window.VOCAB_TERMS = window.VOCAB_TERMS || {};
window.VOCAB_TERMS["pm"] = {"pm--a-b-testing":{"definition":"같은 화면을 두고 의견이 갈릴 때 말로는 끝나지 않는다. 사용자를 무작위로 나눠 한쪽에는 A를, 다른 쪽에는 B를 보여주고 같은 기간의 숫자를 비교한다.","analogy":"같은 국을 두 냄비에 나눠 끓이면서 한쪽만 간을 다르게 해보는 것과 같다.","example":"같은 앱을 켰는데 친구 화면의 버튼 위치가 내 것과 다를 때가 있다. 둘 중 어느 쪽이 나은지 재는 중이다.","tryit":"친구와 같은 앱을 각자 폰에서 같은 화면까지 열고, 먼저 설정에서 앱 버전이 같은지 맞춰 보라. 버전이 같은데도 버튼 자리나 문구가 다르면 둘이 서로 다른 쪽 실험에 들어가 있는 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"두 그룹의 전환율은 어차피 다르게 나온다. 같은 화면을 보여줘도 사람이 달라서 숫자는 늘 흔들린다. 그래서 실험이 묻는 것은 \"차이가 있나\"가 아니라 \"이 정도 차이가 흔들림만으로 나올 수 있나\"다.\n\n이 확률을 p-value라고 한다. 기준을 0.05로 잡으면, 실제로는 아무 차이가 없는데 이만큼 벌어질 확률이 5% 미만일 때만 이겼다고 본다.\n\n표본이 적으면 흔들림이 커서 웬만한 차이는 우연으로 설명된다. 그래서 시작 전에 그룹당 몇 명이 필요한지 계산해두고, 그 수를 채우기 전에는 결과를 보고 멈추지 않는다. 기간도 최소 한 주는 잡는다. 요일마다 오는 사람이 다르기 때문이다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: A/B 테스트와 비슷한 방식들","body":"| | A/B 테스트 | 다변량 테스트 | 밴딧 |\n|---|---|---|---|\n| 나누는 것 | 한 요소, 두 안 | 여러 요소의 조합 | 여러 안 |\n| 트래픽 배분 | 끝까지 고정 | 끝까지 고정 | 잘 되는 쪽으로 옮김 |\n| 필요한 인원 | 적다 | 많다 | 중간 |\n| 쓸 때 | 결론을 남기고 싶을 때 | 요소끼리의 영향을 볼 때 | 빨리 최적화하고 싶을 때 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **버튼과 문구** — 색이나 문장 한 줄만 바꾸고 클릭률을 비교한다. 바꾼 게 하나라서 원인을 지목할 수 있다.\n- **위험한 배포** — 새 결제 흐름을 절반에게만 열어두고, 지표가 떨어지면 그 절반만 되돌린다.\n- **AA 테스트** — 똑같은 화면을 A와 B로 나눠 돌려본다. 여기서 차이가 나오면 실험 장치 자체가 고장 난 것이다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **유의미한 차이가 보이면 바로 끝내도 된다** — 초반 숫자는 크게 흔들린다. 정해둔 표본 수와 기간을 채우기 전에 멈추면 우연을 실력으로 착각하게 된다.\n- **이긴 쪽이 더 좋은 안이다** — 정해둔 지표 하나가 이긴 것이다. 클릭은 늘었는데 구매가 줄었다면, 무엇을 기준으로 삼을지 먼저 정했어야 한다.\n- **A/B 테스트니까 두 개만 비교하는 것이다** — 셋 이상으로도 나눌 수 있다. 다만 그룹이 늘어난 만큼 각 그룹에 필요한 인원도 같이 늘어난다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **지표를 여러 개 걸어두고 하나라도 이기면 성공으로 치지 않는다.** 지표가 많을수록 그중 하나가 우연히 이길 확률도 같이 올라간다.\n- **결과가 나온 다음에 세그먼트(사용자를 조건별로 갈라 본 집단)를 뒤지지 않는다.** \"iOS에서는 이겼다\"는 대개 나중에 찾아낸 것이라 다음 실험에서 재현되지 않는다."}],"figure":"```도해\n흐름: 버튼 색을 바꾸면 정말 나아지는지 어떻게 아나\n가설 :: 초록 버튼이 클릭을 늘린다고 적어둔다\n분배 :: 사용자를 무작위로 절반씩 나눈다\n수집 :: 그룹별 노출 수와 전환 수를 센다\n검정 :: 이 정도 차이가 우연일 확률을 계산한다\n판단 :: 우연이 아니면 이긴 쪽을 전체에 적용한다\n= 이긴 안을 고르는 절차가 아니라, 차이가 우연인지 가르는 절차다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 실험 없이 정하면 무엇이 달라지나\n실험 없이 || A/B 테스트로\n결정 근거 :: 직급 높은 사람 || 전환율 숫자\n실패 비용 :: 전원이 겪는다 || 절반만 겪는다\n되돌리기 :: 이미 늦다 || 바로 되돌린다\n= 누가 옳은지 다투던 자리를 무엇이 옳은지 재는 자리로 바꾼다\n```\n\n새 디자인을 전체 사용자에게 한 번에 적용하면, 그게 나쁜 선택이었다는 걸 지표가 떨어진 다음에야 알게 된다. 이미 모두가 겪은 뒤라 되돌려도 손해는 남는다.\n\n절반에게만 보여주면 나머지 절반이 비교 기준이 된다. 같은 기간, 같은 트래픽에서 잰 숫자이기 때문에 계절이나 광고 때문에 오른 것과 버튼 때문에 오른 것을 구분할 수 있다."},"recap":"**\"반씩 나눠 같은 기간에 재보는 그 실험\"** 이라고 읽으면 된다. 이기는 안을 뽑아주는 도구라기보다, 눈에 보이는 차이가 우연인지 아닌지를 가르는 도구다. 표본 수와 기간과 판단 지표를 시작 전에 정해두지 않으면 숫자는 나와도 결론은 나오지 않는다.","kid":"같은 국을 두 냄비에 똑같이 끓이면서 한쪽에만 소금을 더 넣어 봐. 그리고 사람들을 두 편으로 나눠서 한 편에는 이 냄비 것만, 다른 편에는 저 냄비 것만 주고, 맛있다고 한 사람이 어느 편에 더 많은지 세는 거야. 한 편에 한두 명뿐이면 그날 입맛일 수도 있으니까 양쪽에 아주 많은 사람이 있어야 알 수 있어.","check":[{"q":"시작한 지 하루 만에 B가 앞섰는데 여기서 멈추면 안 되는 이유는","at":"작동 원리"},{"q":"클릭률은 올랐는데 구매가 줄었다면 B가 이겼다고 할 수 있나","at":"흔한 오해"},{"q":"똑같은 화면을 A와 B로 나눠 돌렸는데 차이가 나왔다면 무엇을 의심해야 하나","at":"실제 사례"}],"myths":[{"wrong":"유의미한 차이가 보이면 바로 끝내도 된다","right":"초반 숫자는 크게 흔들린다. 정해둔 표본 수와 기간을 채우기 전에 멈추면 우연을 실력으로 착각하게 된다."},{"wrong":"이긴 쪽이 더 좋은 안이다","right":"정해둔 지표 하나가 이긴 것이다. 클릭은 늘었는데 구매가 줄었다면, 무엇을 기준으로 삼을지 먼저 정했어야 한다."},{"wrong":"A/B 테스트니까 두 개만 비교하는 것이다","right":"셋 이상으로도 나눌 수 있다. 다만 그룹이 늘어난 만큼 각 그룹에 필요한 인원도 같이 늘어난다."}],"cases":[{"label":"버튼과 문구","note":"색이나 문장 한 줄만 바꾸고 클릭률을 비교한다. 바꾼 게 하나라서 원인을 지목할 수 있다."},{"label":"위험한 배포","note":"새 결제 흐름을 절반에게만 열어두고, 지표가 떨어지면 그 절반만 되돌린다."},{"label":"AA 테스트","note":"똑같은 화면을 A와 B로 나눠 돌려본다. 여기서 차이가 나오면 실험 장치 자체가 고장 난 것이다."}],"dia":{"shape":"흐름","title":"버튼 색을 바꾸면 정말 나아지는지 어떻게 아나","rows":[{"who":"가설","what":"초록 버튼이 클릭을 늘린다고 적어둔다"},{"who":"분배","what":"사용자를 무작위로 절반씩 나눈다"},{"who":"수집","what":"그룹별 노출 수와 전환 수를 센다"},{"who":"검정","what":"이 정도 차이가 우연일 확률을 계산한다"},{"who":"판단","what":"우연이 아니면 이긴 쪽을 전체에 적용한다"}],"sum":"이긴 안을 고르는 절차가 아니라, 차이가 우연인지 가르는 절차다"}},"pm--agile":{"definition":"한 번에 다 설계하고 반년 뒤에 내놓으면 그 사이에 바뀐 요구를 담을 자리가 없다. 애자일은 주기를 2주 안팎으로 잘라 매번 돌아가는 것을 내놓고, 거기서 들은 말을 다음 주기에 넣는다.","name":"= 라틴어 agilis(잽싸다)에서 온 말. 가벼워서 가던 방향을 바로 틀 수 있다는 뜻이다","analogy":"요리하면서 계속 간을 보는 것. 다 끓이고 나서 처음 맛보면 고칠 방법이 없다.","example":"앱을 켤 때마다 업데이트 알림이 뜨고 그때마다 화면이 조금씩 달라져 있다. 반년에 한 번 크게 바뀌는 앱은 드물다.","tryit":"앱 스토어에서 자주 쓰는 앱을 열고 '새로운 기능' 기록을 내려 보라. 몇 주 간격으로 조금씩 바뀐 줄이 죽 이어져 있다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"한 바퀴는 목록 하나에서 시작한다. 만들 것을 전부 한 줄로 세워 중요한 순서로 쌓아 두고, 바퀴가 시작될 때 위에서부터 이번에 담을 만큼만 덜어 낸다. 무엇을 뺄지를 매번 다투는 게 아니라, 줄 순서를 미리 정해 두고 자르는 자리만 옮기는 것이다.\n\n덜어 낸 몫은 바퀴가 도는 동안 잠근다. 급한 일이 생기면 다음 바퀴 줄 맨 위로 올리지 이번 바퀴에 끼워 넣지 않는다. 끼워 넣기 시작하면 이번에 무엇이 끝나는지를 아무도 말할 수 없게 되고, 끝에 보여줄 돌아가는 것이 안 나온다.\n\n바퀴가 끝나면 두 가지를 잰다. 담은 것 중 실제로 끝난 양이 하나고, 시연에서 들은 말이 다른 하나다. 앞엣것은 다음 바퀴에 얼마나 담을지를 정하고, 뒤엣것은 무엇을 담을지를 정한다. 기간을 2주로 못 박아 두는 까닭이 여기 있다 — 바퀴마다 기간이 다르면 지난번에 잰 양을 이번에 쓸 수 없다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| | Waterfall | Agile |\n|---|---|---|\n| 주기 | 한 번에 끝까지 | 2주 안팎으로 반복 |\n| 요구 변경 | 착수 후에는 어렵다 | 다음 주기에 반영 |\n| 결과물 | 마지막에 한 번 | 주기마다 돌아가는 것 |\n| 계획 | 처음에 전부 세운다 | 주기마다 다시 세운다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **스크럼 팀** — 2주 단위로 목표를 정하고, 끝나면 만든 것을 보여주고 다음 목표를 다시 정한다.\n- **칸반 보드** — 주기를 나누지 않고 일이 들어오는 대로 흘려보내되, 동시에 진행하는 일의 개수를 제한한다.\n- **XP** — 테스트를 먼저 쓰고 둘이 한 화면을 보며 짜는 식으로, 언제든 고칠 수 있는 코드 상태를 유지한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **애자일은 계획을 안 세우는 것이다** — 계획을 자주 세우는 것이다. 한 번 세운 계획을 끝까지 안 고치는 쪽이 오히려 계획에 덜 신경 쓰는 편이다.\n- **문서를 안 써도 된다** — 애자일 선언문은 문서보다 돌아가는 소프트웨어를 앞에 둔다고 했지 문서를 버리라고 하지 않았다. 아무도 안 읽는 문서를 줄이라는 뜻이다.\n- **스크럼을 쓰면 애자일이다** — 스크럼은 애자일을 실천하는 방법 중 하나다. 매일 서서 회의만 하고 방향을 못 바꾸면 이름만 애자일이다."}],"figure":"```도해\n흐름: 2주짜리 한 바퀴 안에서 무슨 일이 일어나나\n계획 :: 이번에 만들 것 몇 개만 고른다\n개발 :: 2주 동안 그것만 만든다\n시연 :: 돌아가는 것을 직접 보여준다\n피드백 :: 쓰는 사람이 보고 말한다\n@ 계획 :: 들은 말을 다음 바퀴 목록에 넣고 다시 돈다\n= 한 바퀴가 끝날 때마다 돌아가는 것이 하나씩 늘어난다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 다 만든 다음에 처음 보여주면 어떻게 되나\n한 번에 || 여러 바퀴로\n요구 변경 :: 반영 못 한다 || 다음 바퀴에 넣는다\n잘못된 방향 :: 끝나야 안다 || 2주 만에 안다\n안 쓰는 기능 :: 다 만들고 버린다 || 만들기 전에 뺀다\n= 늦게 아는 것과 일찍 아는 것의 차이다\n```\n\n계획을 처음에 다 세우는 방식은 요구가 안 바뀐다는 전제 위에 서 있다. 실제로는 만드는 도중에 시장도 바뀌고 쓰는 사람의 생각도 바뀐다. 다 만들고 나서야 방향이 틀렸다는 걸 알면 되돌릴 시간이 남아 있지 않다.\n\n애자일은 틀렸다는 사실을 빨리 알아내는 쪽을 택한다. 2주마다 돌아가는 것을 내놓으면 그때마다 방향을 확인할 기회가 생긴다. 그 대신 문서와 계획이 자주 다시 쓰인다."},"recap":"**\"짧게 잘라 매번 보여주고 고치는 그 방식\"** 이라고 읽으면 된다. 2주 안팎의 한 바퀴마다 돌아가는 것을 내놓고 거기서 들은 말을 다음 바퀴에 넣으니, 방향이 틀렸다는 사실을 반년이 아니라 2주 만에 알게 된다. 계획을 버리는 게 아니라 계획을 고칠 기회를 자주 만드는 쪽이다.","kid":"국을 다 끓이고 나서 처음 맛봤는데 너무 짜면 어쩔 수가 없지? 그래서 끓이는 동안 조금씩 떠먹어 보고 그때그때 소금을 더 넣거나 물을 붓는 거야. 무언가를 만들 때도 조금 만들어서 먼저 보여주고, 아니다 싶으면 바로 고쳐.","check":[{"q":"요구가 도중에 바뀌었을 때 한 번에 다 만드는 방식이 곤란해지는 이유는","at":"해결하는 문제"},{"q":"시연에서 쓰는 사람이 한 말은 그다음에 어디로 가나","at":"그림"},{"q":"매일 회의를 하는데도 애자일이 아니라고 할 수 있는 경우는","at":"흔한 오해"}],"myths":[{"wrong":"애자일은 계획을 안 세우는 것이다","right":"계획을 자주 세우는 것이다. 한 번 세운 계획을 끝까지 안 고치는 쪽이 오히려 계획에 덜 신경 쓰는 편이다."},{"wrong":"문서를 안 써도 된다","right":"애자일 선언문은 문서보다 돌아가는 소프트웨어를 앞에 둔다고 했지 문서를 버리라고 하지 않았다. 아무도 안 읽는 문서를 줄이라는 뜻이다."},{"wrong":"스크럼을 쓰면 애자일이다","right":"스크럼은 애자일을 실천하는 방법 중 하나다. 매일 서서 회의만 하고 방향을 못 바꾸면 이름만 애자일이다."}],"cases":[{"label":"스크럼 팀","note":"2주 단위로 목표를 정하고, 끝나면 만든 것을 보여주고 다음 목표를 다시 정한다."},{"label":"칸반 보드","note":"주기를 나누지 않고 일이 들어오는 대로 흘려보내되, 동시에 진행하는 일의 개수를 제한한다."},{"label":"XP","note":"테스트를 먼저 쓰고 둘이 한 화면을 보며 짜는 식으로, 언제든 고칠 수 있는 코드 상태를 유지한다."}],"dia":{"shape":"흐름","title":"2주짜리 한 바퀴 안에서 무슨 일이 일어나나","rows":[{"who":"계획","what":"이번에 만들 것 몇 개만 고른다"},{"who":"개발","what":"2주 동안 그것만 만든다"},{"who":"시연","what":"돌아가는 것을 직접 보여준다"},{"who":"피드백","what":"쓰는 사람이 보고 말한다"}],"sum":"한 바퀴가 끝날 때마다 돌아가는 것이 하나씩 늘어난다","loop":{"who":"계획","what":"들은 말을 다음 바퀴 목록에 넣고 다시 돈다"}}},"pm--backlog":{"definition":"여러 곳에서 요청이 들어오면 무엇을 먼저 할지 매번 다시 다투게 된다. 백로그는 그 다툼을 한 목록 위로 옮겨서, 새 요청이 오면 목록의 몇 번째 자리에 놓을지만 정하게 만든다.","name":"Back :: 밀려 있는\nLog :: 적어 둔 줄\n= 붙여 읽으면 \"밀려 있는 일을 적어 둔 줄\". 쌓인 것을 버리지 않고 세워 둔다는 뜻이다","analogy":"식당의 주문 대기표. 번호 순으로 나가고 새 주문은 뒤에 붙는다.","example":"앱에 기능을 건의하면 검토하겠다는 답만 오고 반년 뒤에 그게 생기기도 한다. 그 반년 동안 건의는 이 목록 어딘가에 있었다.","tryit":"메모 앱에 지금 안 해도 되는 일을 열 줄 적고 급한 순으로 다시 세워 보라. 아래 몇 줄은 이번 주에 손도 못 댄다는 것이 바로 보인다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"목록에 올라온 항목은 그대로 개발에 들어가지 않는다. 무엇을 만들면 끝난 것으로 볼지, 다른 항목에 걸려 있지 않은지를 채워 넣는 과정을 거친다. 이 과정을 정제라고 부르고, 여기를 건너뛰면 주기 중간에 질문이 쏟아진다.\n\n순서를 정할 때는 영향받는 사람 수와 드는 노력을 함께 본다. 노력 대비 효과가 큰 항목을 위로 올리는 식이고, 노력을 빼고 효과만 보면 모든 항목이 다 중요해진다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **여러 부서의 요청** — 영업과 마케팅에서 온 요청을 같은 목록에 넣고 자리를 비교해 순서를 정한다.\n- **회의에서 나온 아이디어** — 지금 안 할 것도 항목으로 남겨두면 몇 달 뒤에 다시 꺼낼 수 있다.\n- **주기 시작 회의** — 위에서부터 팀이 감당할 만큼만 꺼내 이번 주기 목록으로 옮긴다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **백로그에 있으면 언젠가는 한다** — 아래쪽 항목은 대부분 영영 안 한다. 안 할 것을 계속 담아두면 목록을 볼 때마다 훑어야 할 줄만 늘어난다.\n- **항목이 많을수록 좋은 백로그다** — 수백 개가 쌓이면 순서를 매기는 일 자체가 불가능해진다. 정기적으로 지우는 것도 관리에 포함된다.\n- **우선순위는 정해두면 끝난다** — 상황이 바뀌면 순서도 바뀐다. 한 번 정한 순서를 안 건드리면 목록은 그냥 오래된 기록이 된다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **전부 P0(가장 급한 등급)으로 매기면 우선순위가 없는 것과 같다.** 가장 높은 등급은 몇 개로 제한해야 뜻이 생긴다.\n- **제목만 있는 항목은 꺼낼 수 없다.** \"시스템 개선\" 같은 줄은 정제 단계에서 무엇을 만들지 정하지 않으면 계속 아래에 남는다."}],"figure":"```도해\n흐름: 아이디어 하나가 백로그에 들어오면 어디까지 가나\n접수 :: 누구든 항목을 적어 넣는다\n정제 :: 무엇을 만들지 조건을 채운다\n우선순위 :: 위아래 자리를 다시 정한다\n선정 :: 이번 주기에 할 만큼만 위에서 꺼낸다\n완료 :: 끝난 항목은 목록에서 내려간다\n= 줄서기가 아니라 순서가 계속 바뀌는 대기열이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 할 일을 한 목록에 모아두지 않으면 어떻게 되나\n목록 없이 || 백로그로\n요청 처리 :: 목소리 큰 순 || 우선순위 순\n나온 아이디어 :: 회의 끝나면 증발 || 항목으로 남는다\n진행 상황 :: 물어봐야 안다 || 목록을 보면 안다\n= 무엇을 먼저 할지 정하는 자리를 한 군데로 모으는 것이다\n```\n\n요청이 사람마다 다른 경로로 들어오면 개발자는 매번 누구 말을 들어야 할지 판단하게 된다. 그 판단은 사실 개발자가 할 일이 아니고, 아무도 전체를 못 보는 상태에서 내려진다.\n\n백로그는 모든 요청을 한 줄로 세워 비교하게 만든다. 급하다는 말끼리 나란히 놓이면 정말 급한 것이 어느 쪽인지 정할 수 있다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 백로그는 어느 범위까지 담고 있나\n제품 백로그 :: 언젠가 할 것 전부. 계속 바뀐다\n꺼낼 후보 :: 조건이 채워져 바로 꺼낼 수 있는 것\n스프린트 백로그 :: 이번 주기에 하기로 한 것. 중간에 안 바꾼다\n= 아래로 갈수록 개수는 줄고 적힌 내용은 자세해진다\n```"},"recap":"**\"밀린 일을 한 줄로 세워 둔 그 목록\"** 이라고 읽으면 된다. 무엇을 먼저 할지 정하는 판단이 한 자리로 모이니, 새 요청이 와도 다투는 대신 목록의 몇 번째에 놓을지만 정하면 된다. 그 순서는 상황에 따라 계속 다시 매긴다.","kid":"식당에 사람이 많으면 번호표를 뽑고 기다리지? 할 일도 그렇게 줄을 세워 두는데, 이 줄은 더 급한 게 오면 앞으로 끼어들 수 있어. 그래서 뒤쪽에 오래 서 있던 것은 차례가 끝내 안 오기도 해.","check":[{"q":"여러 부서가 각자 \"급하다\"고 할 때 백로그가 하는 일은 무엇인가","at":"해결하는 문제"},{"q":"항목이 500개까지 쌓이면 무엇이 안 되기 시작하나","at":"흔한 오해"},{"q":"제품 백로그와 스프린트 백로그 중 주기 도중에 바뀌지 않는 쪽은 어디인가","at":"구성"}],"myths":[{"wrong":"백로그에 있으면 언젠가는 한다","right":"아래쪽 항목은 대부분 영영 안 한다. 안 할 것을 계속 담아두면 목록을 볼 때마다 훑어야 할 줄만 늘어난다."},{"wrong":"항목이 많을수록 좋은 백로그다","right":"수백 개가 쌓이면 순서를 매기는 일 자체가 불가능해진다. 정기적으로 지우는 것도 관리에 포함된다."},{"wrong":"우선순위는 정해두면 끝난다","right":"상황이 바뀌면 순서도 바뀐다. 한 번 정한 순서를 안 건드리면 목록은 그냥 오래된 기록이 된다."}],"cases":[{"label":"여러 부서의 요청","note":"영업과 마케팅에서 온 요청을 같은 목록에 넣고 자리를 비교해 순서를 정한다."},{"label":"회의에서 나온 아이디어","note":"지금 안 할 것도 항목으로 남겨두면 몇 달 뒤에 다시 꺼낼 수 있다."},{"label":"주기 시작 회의","note":"위에서부터 팀이 감당할 만큼만 꺼내 이번 주기 목록으로 옮긴다."}],"dia":{"shape":"흐름","title":"아이디어 하나가 백로그에 들어오면 어디까지 가나","rows":[{"who":"접수","what":"누구든 항목을 적어 넣는다"},{"who":"정제","what":"무엇을 만들지 조건을 채운다"},{"who":"우선순위","what":"위아래 자리를 다시 정한다"},{"who":"선정","what":"이번 주기에 할 만큼만 위에서 꺼낸다"},{"who":"완료","what":"끝난 항목은 목록에서 내려간다"}],"sum":"줄서기가 아니라 순서가 계속 바뀌는 대기열이다"}},"pm--cac-ltv":{"definition":"두 숫자를 나란히 놓아야 지금 성장이 돈을 버는 성장인지 알 수 있다. 가입자 수만 보면 고객이 늘수록 적자가 커지는 구조를 몇 달 동안 못 알아챈다.","name":"Customer Acquisition Cost :: 한 명 데려온 값\nLifetime Value :: 평생 남기는 값\n= 앞은 나가는 돈, 뒤는 들어오는 돈. 나란히 놓아야 비로소 뜻이 생기는 짝이다","analogy":"전단지 값과 그 손님이 평생 사 갈 금액. 전단지에 든 돈이 더 크면 손님이 늘어날수록 손해다.","example":"가입만 하면 만 원 쿠폰을 주는 서비스가 있다. 그 만 원보다 내가 평생 쓸 돈이 커야 남는 장사다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"CAC 는 획득에 들어간 돈을 그 기간에 새로 온 고객 수로 나눈다. 마케팅비 1천만 원과 영업비 5백만 원을 써서 500명을 데려왔다면 CAC 는 3만 원이다.\n\nLTV 는 두 가지 방식으로 잡는다. 거래형이면 평균 구매액 곱하기 구매 빈도 곱하기 유지 기간이고, 구독형이면 월 평균 수익에 마진율을 곱하고 이탈률로 나눈다. 월 1만 원, 마진 80%, 월 이탈 5% 면 LTV 는 16만 원이고 평균 유지 기간은 20개월이다.\n\n```도해\n층: LTV 를 CAC 로 나눈 값은 무엇을 말해주나\n3배 이상 :: 마케팅에 더 써도 되는 구간\n1배에서 3배 :: 남기는 하지만 효율을 손봐야 한다\n1배 미만 :: 고객이 늘수록 적자가 커진다\n= 같은 CAC 여도 LTV 가 얼마냐에 따라 정반대의 결정이 나온다\n```\n\n이탈률이 분모에 있다는 점이 중요하다. 월 이탈 5% 를 3% 로 낮추면 다른 값이 그대로여도 LTV 가 크게 오른다. 그래서 유지 개선이 광고 효율 개선보다 크게 먹히는 경우가 많다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **채널 정리** — 채널별로 CAC 를 따로 계산해 비싼 쪽을 줄이고 싼 쪽에 옮긴다.\n- **가격 인상 판단** — 월 요금을 올리면 이탈률이 얼마나 오르는지를 LTV 변화로 환산해 본다.\n- **투자 유치** — 회수 기간과 배수를 보여주는 것이 가입자 수 그래프보다 설득력이 있다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **CAC 는 광고비를 신규 고객 수로 나눈 값이다** — 광고비만 넣으면 실제보다 작게 나온다. 영업 인건비와 도구 비용까지 넣어야 맞는 숫자다.\n- **LTV 가 CAC 보다 크면 괜찮다** — 크기만으로는 부족하다. 회수에 2년이 걸리면 그 사이에 쓸 현금이 먼저 마른다.\n- **LTV 는 고객이 쓴 총 금액이다** — 매출이 아니라 마진 기준으로 잡아야 한다. 원가를 빼지 않으면 실제보다 부풀려진다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **평균 하나로 뭉치지 않는다.** 채널마다 CAC 가 다르고 요금제마다 LTV 가 다르다. 뭉치면 어느 쪽이 손해인지 안 보인다.\n- **아직 이탈하지 않은 고객의 LTV 는 추정치다.** 서비스가 1년밖에 안 됐는데 3년 유지를 가정하면 숫자가 소설이 된다."}],"figure":"```도해\n흐름: 고객 한 명이 들어와서 나갈 때까지 돈은 어떻게 움직이나\n광고비 :: 먼저 나간다. 아직 들어온 돈은 없다\n가입 :: 이 사람에게 쓴 돈이 CAC 로 확정된다\n첫 결제 :: 들어오기 시작한다. 아직 회수 전이다\n회수 :: 누적 수익이 CAC 를 넘어서는 시점\n이탈 :: 여기까지 쌓인 금액이 LTV 다\n판단 :: LTV 가 CAC 의 3배쯤이면 더 써도 된다\n= 고객이 늘고 있다는 사실만으로는 돈을 벌고 있는지 알 수 없다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 두 숫자를 안 보면 무엇을 놓치나\n안 볼 때 || 볼 때\n성장 판단 :: 가입자만 센다 || 회수까지 본다\n마케팅 예산 :: 감으로 늘린다 || 배수로 정한다\n적자 발견 :: 몇 달 뒤 || 첫 달에\n= 고객이 늘수록 손해인 구조는 매출만 봐서는 보이지 않는다\n```\n\n한 명 데려오는 데 5만 원을 쓰는데 그 사람이 평생 3만 원을 쓴다면, 마케팅을 잘할수록 손해가 커진다. 매출 그래프는 계속 오르기 때문에 겉으로는 성장으로 보인다.\n\nCAC 와 LTV 는 그 착시를 걷어낸다. 두 값의 비율이 마케팅에 더 써도 되는지를 정하고, 회수까지 걸리는 기간이 지금 쓸 수 있는 현금을 정한다."},"recap":"**\"한 명 데려오는 값과 그 한 명이 남기는 값\"** 이라고 읽으면 된다. 둘의 비율이 마케팅을 더 써도 되는지를 정하고, 회수 기간이 그 사이 버틸 현금을 정한다. 가입자 수만 보면 늘수록 손해인 구조를 알아채지 못한다.","kid":"손님을 부르려고 전단지를 돌린다고 해 봐. 전단지 만드는 데 든 돈보다 그 손님이 두고두고 사 갈 돈이 더 커야 남는 거야. 아니면 손님이 늘어날수록 오히려 손해가 커져.","check":[{"q":"신규 가입자가 매달 늘고 있는데 이익은 줄고 있다. 무엇을 계산해 봐야 하나","at":"해결하는 문제"},{"q":"LTV 와 CAC 가 똑같은 두 회사가 있는데 한 곳만 현금이 마른다. 무엇이 다른가","at":"흔한 오해"},{"q":"월 이탈률을 5% 에서 3% 로 낮추면 LTV 는 왜 움직이나","at":"작동 원리"}],"myths":[{"wrong":"CAC 는 광고비를 신규 고객 수로 나눈 값이다","right":"광고비만 넣으면 실제보다 작게 나온다. 영업 인건비와 도구 비용까지 넣어야 맞는 숫자다."},{"wrong":"LTV 가 CAC 보다 크면 괜찮다","right":"크기만으로는 부족하다. 회수에 2년이 걸리면 그 사이에 쓸 현금이 먼저 마른다."},{"wrong":"LTV 는 고객이 쓴 총 금액이다","right":"매출이 아니라 마진 기준으로 잡아야 한다. 원가를 빼지 않으면 실제보다 부풀려진다."}],"cases":[{"label":"채널 정리","note":"채널별로 CAC 를 따로 계산해 비싼 쪽을 줄이고 싼 쪽에 옮긴다."},{"label":"가격 인상 판단","note":"월 요금을 올리면 이탈률이 얼마나 오르는지를 LTV 변화로 환산해 본다."},{"label":"투자 유치","note":"회수 기간과 배수를 보여주는 것이 가입자 수 그래프보다 설득력이 있다."}],"dia":{"shape":"흐름","title":"고객 한 명이 들어와서 나갈 때까지 돈은 어떻게 움직이나","rows":[{"who":"광고비","what":"먼저 나간다. 아직 들어온 돈은 없다"},{"who":"가입","what":"이 사람에게 쓴 돈이 CAC 로 확정된다"},{"who":"첫 결제","what":"들어오기 시작한다. 아직 회수 전이다"},{"who":"회수","what":"누적 수익이 CAC 를 넘어서는 시점"},{"who":"이탈","what":"여기까지 쌓인 금액이 LTV 다"},{"who":"판단","what":"LTV 가 CAC 의 3배쯤이면 더 써도 된다"}],"sum":"고객이 늘고 있다는 사실만으로는 돈을 벌고 있는지 알 수 없다"}},"pm--crm":{"definition":"영업, 지원, 마케팅이 각자 다른 파일로 고객을 관리하면 같은 사람에게 두 번 연락하고, 누가 언제 무슨 말을 했는지 아무도 모르게 된다. CRM은 그 기록을 한 군데로 모으고, 다음에 누구를 먼저 볼지 정하는 데 쓴다.","name":"Customer :: 고객\nRelationship :: 주고받은 사이\nManagement :: 챙겨 다루기\n= 붙여 읽으면 \"고객과 주고받은 사이를 챙겨 다루기\". 명단이 아니라 사이가 대상이다","analogy":"단골 가게 주인의 기억. 지난번에 뭘 샀고 무슨 말을 했는지 알고 있어서 다시 묻지 않는다.","example":"장바구니에 담아두고 며칠 지나면 아직 고민 중이냐는 메일이 온다. 내가 어디서 멈췄는지가 어딘가에 남아 있다는 뜻이다.","tryit":"메일함에서 지난달에 주문한 가게 이름을 검색해 보라. 주문 확인, 배송, 그 뒤의 권유가 한 사람 앞으로 줄줄이 이어져 있다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"리드 스코어링은 아직 고객이 아닌 사람에게 점수를 매기는 일이다. 회사 규모, 직급, 최근에 메일을 열었는지 같은 것을 더해 숫자 하나로 만들고, 그 순서대로 연락한다.\n\n파이프라인은 진행 중인 거래를 단계로 늘어놓은 것이다. 리드에서 시작해 검증, 제안, 협상을 거쳐 성사나 실패로 끝난다. 단계마다 성사 확률을 정해두면 진행 중인 건들의 금액을 확률로 눌러 예상 매출을 낼 수 있다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **연락 순서 정하기** — 남은 잠재 고객이 백 명이면 점수가 높은 쪽부터 연락한다.\n- **후속 조치 자동화** — 며칠 동안 연락이 끊긴 건에 안내 메일이 자동으로 나가고, 담당자에게도 알림이 간다.\n- **예상 매출 보기** — 단계별 확률을 곱해 지금 진행 중인 건들이 얼마가 될지 미리 본다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **CRM 은 고객 명단을 넣어두는 주소록이다** — 이름과 번호만 들어 있으면 안 넣은 것과 같다. 언제 무슨 말이 오갔고 지금 어느 단계인지가 있어야 판단에 쓰인다.\n- **CRM 을 도입하면 매출이 오른다** — 도구가 파는 것이 아니다. 팀이 기록을 안 남기기 시작하면 그날로 예전 파일 관리로 돌아간다.\n- **영업팀만 쓰는 시스템이다** — 지원팀이 받은 불만도, 마케팅이 보낸 메일도 같은 고객의 이력이다. 한쪽만 쓰면 그 고객의 절반만 보인다."}],"figure":"```도해\n흐름: 문의 하나가 계약이 될 때까지 무엇이 남나\n접점 :: 메일, 전화, 문의 폼으로 사람이 들어온다\n연락처 :: 같은 사람이면 기존 기록에 붙인다\n점수 :: 회사 규모나 반응으로 순위를 매긴다\n거래 :: 제안, 협상 같은 단계를 옮겨 적는다\n결과 :: 성사와 실패를 남겨 다음 판단에 쓴다\n= 흩어진 접점을 한 사람의 이력으로 묶는 것이 CRM 이 하는 일이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 고객 기록이 팀마다 흩어져 있으면 어떻게 되나\nCRM 없이 || CRM 으로\n같은 고객 :: 팀마다 따로 봄 || 한 사람으로 봄\n연락 순서 :: 눈에 띄는 순 || 점수 높은 순\n담당자 교체 :: 이력이 사라짐 || 기록이 남는다\n= 사람이 기억하던 것을 시스템이 기억하게 만드는 일이다\n```\n\n영업팀은 엑셀에, 지원팀은 다른 도구에 고객을 적어두면 두 곳 어디에도 그 고객의 전체 그림이 없다. 어제 불만을 접수한 고객에게 오늘 신규 제안 메일이 나가는 일이 여기서 생긴다.\n\n기록이 한곳에 모이면 판단 기준도 생긴다. 잠재 고객이 백 명일 때 누구부터 연락할지, 어느 건이 어느 단계에 멈춰 있는지가 사람의 감이 아니라 남은 기록으로 정해진다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: CRM 은 무엇을 쌓아 올린 것인가\n행동 :: 자동 발송, 담당자 배정, 리포트\n판단 :: 점수와 단계. 누구를 먼저 볼지 정한다\n고객 정보 :: 연락처 하나로 묶인 이력과 상태\n접점 데이터 :: 메일, 통화, 웹 방문, 문의 기록\n= 아래가 쌓이지 않으면 위는 전부 감으로 돌아간다\n```"},"recap":"**\"고객 한 사람의 이력을 한곳에 쌓아 두는 그 장부\"** 라고 읽으면 된다. 쌓인 기록 위에서 누구를 먼저 볼지, 어느 거래가 어디에 멈춰 있는지를 정한다. 기록이 들어가지 않으면 화면만 남는다.","kid":"동네 분식집 아주머니는 네가 지난번에 뭘 시켰고 뭘 남겼는지 기억하고 있지? 그래서 다시 묻지 않고 오늘 뭘 권할지도 바로 알아. 가게가 커져서 혼자 다 못 외우게 되면 그 기억을 공책에 옮겨 적어서, 누가 나와도 똑같이 알게 만드는 거야.","check":[{"q":"어제 불만을 접수한 고객에게 오늘 제안 메일이 나가는 일은 왜 생기나","at":"해결하는 문제"},{"q":"잠재 고객이 백 명일 때 누구부터 연락할지 무엇을 보고 정하나","at":"작동 원리"},{"q":"이름과 전화번호만 채워 둔 CRM 이 안 넣은 것과 같아지는 이유는","at":"흔한 오해"}],"myths":[{"wrong":"CRM 은 고객 명단을 넣어두는 주소록이다","right":"이름과 번호만 들어 있으면 안 넣은 것과 같다. 언제 무슨 말이 오갔고 지금 어느 단계인지가 있어야 판단에 쓰인다."},{"wrong":"CRM 을 도입하면 매출이 오른다","right":"도구가 파는 것이 아니다. 팀이 기록을 안 남기기 시작하면 그날로 예전 파일 관리로 돌아간다."},{"wrong":"영업팀만 쓰는 시스템이다","right":"지원팀이 받은 불만도, 마케팅이 보낸 메일도 같은 고객의 이력이다. 한쪽만 쓰면 그 고객의 절반만 보인다."}],"cases":[{"label":"연락 순서 정하기","note":"남은 잠재 고객이 백 명이면 점수가 높은 쪽부터 연락한다."},{"label":"후속 조치 자동화","note":"며칠 동안 연락이 끊긴 건에 안내 메일이 자동으로 나가고, 담당자에게도 알림이 간다."},{"label":"예상 매출 보기","note":"단계별 확률을 곱해 지금 진행 중인 건들이 얼마가 될지 미리 본다."}],"dia":{"shape":"흐름","title":"문의 하나가 계약이 될 때까지 무엇이 남나","rows":[{"who":"접점","what":"메일, 전화, 문의 폼으로 사람이 들어온다"},{"who":"연락처","what":"같은 사람이면 기존 기록에 붙인다"},{"who":"점수","what":"회사 규모나 반응으로 순위를 매긴다"},{"who":"거래","what":"제안, 협상 같은 단계를 옮겨 적는다"},{"who":"결과","what":"성사와 실패를 남겨 다음 판단에 쓴다"}],"sum":"흩어진 접점을 한 사람의 이력으로 묶는 것이 CRM 이 하는 일이다"}},"pm--churn-rate":{"definition":"떠난 사람 수만 말하면 규모를 알 수 없다. 천 명 중 백 명과 만 명 중 백 명은 같은 백 명이 아니다. 그래서 떠난 수를 남아 있던 수로 나눠 비율로 적는다. 어려운 자리는 나누는 수를 무엇으로 잡느냐이고, 문서마다 그 답이 다르다.","name":"Churn :: 휘저어 섞다\nRate :: 몇 분의 몇\n= 붙여 읽으면 \"명단이 얼마나 휘저어졌나\". 들고 나며 뒤바뀐 몫을 가리킨다","analogy":"학기 초에 백 명이던 동아리 명부에서 학기가 끝날 때까지 지워진 이름의 몫이다.","example":"구독을 끊으려다 \"정말 해지하시겠어요\" 화면을 세 번 지나본 적이 있다. 그 화면들이 붙잡으려는 것이 이 숫자다.","tryit":"폰의 구독 목록을 열어 반년 동안 한 번도 안 쓴 것을 세어 보라. 그쪽 명부에는 아직 안 지워진 이름들이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"산식은 한 줄이다. 떠난 수를 무언가로 나눈다. 실제로 값을 가르는 것은 그 무언가다.\n\nStripe 의 Billing 문서는 구독자 이탈률을 최근 30일 동안 이탈한 구독자 수를, 30일 전의 활성 구독자 수에 최근 30일 동안 새로 들어온 구독자 수를 더한 값으로 나눈 것이라고 적는다. 문서가 붙여 둔 예가 이 선택의 무게를 보여준다. 월초 구독자 1000명, 그달에 100명이 새로 들어오고 100명이 떠났다면 이탈률은 100 / 1100 = 9.1% 다. 같은 100명을 두고 분모를 1000으로 잡으면 10% 가 된다. 사건은 하나인데 값이 둘이다.\n\n\"떠났다\" 를 무엇으로 볼지도 사람이 정한다. Stripe 는 한 구독자의 구독이 전부 취소되거나 미납으로 표시되면 이탈로 세고, 월 반복 매출(그 구독자가 다달이 내는 금액)이 0으로 떨어져도 이탈로 센다. 그래서 100% 할인 쿠폰이 붙은 구독자는 이탈로 잡히고, 쿠폰을 떼면 다시 활성으로 돌아온다.\n\n정기 구독이 아니면 취소라는 사건 자체가 없다. Dynamics 365 Customer Insights 의 거래 이탈 예측은 며칠 동안 구매가 없어야 이탈로 볼지를 사람이 숫자로 입력하게 하고, 그 기간을 이탈 창이라고 부른다. 같은 문서는 해마다 열리는 행사를 파는 곳과 주 단위로 파는 곳이 이탈을 서로 다른 시간 단위로 정의한다고 적는다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **요금제별로 나눠 보기** — 전체 값은 그대로인데 한 요금제에서만 크게 빠지는 일이 흔하다. 나눠 세야 어디를 손볼지가 정해진다.\n- **결제 실패로 빠진 사람** — 마음이 떠난 것이 아니라 카드가 만료된 경우다. Stripe 는 미납으로 표시된 구독도 이탈로 세므로, 둘을 갈라 보지 않으면 엉뚱한 곳을 고치게 된다.\n- **생애 가치의 입력값** — Stripe 문서는 구독자 생애 가치를 사용자당 평균 매출을 구독자 이탈률로 나눠 구한다. 이탈률이 흔들리면 그 값도 같이 흔들린다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **해지 버튼을 누른 사람만 이탈이다** — 스스로 끊은 사람만이 아니다. Stripe 는 미납으로 표시된 구독도, 할인 때문에 매출이 0이 된 구독자도 그 기간의 이탈로 센다.\n- **이탈률이 내려갔으면 덜 떠난 것이다** — 아니다. Stripe 의 산식은 분모에 그 기간의 신규 구독자를 더하므로, 떠난 수가 지난달과 똑같아도 신규가 늘면 값이 내려간다.\n- **이탈률 하나로 회사끼리 비교할 수 있다** — 재는 창과 분모가 문서마다 다르다. Stripe 는 최근 30일을 굴려 재고 분모에 신규를 더하지만, 정기 구독이 아닌 곳은 며칠 동안 구매가 없어야 이탈인지부터 직접 정한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **분모를 먼저 물어라.** 같은 이름이라도 시작 인원만 쓰는 곳과 기간 중 신규까지 더하는 곳이 있다. 값을 받기 전에 어느 쪽인지 확인한다.\n- **작은 무리에서는 값이 튄다.** 스무 명이 쓰는 요금제에서 한 명이 나가면 5% 다. 잘게 나눠 볼수록 분모가 작아진다는 것을 같이 본다."}],"figure":"```도해\n흐름: 이탈률은 무엇을 무엇으로 나눈 값인가\n기간 정하기 :: 30일처럼 잴 구간을 먼저 못 박는다\n분모 세기 :: 그 구간에 명단에 있던 사람을 센다\n분자 세기 :: 그 구간에 명단에서 빠진 사람을 센다\n나누기 :: 빠진 수를 명단 수로 나눈다\n= 한 구간에서 빠져나간 사람의 몫이다. 구간과 분모를 정하는 것이 절반이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 인원 수만 세면 무엇을 놓치나\n인원 수만 || 이탈률까지\n같은 1000명 :: 변화가 없어 보임 || 200명 바뀐 게 보임\n새 유입 :: 구멍을 덮는다 || 구멍이 드러난다\n고칠 자리 :: 짐작만 한다 || 떠나는 때가 보임\n= 총원이 같아도 그 안에서 몇 명이 갈렸는지는 전혀 다를 수 있다\n```\n\n총원은 들어온 수와 나간 수를 더한 결과라서, 둘 다 크든 둘 다 작든 같은 숫자가 나온다. 이 값만 보면 매달 다섯 명 중 한 명을 새로 채워 넣고 있다는 사실이 끝까지 안 보인다.\n\n이탈률은 나가는 쪽만 따로 떼어 비율로 적는다. 그러면 데려오는 일과 붙잡는 일이 서로 다른 숫자로 갈라지고, 마케팅을 멈춘 다음 달을 기다리지 않고도 새는 정도를 잴 수 있다."},"recap":"**\"한 구간에서 빠져나간 사람의 몫\"** 이라고 읽으면 된다. 값을 보기 전에 두 가지를 먼저 묻는다 — 어느 구간을 쟀나, 그리고 무엇으로 나눴나. 같은 100명이 떠나도 분모에 신규를 더하느냐 마느냐로 10% 와 9.1% 가 갈린다.","kid":"학기 초에 동아리에 백 명이 있었는데 학기가 끝날 때 스무 명이 이름을 지웠다고 해 봐. 그러면 다섯 명 중 한 명이 나간 거야. 새로 들어온 애들 때문에 인원이 그대로면 나간 걸 아무도 눈치 못 채니까, 나간 사람만 따로 세는 거야.","check":[{"q":"1000명으로 시작한 달에 100명이 들어오고 100명이 나갔는데 왜 10%가 아니라 9.1%로 적히나","at":"작동 원리"},{"q":"떠난 사람 수가 지난달과 똑같은데 이탈률이 내려갔다면 무슨 일이 있었나","at":"흔한 오해"},{"q":"다른 회사가 발표한 이탈률을 우리 값과 나란히 놓기 전에 무엇을 확인해야 하나","at":"주의사항"}],"myths":[{"wrong":"해지 버튼을 누른 사람만 이탈이다","right":"스스로 끊은 사람만이 아니다. Stripe 는 미납으로 표시된 구독도, 할인 때문에 매출이 0이 된 구독자도 그 기간의 이탈로 센다."},{"wrong":"이탈률이 내려갔으면 덜 떠난 것이다","right":"아니다. Stripe 의 산식은 분모에 그 기간의 신규 구독자를 더하므로, 떠난 수가 지난달과 똑같아도 신규가 늘면 값이 내려간다."},{"wrong":"이탈률 하나로 회사끼리 비교할 수 있다","right":"재는 창과 분모가 문서마다 다르다. Stripe 는 최근 30일을 굴려 재고 분모에 신규를 더하지만, 정기 구독이 아닌 곳은 며칠 동안 구매가 없어야 이탈인지부터 직접 정한다."}],"cases":[{"label":"요금제별로 나눠 보기","note":"전체 값은 그대로인데 한 요금제에서만 크게 빠지는 일이 흔하다. 나눠 세야 어디를 손볼지가 정해진다."},{"label":"결제 실패로 빠진 사람","note":"마음이 떠난 것이 아니라 카드가 만료된 경우다. Stripe 는 미납으로 표시된 구독도 이탈로 세므로, 둘을 갈라 보지 않으면 엉뚱한 곳을 고치게 된다."},{"label":"생애 가치의 입력값","note":"Stripe 문서는 구독자 생애 가치를 사용자당 평균 매출을 구독자 이탈률로 나눠 구한다. 이탈률이 흔들리면 그 값도 같이 흔들린다."}],"dia":{"shape":"흐름","title":"이탈률은 무엇을 무엇으로 나눈 값인가","rows":[{"who":"기간 정하기","what":"30일처럼 잴 구간을 먼저 못 박는다"},{"who":"분모 세기","what":"그 구간에 명단에 있던 사람을 센다"},{"who":"분자 세기","what":"그 구간에 명단에서 빠진 사람을 센다"},{"who":"나누기","what":"빠진 수를 명단 수로 나눈다"}],"sum":"한 구간에서 빠져나간 사람의 몫이다. 구간과 분모를 정하는 것이 절반이다"}},"pm--cohort-analysis":{"definition":"전체를 한 덩어리로 평균 내면 어제 들어온 사람과 2년 전에 들어온 사람이 한 칸에 섞인다. 그 평균이 올랐을 때 제품이 좋아진 것인지 신규가 많이 들어온 것인지 구별할 방법이 없다. 코호트는 그 덩어리를 시작 시점으로 갈라 놓는다.","name":"Cohort :: 같은 때 묶인 무리\nAnalysis :: 갈라서 보기\n= 붙여 읽으면 \"같은 때 시작한 무리로 갈라 보기\". 무엇으로 묶느냐가 이 방법의 전부다","analogy":"같은 해에 입학한 한 학년을 졸업할 때까지 그 학년만 따로 세어 보는 일이다.","example":"학교 신문에 2019년 입학생 중 몇 퍼센트가 제때 졸업했다는 문장이 실린다. 전교생 수로는 절대 안 나오는 숫자다.","tryit":"같은 달에 그 앱을 깔았던 친구 다섯을 떠올려 보고, 지금도 쓰는 사람이 몇인지 세어 보라. 그게 그 달 무리의 유지율이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"묶는 기준을 먼저 고른다. Google Analytics 의 데이터 API 는 코호트 보고서를 만들 때 첫 세션 날짜 같은 차원 하나와 날짜 범위를 짝지어 무리를 정의한다. 그러면 그 무리에 대해 두 값이 나온다. 무리에 속한 전체 사용자 수와, 그 기간에 아직 활동 중인 사용자 수다. 문서는 뒤의 것을 앞의 것으로 나눈 값을 유지 비율로 쓰는 예를 들고, 그렇게 하면 크기가 다른 무리들도 나란히 놓고 볼 수 있다고 적는다.\n\n경과 시간은 절대 날짜가 아니라 상대 날짜로 센다. 같은 API 는 무리가 시작하고 며칠째인지, 몇 주째인지를 따로 둔다. 1월 무리의 3주째와 2월 무리의 3주째가 같은 칸에 서야 견줄 수 있기 때문이다.\n\n묶는 기준이 꼭 가입일일 필요는 없다. Azure Application Insights 문서는 코호트를 무언가를 공통으로 가진 사용자·세션·이벤트·작업의 집합이라고 정의하고, 그 집합을 분석 쿼리로 직접 적게 한다. 같은 문서의 유지율 표는 행 하나가 그 기간에 무언가를 한 사람들의 한 무리이고, 그 행의 칸마다 그 무리 중 나중 기간에 한 번이라도 돌아온 사람 수가 적힌다고 설명한다.\n\n값이 100%를 넘기도 한다. Stripe 는 처음으로 양의 월 반복 매출을 낸 시점을 기준으로 구독자를 무리에 배정하는데, 매출로 보는 유지율은 남은 사람이 결제액을 올린 몫까지 세기 때문에 100%를 넘을 수 있다고 적는다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **고친 것의 효과 확인** — 화면을 바꾼 뒤에 들어온 줄부터 곡선이 달라지는지 본다. 전체 평균은 옛 줄이 섞여 있어 늦게 움직인다.\n- **한 장짜리 표** — 행마다 한 무리, 칸마다 몇 주째가 오도록 늘어놓으면 어느 무리가 언제 빠졌는지가 한눈에 들어온다.\n- **매출로 보는 유지** — 사람 수 대신 그 무리가 내는 금액을 따라가면, 사람은 줄었는데 금액은 늘어난 무리가 드러난다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **코호트는 가입한 달로 묶는 것이다** — 시작점 하나만 정하면 무엇으로든 묶는다. Application Insights 는 코호트를 무언가를 공통으로 가진 집합으로 정의하고, 그 집합을 쿼리로 직접 적게 한다.\n- **유지율은 100%를 넘을 수 없다** — 사람 수로 보면 그렇지만 금액으로 보면 넘는다. Stripe 는 남은 구독자가 결제액을 올린 몫까지 세기 때문에 매출 유지율이 100%를 넘을 수 있다고 적어 둔다.\n- **무리를 잘게 나눌수록 정확해진다** — 한 칸에 든 사람이 적어지면 한두 명의 움직임이 곡선을 흔든다. 나눌수록 선명해지는 게 아니라 시끄러워진다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **무리 크기를 값 옆에 적어 둔다.** 30명짜리 무리의 60% 와 3000명짜리 무리의 60% 는 같은 무게가 아니다.\n- **경과 시간으로 줄을 맞춘다.** 절대 날짜로 늘어놓으면 늦게 시작한 무리가 그냥 짧아 보인다. 몇 주째인지로 맞춰야 견줄 수 있다."}],"figure":"```도해\n흐름: 코호트 분석은 사람을 무엇으로 어떻게 묶어 보나\n묶는 기준 :: 처음 쓴 날처럼 시작점 하나를 고른다\n무리 짓기 :: 같은 시작점을 가진 사람을 한 줄로 묶는다\n줄마다 추적 :: 줄마다 1주 뒤·4주 뒤에 몇이 남았나 센다\n줄끼리 비교 :: 1월 줄과 2월 줄을 나란히 놓고 견준다\n= 같은 때 시작한 사람만 한 줄로 묶어 따라가는 것이 코호트 분석이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 전체를 한 덩어리로 보면 무엇이 가려지나\n전체 평균 || 무리별로\n좋아졌나 :: 알 수 없다 || 줄끼리 견준다\n신규가 몰리면 :: 값이 흔들린다 || 줄은 안 흔들림\n고친 효과 :: 묻힌다 || 그 뒤 줄에 뜬다\n= 평균 하나는 새로 온 사람과 오래 남은 사람을 섞어 버린다\n```\n\n전체 평균은 두 가지가 겹쳐 만든 값이다. 하나는 사람들이 얼마나 남느냐이고 다른 하나는 이번 달에 몇 명이 새로 들어왔느냐다. 겹쳐 있으면 값이 움직여도 어느 쪽이 움직였는지 말할 수 없다.\n\n시작 시점으로 갈라 놓으면 그 겹침이 풀린다. 신규 유입은 새 줄을 하나 더 만들 뿐 기존 줄의 숫자를 건드리지 않기 때문에, 화면을 고친 뒤에 생긴 줄만 달라졌다면 그건 고친 것의 효과다."},"recap":"**\"같은 때 시작한 사람만 한 줄로 묶어 따라가는 눈\"** 이라고 읽으면 된다. 전체 평균은 새로 온 사람과 오래 남은 사람을 섞어 버려서 무엇이 달라졌는지 말해주지 못한다. 무엇으로 묶을지와 경과 시간을 어디에 둘지를 정하는 것이 이 방법의 전부다.","kid":"같은 해에 학교에 들어온 애들만 따로 묶어서 해마다 몇 명 남았는지 세는 거야. 전교생을 한꺼번에 세면 새로 들어온 1학년이 섞여서 누가 그만뒀는지 안 보이거든. 이렇게 묶어 보면 어느 해에 들어온 애들이 유난히 많이 그만뒀는지도 알 수 있어.","check":[{"q":"화면을 고쳤는데 전체 평균이 안 움직이는 동안 무엇을 보고 있어야 하나","at":"실제 사례"},{"q":"무리마다 사람 수가 다른데도 나란히 견줄 수 있는 이유는 무엇인가","at":"작동 원리"},{"q":"사람 수는 줄었는데 유지율이 100%를 넘는 일은 어떻게 생기나","at":"흔한 오해"}],"myths":[{"wrong":"코호트는 가입한 달로 묶는 것이다","right":"시작점 하나만 정하면 무엇으로든 묶는다. Application Insights 는 코호트를 무언가를 공통으로 가진 집합으로 정의하고, 그 집합을 쿼리로 직접 적게 한다."},{"wrong":"유지율은 100%를 넘을 수 없다","right":"사람 수로 보면 그렇지만 금액으로 보면 넘는다. Stripe 는 남은 구독자가 결제액을 올린 몫까지 세기 때문에 매출 유지율이 100%를 넘을 수 있다고 적어 둔다."},{"wrong":"무리를 잘게 나눌수록 정확해진다","right":"한 칸에 든 사람이 적어지면 한두 명의 움직임이 곡선을 흔든다. 나눌수록 선명해지는 게 아니라 시끄러워진다."}],"cases":[{"label":"고친 것의 효과 확인","note":"화면을 바꾼 뒤에 들어온 줄부터 곡선이 달라지는지 본다. 전체 평균은 옛 줄이 섞여 있어 늦게 움직인다."},{"label":"한 장짜리 표","note":"행마다 한 무리, 칸마다 몇 주째가 오도록 늘어놓으면 어느 무리가 언제 빠졌는지가 한눈에 들어온다."},{"label":"매출로 보는 유지","note":"사람 수 대신 그 무리가 내는 금액을 따라가면, 사람은 줄었는데 금액은 늘어난 무리가 드러난다."}],"dia":{"shape":"흐름","title":"코호트 분석은 사람을 무엇으로 어떻게 묶어 보나","rows":[{"who":"묶는 기준","what":"처음 쓴 날처럼 시작점 하나를 고른다"},{"who":"무리 짓기","what":"같은 시작점을 가진 사람을 한 줄로 묶는다"},{"who":"줄마다 추적","what":"줄마다 1주 뒤·4주 뒤에 몇이 남았나 센다"},{"who":"줄끼리 비교","what":"1월 줄과 2월 줄을 나란히 놓고 견준다"}],"sum":"같은 때 시작한 사람만 한 줄로 묶어 따라가는 것이 코호트 분석이다"}},"pm--conversion-rate":{"definition":"건수만 세면 규모와 실력이 뒤엉킨다. 광고를 두 배로 부으면 전환 건수도 대개 같이 늘어나는데, 그게 화면이 좋아져서인지 사람을 더 데려와서인지 알 수 없다. 비율로 적으면 규모가 나눠 없어지고 남은 것만 보인다.","name":"Conversion :: 바라던 행동을 함\nRate :: 몇 분의 몇\n= 붙여 읽으면 \"바라던 행동을 한 사람이 몇 분의 몇인가\". 분모가 값을 정한다","analogy":"가게 앞을 지나간 사람 중 실제로 물건을 사 간 사람의 몫이다.","example":"장바구니에 담아 놓고 결제는 안 한 채 앱을 닫아 본 적이 있다. 그 순간 나는 분모에는 들어가고 분자에는 안 들어간 사람이다.","tryit":"광고를 눌러 들어간 페이지에서 곧바로 뒤로 가기를 눌러 보라. 그 한 번이 저쪽 표에서는 분모만 늘린 클릭 하나로 적힌다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"산식은 하나인데 분모가 여럿이다.\n\nMicrosoft Advertising 의 보고 문서는 전환율을 (전환 수 / 클릭 수) × 100 으로 적고, 광고가 클릭 300번에 전환 4건을 얻었으면 1.33% 라는 예를 붙인다. 여기서 나누는 수는 클릭이다.\n\nSearch Ads 360 의 보고 API 는 같은 자리를 상호작용으로 나눈다. 문서는 상호작용을 광고 형식에 딸린 주된 사용자 행동이라고 정의하고, 글 광고와 쇼핑 광고는 클릭이 그것이고 동영상 광고는 조회가 그것이라고 적는다. 광고 형식이 바뀌면 같은 이름의 값이 다른 것을 나눈 결과가 된다.\n\n제품 쪽으로 오면 분모가 또 달라진다. Stripe 의 Billing 문서는 무료 체험 전환율을 최근 30일 안에 유료로 넘어간 체험 수를 최근 30일 안에 끝난 체험 수로 나눈 값으로 적는다. 100건이 끝나고 15건이 넘어갔으면 15% 다. 이 정의에는 구멍이 하나 있다. 체험이 끝난 뒤에 결제로 넘어간 건이 분자에 들어가면 값이 100%를 넘을 수 있다고 문서가 직접 적어 둔다.\n\n분모에 사람이 아닌 것도 섞인다. 같은 Microsoft 문서는 클릭이 검색 결과나 사이트에서의 클릭 말고도 스파이더·로봇·테스트 서버 같은 다른 출처에서 올 수 있다고 적는다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **두 화면 견주기** — 같은 기간 같은 분모로 재야 두 화면의 값이 비교가 된다. 기간이 다르면 화면이 아니라 계절을 재게 된다.\n- **광고 표와 제품 표가 안 맞을 때** — 광고 쪽은 클릭으로 나누고 무료 체험 쪽은 끝난 체험 수로 나눈다. 이름이 같아도 두 표의 숫자는 안 맞는 것이 정상이다.\n- **100%를 넘는 값** — 체험이 끝난 뒤에 결제한 사람이 분자로 잡히면 비율이 100%를 넘는다. 값이 이상하면 산식부터 열어 본다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **전환율은 어디서나 같은 방식으로 잰다** — 나누는 수가 제각각이다. Microsoft Advertising 은 클릭으로 나누고, Search Ads 360 은 광고 형식마다 다른 상호작용으로 나눈다. 글 광고는 클릭이고 동영상 광고는 조회다.\n- **비율이니까 100%를 넘을 수 없다** — 넘는다. Stripe 문서는 체험이 끝난 뒤에 유료로 넘어간 건이 있으면 무료 체험 전환율이 100%를 웃돌 수 있다고 적어 둔다.\n- **전환율이 올랐으면 잘된 것이다** — 분모가 줄어도 값은 오른다. 광고를 줄여 방문이 반으로 떨어지면 비율은 좋아지고 건수는 그대로거나 준다. 비율과 건수를 함께 보지 않으면 후퇴를 성과로 읽는다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **분모를 먼저 확인한다.** 클릭인지, 상호작용인지, 끝난 체험 수인지에 따라 같은 사건이 다른 값으로 적힌다.\n- **분모에 사람이 아닌 것이 섞인다.** Microsoft 문서는 클릭이 스파이더·로봇·테스트 서버에서도 올 수 있다고 적는다. 분모가 부풀면 값은 실제보다 낮게 나온다."}],"figure":"```도해\n흐름: 전환율은 무엇을 무엇으로 나눈 값인가\n분모 정하기 :: 무엇을 온 사람으로 셀지 먼저 못 박는다\n분자 정하기 :: 무엇을 목표 행동으로 볼지 정한다\n세기 :: 정해 둔 기간 동안 양쪽을 각각 센다\n나누기 :: 분자를 분모로 나누고 100을 곱한다\n= 온 사람 중 목표 행동을 한 사람의 몫이다. 분모가 바뀌면 값도 바뀐다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 건수만 세면 무엇을 못 보나\n건수만 || 전환율까지\n광고를 늘리면 :: 같이 늘어난다 || 그대로거나 준다\n두 화면 견주기 :: 규모에 묻힌다 || 나란히 선다\n나쁜 유입 :: 성과로 보인다 || 값이 떨어진다\n= 건수는 규모를 재고, 비율은 잘 만들었는지를 잰다\n```\n\n건수는 두 가지가 곱해진 값이다. 얼마나 많이 왔느냐와, 온 사람 중 얼마가 끝까지 갔느냐다. 곱해져 있으면 숫자가 올라도 어느 쪽이 올랐는지 말할 수 없고, 사람을 더 사 오는 것으로 언제까지나 가릴 수 있다.\n\n전환율은 앞의 것을 나눠 없애고 뒤의 것만 남긴다. 그래서 방문이 반으로 줄어든 달에도 화면이 좋아졌는지를 물을 수 있고, 두 화면을 같은 기간 같은 분모로 재면 어느 쪽이 나은지가 취향 문제가 아니게 된다."},"recap":"**\"온 사람 중 목표까지 간 사람의 몫\"** 이라고 읽으면 된다. 값보다 먼저 볼 것은 분모다. 무엇을 온 사람으로 셌는지가 바뀌면 같은 사건이 다른 비율이 되고, 분모가 줄어도 값은 오르므로 비율과 건수를 늘 함께 본다.","kid":"가게 앞을 지나간 사람이 백 명인데 그중 열 명만 들어와서 뭘 사 갔다고 해 봐. 그러면 열 명 중 한 명이 산 거지. 이 몫을 재려면 산 사람만 세면 안 되고 지나간 사람을 어디까지 셀지부터 정해야 하는데, 그 기준을 바꾸면 같은 날인데도 다른 숫자가 나와.","check":[{"q":"클릭 300번에 전환 4건이면 전환율은 얼마이고 무엇으로 나눈 값인가","at":"작동 원리"},{"q":"비율인데도 100%를 넘는 값이 나오는 일은 어떻게 생기나","at":"흔한 오해"},{"q":"표에 적힌 전환율이 실제보다 낮게 나올 수 있는 이유는 무엇인가","at":"주의사항"}],"myths":[{"wrong":"전환율은 어디서나 같은 방식으로 잰다","right":"나누는 수가 제각각이다. Microsoft Advertising 은 클릭으로 나누고, Search Ads 360 은 광고 형식마다 다른 상호작용으로 나눈다. 글 광고는 클릭이고 동영상 광고는 조회다."},{"wrong":"비율이니까 100%를 넘을 수 없다","right":"넘는다. Stripe 문서는 체험이 끝난 뒤에 유료로 넘어간 건이 있으면 무료 체험 전환율이 100%를 웃돌 수 있다고 적어 둔다."},{"wrong":"전환율이 올랐으면 잘된 것이다","right":"분모가 줄어도 값은 오른다. 광고를 줄여 방문이 반으로 떨어지면 비율은 좋아지고 건수는 그대로거나 준다. 비율과 건수를 함께 보지 않으면 후퇴를 성과로 읽는다."}],"cases":[{"label":"두 화면 견주기","note":"같은 기간 같은 분모로 재야 두 화면의 값이 비교가 된다. 기간이 다르면 화면이 아니라 계절을 재게 된다."},{"label":"광고 표와 제품 표가 안 맞을 때","note":"광고 쪽은 클릭으로 나누고 무료 체험 쪽은 끝난 체험 수로 나눈다. 이름이 같아도 두 표의 숫자는 안 맞는 것이 정상이다."},{"label":"100%를 넘는 값","note":"체험이 끝난 뒤에 결제한 사람이 분자로 잡히면 비율이 100%를 넘는다. 값이 이상하면 산식부터 열어 본다."}],"dia":{"shape":"흐름","title":"전환율은 무엇을 무엇으로 나눈 값인가","rows":[{"who":"분모 정하기","what":"무엇을 온 사람으로 셀지 먼저 못 박는다"},{"who":"분자 정하기","what":"무엇을 목표 행동으로 볼지 정한다"},{"who":"세기","what":"정해 둔 기간 동안 양쪽을 각각 센다"},{"who":"나누기","what":"분자를 분모로 나누고 100을 곱한다"}],"sum":"온 사람 중 목표 행동을 한 사람의 몫이다. 분모가 바뀌면 값도 바뀐다"}},"pm--dau-mau":{"definition":"가입자 수는 한 번 오르면 내려가지 않는다. 3년 전에 가입하고 앱을 지운 사람도 그 숫자에는 그대로 남아 있다. 활성 사용자는 정해진 창 안에서 실제로 무언가 한 사람만 세기 때문에 오르내리고, 그래서 지금 상태를 말해준다.","name":"Daily :: 하루\nMonthly :: 한 달\nActive :: 무언가를 한\nUsers :: 쓰는 사람\n= 붙여 읽으면 \"하루 안에 뭔가를 한 사람 수\" 와 \"한 달 안에 뭔가를 한 사람 수\" 다","analogy":"가게 문에 계수기를 둘 달아, 하나는 오늘 들어온 사람을 세고 다른 하나는 지난 한 달 안에 한 번이라도 들어온 사람을 센다.","example":"소개 자료에 \"월 활성 사용자 1000만\" 이라고 적힌 문장을 본 적이 있다. 그중 오늘 실제로 앱을 연 사람은 훨씬 적다.","tryit":"지난 한 달 안에 한 번이라도 연 앱을 홈 화면에서 세어 보고, 오늘 연 앱을 다시 세어 보라. 두 숫자의 비가 곧 그 끈끈함이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"둘 다 고유한 사람을 세지만 창을 자르는 법이 다르다.\n\nAmazon Pinpoint 의 사용량 문서는 일간 활성 사용자를 선택한 기간의 날마다 앱을 연 사용자 수로, 월간 활성 사용자를 그 날짜 기준으로 앞선 30일 안에 한 번이라도 앱을 연 사용자 수로 적는다. 뒤의 것은 달력의 한 달이 아니라 날마다 함께 굴러가는 30일 창이다.\n\n같은 이름을 달력으로 자르는 곳도 있다. Microsoft Copilot Studio 의 분석 문서는 활성 사용자를 보고 기간 안에 한 번이라도 상호작용한 고유 사용자로 정의하고, 일간은 협정 세계시 기준 꽉 찬 24시간, 월간은 협정 세계시 기준 달력 한 달로 센다. 같은 제품을 같은 사람들이 써도 굴러가는 30일과 달력 한 달은 다른 숫자를 낸다.\n\n무엇을 한 명으로 셀지도 정해야 한다. Pinpoint 는 엔드포인트(메시지를 보낼 수 있는 목적지 하나 — 기기·이메일 주소·전화번호)와 사용자(고유한 사용자 아이디를 가진 한 사람)를 나눠 세고, 한 사람이 기기 여러 대에서 앱을 쓰면 그 사람의 아이디가 기기마다의 목적지에 붙는다고 적는다. Copilot Studio 는 아예 로그인을 요구하도록 설정한 경우에만 이 지표를 보여준다.\n\n두 값을 나눈 것은 끈끈함이라고 부른다. Pinpoint 문서는 sticky factor 를 월간 활성 엔드포인트 중 그날 활동한 몫으로 적고, 0.25 면 앞선 30일의 활성 중 25% 가 그날 활동했다는 뜻이라는 예를 든다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **끈끈함 보기** — 두 값을 나누면 한 달에 며칠 꼴로 오는지가 나온다. 매일 여는 도구와 한 달에 한 번 여는 도구를 같은 잣대로 재지 않게 된다.\n- **한 사람 여러 기기** — 폰과 태블릿에서 같은 앱을 쓰면 보낼 곳은 둘, 사람은 하나다. 어느 쪽을 센 값인지 표에 적어 둔다.\n- **로그인 없는 제품** — 사람을 알아볼 방법이 없으면 기기 수가 사람 수를 대신한다. Copilot Studio 는 로그인을 요구하도록 설정한 경우에만 이 지표를 내준다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **월간 활성 사용자는 그달에 가입한 사람 수다** — 가입이 아니라 활동을 센다. Pinpoint 는 그 날짜 기준 앞선 30일 안에 앱을 한 번이라도 연 사람으로 세므로, 3년 전에 가입한 사람도 어제 열었으면 여기 들어간다.\n- **일간 값을 30일 더하면 월간 값이 된다** — 매일 오는 사람이 30번 세어진다. 둘 다 중복을 뺀 고유 사용자 수라서 더할 수 있는 종류의 숫자가 아니다.\n- **두 회사의 월간 활성 사용자는 나란히 비교할 수 있다** — 창을 자르는 법부터 다르다. 앞선 30일을 날마다 굴리는 정의와 달력 한 달을 쓰는 정의가 같은 이름을 달고 돌아다닌다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **무엇을 센 값인지 표에 적어 둔다.** 기기를 세면 한 사람이 여럿으로 잡히고, 로그인을 요구하지 않으면 사람을 셀 방법 자체가 없다.\n- **하루치 하나로 판단하지 않는다.** 굴러가는 30일 값은 천천히 움직이는데 하루치는 요일마다 오르내려서, 이틀치를 견주면 없는 변화가 보인다."}],"figure":"```도해\n대조: 하루로 세는 것과 한 달로 세는 것은 무엇이 다른가\nDAU |=| MAU\n세는 창 :: 하루 안에 || 지난 한 달 안에\n한 사람이 :: 그날 써야 센다 || 한 번만 써도 센다\n빠지려면 :: 하루만 쉬면 || 한 달을 쉬어야\n= 같은 사람을 세는데 창을 얼마나 넓게 여느냐가 다르다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 누적 가입자만 발표하면 무엇이 가려지나\n누적 가입자 || 활성 사용자\n앱을 지운 사람 :: 계속 세어진다 || 안 세어진다\n숫자 방향 :: 내려갈 수 없다 || 오르내린다\n지금 상태 :: 알 수 없다 || 오늘이 보인다\n= 누적은 지나간 것의 합이고, 활성은 지금 쓰는 사람의 수다\n```\n\n누적 가입자 수는 광고를 부으면 따라 오르고, 사람들이 떠나도 절대 내려가지 않는다. 그래서 이 숫자만 발표하면 제품이 살아 있는지 죽어 있는지가 가려진다.\n\n활성 사용자는 창을 정하고 그 안에서 실제로 무언가 한 사람만 센다. 오르내리는 숫자라서 이번 주에 무슨 일이 있었는지가 그대로 드러나고, 하루 창과 한 달 창을 나란히 두면 얼마나 자주 오는 사람들인지까지 보인다."},"recap":"**\"지금 쓰는 사람이 몇인지 재는 두 개의 창\"** 이라고 읽으면 된다. 하루 창과 한 달 창은 더하거나 뺄 수 있는 숫자가 아니라 폭만 다른 같은 질문이고, 둘을 나눈 값이 얼마나 자주 오는지를 말해준다. 값을 받으면 창을 어떻게 잘랐는지와 무엇을 한 명으로 세었는지를 먼저 묻는다.","kid":"가게 문에 손님 세는 기계를 두 개 달았다고 해 봐. 하나는 오늘 들어온 사람만 세고, 다른 하나는 지난 한 달 안에 한 번이라도 들어온 사람을 세. 두 숫자를 나란히 놓으면 날마다 오는 단골 가게인지 어쩌다 한 번 들르는 가게인지 알 수 있어.","check":[{"q":"일간 활성 사용자를 30일 동안 더하면 왜 월간 활성 사용자가 안 되나","at":"흔한 오해"},{"q":"굴러가는 30일로 재는 곳과 달력 한 달로 재는 곳의 값이 갈리는 이유는","at":"작동 원리"},{"q":"폰과 태블릿에서 같은 앱을 쓰는 사람은 몇 명으로 세어지나","at":"실제 사례"}],"myths":[{"wrong":"월간 활성 사용자는 그달에 가입한 사람 수다","right":"가입이 아니라 활동을 센다. Pinpoint 는 그 날짜 기준 앞선 30일 안에 앱을 한 번이라도 연 사람으로 세므로, 3년 전에 가입한 사람도 어제 열었으면 여기 들어간다."},{"wrong":"일간 값을 30일 더하면 월간 값이 된다","right":"매일 오는 사람이 30번 세어진다. 둘 다 중복을 뺀 고유 사용자 수라서 더할 수 있는 종류의 숫자가 아니다."},{"wrong":"두 회사의 월간 활성 사용자는 나란히 비교할 수 있다","right":"창을 자르는 법부터 다르다. 앞선 30일을 날마다 굴리는 정의와 달력 한 달을 쓰는 정의가 같은 이름을 달고 돌아다닌다."}],"cases":[{"label":"끈끈함 보기","note":"두 값을 나누면 한 달에 며칠 꼴로 오는지가 나온다. 매일 여는 도구와 한 달에 한 번 여는 도구를 같은 잣대로 재지 않게 된다."},{"label":"한 사람 여러 기기","note":"폰과 태블릿에서 같은 앱을 쓰면 보낼 곳은 둘, 사람은 하나다. 어느 쪽을 센 값인지 표에 적어 둔다."},{"label":"로그인 없는 제품","note":"사람을 알아볼 방법이 없으면 기기 수가 사람 수를 대신한다. Copilot Studio 는 로그인을 요구하도록 설정한 경우에만 이 지표를 내준다."}],"dia":{"shape":"대조","title":"하루로 세는 것과 한 달로 세는 것은 무엇이 다른가","rows":[{"who":"","what":"DAU || MAU","left":"DAU","right":"MAU","even":true},{"who":"세는 창","what":"하루 안에 || 지난 한 달 안에","left":"하루 안에","right":"지난 한 달 안에"},{"who":"한 사람이","what":"그날 써야 센다 || 한 번만 써도 센다","left":"그날 써야 센다","right":"한 번만 써도 센다"},{"who":"빠지려면","what":"하루만 쉬면 || 한 달을 쉬어야","left":"하루만 쉬면","right":"한 달을 쉬어야"}],"sum":"같은 사람을 세는데 창을 얼마나 넓게 여느냐가 다르다"}},"pm--dora-metrics":{"definition":"2014년에 시작된 DORA 연구가 조직 성과와 이어지는 변수로 처음 고른 넷이 배포 빈도 · 변경 리드 타임 · 평균 복구 시간(MTTR) · 변경 실패율이었다. 이후 이름과 정의가 여러 번 손질됐고 2024년에는 다섯 번째 숫자까지 붙었지만, 흔히 \"네 지표\" 라고 부르는 것은 이 처음의 넷이다.","name":"DevOps :: 만들고 굴리는 일\nResearch :: 조사\nAssessment :: 진단\nMetrics :: 재는 숫자\n= 붙여 읽으면 \"만들고 굴리는 일을 조사해 진단하려고 만든 숫자\". 좋은 팀을 뽑는 점수가 아니다","analogy":"식당 주방 벽의 기록표 — 접시가 얼마나 자주 나가고, 주문부터 몇 분 걸리고, 몇 접시나 물려 오고, 물린 것을 다시 내는 데 얼마 걸리는지를 적어 둔 종이다.","example":"쓰던 앱의 업데이트가 두 달에 한 번 오다가 매주 오기 시작했는데, 그런데도 오히려 덜 고장 나던 그 시기다.","tryit":"폰의 앱 스토어에서 아무 앱이나 열어 업데이트 날짜 목록을 훑어보라. 그 간격이 좁아졌는지 벌어졌는지가 첫 숫자가 재는 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"DORA 의 현행 정의는 짧다. 변경 리드 타임은 \"변경이 형상 관리에 커밋된 시점부터 운영에 반영될 때까지 걸리는 시간\", 배포 빈도는 \"주어진 기간의 배포 횟수 또는 배포 사이의 간격\", 변경 실패율은 \"배포 후 즉시 손을 대야 하는 배포의 비율\", 실패한 배포의 복구 시간은 \"즉시 손을 대야 하는 배포 실패에서 회복하는 데 걸리는 시간\" 이다.\n\n세는 방법에서 갈린다. 예컨대 구글 클라우드의 배포 도구는 배포 빈도를 배포 **횟수**가 아니라 **배포한 날 수**로 센다 — 하루에 네 번 내보내도 그날은 한 번으로 친다. 정의도 문서마다 다르다. 마이크로소프트의 클라우드 도입 프레임워크는 리드 타임을 \"버그 수정이나 새 기능이 **아이디어에서** 운영 반영까지 가는 시간\" 으로 적는데, DORA 는 **커밋에서** 시작한다. 기획 대기 시간이 통째로 들어가느냐 마느냐가 갈리므로, 어디서부터 재는지를 못 박지 않으면 같은 이름의 숫자끼리도 견줄 수 없다.\n\n이름 자체도 손질돼 왔다. 2023년에 DORA 는 오래 쓰이던 MTTR(평균 복구 시간)을 \"실패한 배포의 복구 시간\" 으로 다시 정의했다. 예전 정의가 변경 때문에 난 장애와 데이터 센터 정전 같은 외부 원인의 장애를 구분하지 못했기 때문이고, 새 정의는 운영에 나간 변경이 일으킨 손상을 되돌리는 시간만 본다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **큰 덩어리를 쪼갤 때** — 한 달에 한 번 크게 내보내던 것을 잘게 나누면 잦기와 리드 타임이 같이 좋아진다. 이때 사고율을 함께 보지 않으면, 검증 단계를 덜어내 빨라진 것을 쪼개서 빨라진 것으로 착각한다.\n- **되돌리기 장치를 갖출 때** — 복구 시간은 원인을 빨리 찾아서가 아니라 빨리 되돌려서 줄어든다. 원인 분석 회의보다 롤백 단추 하나가 이 숫자를 더 크게 바꾼다.\n- **팀 비교 요청을 받을 때** — 결제 시스템 팀과 사내 도구 팀을 한 표에 올려 줄 세우면 숫자가 뜻을 잃는다. 같은 팀의 지난달과 이번 달을 견주는 데 쓴다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **자주 내보낼수록 그만큼 더 자주 깨진다** — DORA 연구는 반대로 나온다. 속도와 안정성은 맞바꾸는 것이 아니고, 대부분의 팀에서 두 쪽 숫자가 같은 방향으로 움직인다.\n- **숫자를 목표로 걸면 팀이 따라온다** — \"연말까지 모든 앱이 하루에 여러 번 내보낸다\" 같은 선언은 숫자를 꾸미게 만든다. DORA 가 굿하트의 법칙을 들며 첫 번째 함정으로 적어 둔 것이 바로 이것이다.\n- **넷으로 굳어진 목록이다** — 이름도 정의도 계속 바뀌었다. 2023년에 MTTR 이 \"실패한 배포의 복구 시간\" 으로 다시 정의됐고, 2024년에는 다섯 번째 숫자인 배포 재작업 비율이 더해졌다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **팀끼리 줄 세우지 마라.** 성격이 크게 다른 애플리케이션의 숫자를 나란히 놓으면 오해를 부른다고 DORA 가 직접 적는다. 견줄 대상은 옆 팀이 아니라 지난달의 우리 팀이다.\n- **한 숫자만 보지 마라.** 넷은 서로를 팽팽하게 당긴다. 잦기만 밀어 올리면 사고율이 올라가고, 사고율만 낮추려 들면 아무것도 안 내보내는 쪽이 가장 안전해진다.\n- **재는 일에 힘을 다 쓰지 마라.** 수집 장치를 정교하게 만드느라 정작 나아지는 일을 못 하는 것도 DORA 가 꼽는 함정 중 하나다."}],"figure":"```도해\n흐름: 고친 것 하나가 나가는 길에서 무엇을 재나\n저장소 :: 고친 것을 올린다. 여기가 출발선이다\n리드 타임 :: 출발선부터 사용자에게 닿기까지 걸린 시간\n반영 :: 실제로 나간다. 여기가 도착선이다\n잦기 :: 이 도착이 얼마나 자주 일어나나\n사고율 :: 도착한 것 중 곧바로 손봐야 했던 비율\n복구 시간 :: 손봐야 했던 건이 정상으로 돌아오기까지\n= 네 숫자는 따로 노는 지표가 아니라 한 줄기 위의 서로 다른 자리다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 이 네 숫자가 없으면 무엇을 못 하나\n숫자 없이 || 네 숫자로\n잘하나 :: 느낌으로 다툰다 || 같은 자로 잰다\n나아졌나 :: 기억에 기댄다 || 지난달과 견준다\n어디가 문제냐 :: 뭉뚱그린다 || 넷 중 하나를 짚는다\n= 빠르기와 깨짐을 따로 세어야 어느 쪽이 무너졌는지 보인다\n```\n\n\"우리 팀 개발 잘하고 있나\" 는 답이 없는 질문이다. 짠 줄 수도, 끝낸 일감 수도 내보내는 능력과는 상관이 없어서, 결국 목소리 큰 사람의 인상이 답이 된다. 무엇을 고쳐야 할지도 안 나온다 — \"느리다\" 는 말만으로는 만드는 데서 느린지, 내보내는 데서 느린지, 깨져서 되돌리느라 느린지를 가를 수 없다.\n\nDORA 는 그 한 덩어리를 넷으로 쪼갰다. 얼마나 자주 내보내는가, 고친 것이 사용자에게 닿기까지 얼마나 걸리는가, 내보낸 것 중 얼마가 사고를 냈는가, 사고 난 것이 돌아오기까지 얼마나 걸리는가. 그리고 이 연구가 거듭 확인한 것은 빠르기와 안정이 맞바꾸는 관계가 아니라는 점이다 — DORA 자신의 표현으로 \"속도와 안정성은 트레이드오프가 아니며, 대부분의 팀에서 두 지표는 상관관계를 보인다\"."},"recap":"**\"고친 것이 사용자에게 닿기까지를 재는 그 네 숫자\"** 라고 읽으면 된다. 네 숫자는 서로를 당기고 있어서 하나만 밀어 올리면 다른 하나가 대개 티를 낸다. 그래서 목표로 걸 숫자가 아니라 지난달의 우리와 견줄 숫자다.","kid":"떡볶이집에서 새 맛을 얼마나 자주 내놓는지만 세면, 서둘러 대충 내놔도 잘한 걸로 나와. 그래서 얼마나 자주 내놓는지, 내주기까지 몇 분 걸리는지, 몇 접시나 되돌아오는지, 되돌아온 걸 다시 해 주는 데 얼마 걸리는지를 함께 적어 둬. 네 가지를 나란히 적어야 오늘 뭐가 잘 안 됐는지를 사장님 기분이 아니라 그 종이만 보고 알 수 있어.","check":[{"q":"하루에 네 번 내보낸 날은 잦기를 넷으로 세나 하나로 세나","at":"작동 원리"},{"q":"결제 팀과 사내 도구 팀의 숫자를 한 표에 올리면 무엇이 어긋나나","at":"주의사항"},{"q":"자주 내보낼수록 그만큼 더 자주 깨진다는 말이 왜 근거가 없나","at":"흔한 오해"}],"myths":[{"wrong":"자주 내보낼수록 그만큼 더 자주 깨진다","right":"DORA 연구는 반대로 나온다. 속도와 안정성은 맞바꾸는 것이 아니고, 대부분의 팀에서 두 쪽 숫자가 같은 방향으로 움직인다."},{"wrong":"숫자를 목표로 걸면 팀이 따라온다","right":"\"연말까지 모든 앱이 하루에 여러 번 내보낸다\" 같은 선언은 숫자를 꾸미게 만든다. DORA 가 굿하트의 법칙을 들며 첫 번째 함정으로 적어 둔 것이 바로 이것이다."},{"wrong":"넷으로 굳어진 목록이다","right":"이름도 정의도 계속 바뀌었다. 2023년에 MTTR 이 \"실패한 배포의 복구 시간\" 으로 다시 정의됐고, 2024년에는 다섯 번째 숫자인 배포 재작업 비율이 더해졌다."}],"cases":[{"label":"큰 덩어리를 쪼갤 때","note":"한 달에 한 번 크게 내보내던 것을 잘게 나누면 잦기와 리드 타임이 같이 좋아진다. 이때 사고율을 함께 보지 않으면, 검증 단계를 덜어내 빨라진 것을 쪼개서 빨라진 것으로 착각한다."},{"label":"되돌리기 장치를 갖출 때","note":"복구 시간은 원인을 빨리 찾아서가 아니라 빨리 되돌려서 줄어든다. 원인 분석 회의보다 롤백 단추 하나가 이 숫자를 더 크게 바꾼다."},{"label":"팀 비교 요청을 받을 때","note":"결제 시스템 팀과 사내 도구 팀을 한 표에 올려 줄 세우면 숫자가 뜻을 잃는다. 같은 팀의 지난달과 이번 달을 견주는 데 쓴다."}],"dia":{"shape":"흐름","title":"고친 것 하나가 나가는 길에서 무엇을 재나","rows":[{"who":"저장소","what":"고친 것을 올린다. 여기가 출발선이다"},{"who":"리드 타임","what":"출발선부터 사용자에게 닿기까지 걸린 시간"},{"who":"반영","what":"실제로 나간다. 여기가 도착선이다"},{"who":"잦기","what":"이 도착이 얼마나 자주 일어나나"},{"who":"사고율","what":"도착한 것 중 곧바로 손봐야 했던 비율"},{"who":"복구 시간","what":"손봐야 했던 건이 정상으로 돌아오기까지"}],"sum":"네 숫자는 따로 노는 지표가 아니라 한 줄기 위의 서로 다른 자리다"}},"pm--definition-of-done":{"definition":"스크럼 지침은 이것을 결과물이 제품에 필요한 품질을 갖췄을 때의 상태를 적은 공식 서술이라고 적는다. 항목 하나가 이 기준을 만족하는 순간이 곧 내놓을 수 있는 결과물이 태어나는 순간이다.","name":"Definition :: 미리 적어 둔 조건\nDone :: 끝났다\n= 붙여 읽으면 \"끝났다는 말의 뜻\". 그 뜻을 사람마다 다르게 갖지 말자는 것이 전부다","analogy":"주방에서 접시를 내보내기 전에 붙여 둔 조건표라서, 하나라도 빠지면 그 접시는 창밖으로 못 나간다.","example":"\"다 됐어요\" 라는 말을 듣고 받아 봤더니 확인도 안 됐고 설명도 없어서 이틀이 더 걸리던 그 상황이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"누가 정하는지가 정해져 있다. 조직에 이미 표준이 있으면 모든 팀이 그것을 최소선으로 따르고, 표준이 없으면 팀이 그 제품에 맞게 만든다. 한 제품을 여러 팀이 함께 만들면 같은 것을 서로 정하고 함께 지켜야 한다. 만드는 사람들은 이 기준을 따를 의무가 있다.\n\n이 선이 그어지면 세는 일이 가능해진다. 이번 바퀴에 끝낸 개수든, 항목마다 붙인 크기의 합이든, 분자에 들어갈 자격을 이 조건표가 정한다. 반쯤 된 것은 0으로 세고 조건을 통과한 것만 센다.\n\n같은 이유로 이 숫자는 조건표를 바꾸는 것만으로 움직인다. 조건을 느슨하게 잡으면 같은 팀이 같은 일을 하고도 끝낸 개수가 늘고, 조건을 조이면 줄어든다. 그래서 두 팀의 숫자를 나란히 놓는 일은 두 조건표가 같을 때만 뜻이 있고, 한 팀의 숫자를 시간에 걸쳐 보는 일도 그동안 조건표를 안 건드렸을 때만 뜻이 있다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **리뷰 전에 걸러내기** — 조건을 못 맞춘 항목은 그 자리에서 보여주지 않고 목록으로 돌려보낸다.\n- **여러 팀이 한 제품을 만들 때** — 팀마다 다른 조건표를 쓰면 합쳐 놓은 결과물의 상태를 아무도 말할 수 없어서, 같은 것을 함께 정하고 따른다.\n- **회고에서 손보기** — 조건이 매번 안 지켜지면 조건을 낮추든 한 바퀴에 담는 양을 줄이든 둘 중 하나를 고른다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **완료 정의는 항목마다 새로 쓰는 조건이다** — 그 항목 하나에만 붙는 조건과 다르다. 이것은 그 제품의 모든 항목에 똑같이 걸리는 최소선이라, 조직 표준이 있으면 모든 팀이 그것을 최소로 따라야 한다.\n- **조건은 빡빡할수록 좋다** — 지금 매번 지킬 수 없는 조건을 적어 두면 아무것도 끝난 것이 되지 않는다. 지킬 수 있는 선에서 시작해 회고에서 한 칸씩 올리는 편이 낫다.\n- **거의 다 됐으니 이번엔 끝난 걸로 치자** — 지침은 조건을 못 맞춘 항목은 내보낼 수도, 리뷰에서 보여줄 수도 없다고 적는다. 그 항목은 목록으로 돌아가 다음에 다시 저울질된다."}],"figure":"```도해\n흐름: 만든 것 하나는 어디서 끝난 것이 되나\n항목 :: 이번 바퀴에 만들기로 고른다\n만들기 :: 실제로 손을 대 결과를 낸다\n조건표 :: 미리 적어 둔 조건을 하나씩 맞춰 본다\n통과 :: 다 맞은 그 순간 내놓을 수 있는 것이 된다\n@ 목록으로 :: 하나라도 안 맞으면 도로 목록에 돌아간다\n= 조건표를 통과한 것만 끝난 것으로 세어진다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: \"다 됐다\" 의 뜻을 안 정해 두면 어떻게 되나\n기준이 없으면 || 완료 정의로\n끝났다는 말 :: 사람마다 다르다 || 한 뜻으로 읽힌다\n남은 일 :: 나중에 튀어나온다 || 앞에서 걸린다\n보여줄 수 있나 :: 알 수 없다 || 조건이 답한다\n= 무엇을 갖춰야 끝인지를 미리 적어 둔 것이 이 기준이다\n```\n\n\"끝났다\" 는 말은 사람마다 다른 뜻으로 쓴다. 만든 사람은 손을 뗐다는 뜻으로 쓰고, 받는 사람은 지금 써도 된다는 뜻으로 듣는다. 그래서 다 끝났다던 일에서 남은 것이 계속 튀어나오고, 이번 바퀴에 몇 개를 끝냈다는 말도 서로 다른 것을 세게 된다.\n\n완료 정의는 그 말의 뜻을 한 벌로 고정한다. 지침은 이 기준이 무엇이 결과물에 들어갔는지에 대한 공통된 이해를 만들어 투명성을 준다고 적고, 기준을 못 맞춘 항목은 내보낼 수도 리뷰에서 보여줄 수도 없이 목록으로 돌아간다고 적는다. 세는 일이 가능해지는 것도 여기서부터다. 칸반 지침도 흐름을 정의할 때 어디를 넘으면 시작이고 어디를 넘으면 끝인지를 반드시 적으라고 하는데, 주기 시간과 처리량이 그 두 선에서 계산되기 때문이다."},"recap":"**\"끝났다는 말의 뜻을 미리 적어 둔 그 목록\"** 이라고 읽으면 된다. 이 조건을 못 맞춘 항목은 내보내지도 보여주지도 못하고 목록으로 돌아간다. 이 선이 그어져야 \"이번에 몇 개 끝냈다\" 는 숫자가 비로소 뜻을 가진다.","kid":"식당 주방에서는 접시를 내보내기 전에 볼 것이 정해져 있어. 밥 담았나, 국 담았나, 숟가락 놨나. 하나라도 빠지면 그 접시는 창밖으로 안 나가고 도로 들어와.","check":[{"q":"조건을 못 맞춘 항목은 그 바퀴가 끝날 때 어디로 가나","at":"그림"},{"q":"두 팀이 끝낸 개수를 나란히 놓고 견주면 안 되는 이유는","at":"작동 원리"},{"q":"조건을 아주 빡빡하게 잡은 팀에서는 무슨 일이 벌어지나","at":"흔한 오해"}],"myths":[{"wrong":"완료 정의는 항목마다 새로 쓰는 조건이다","right":"그 항목 하나에만 붙는 조건과 다르다. 이것은 그 제품의 모든 항목에 똑같이 걸리는 최소선이라, 조직 표준이 있으면 모든 팀이 그것을 최소로 따라야 한다."},{"wrong":"조건은 빡빡할수록 좋다","right":"지금 매번 지킬 수 없는 조건을 적어 두면 아무것도 끝난 것이 되지 않는다. 지킬 수 있는 선에서 시작해 회고에서 한 칸씩 올리는 편이 낫다."},{"wrong":"거의 다 됐으니 이번엔 끝난 걸로 치자","right":"지침은 조건을 못 맞춘 항목은 내보낼 수도, 리뷰에서 보여줄 수도 없다고 적는다. 그 항목은 목록으로 돌아가 다음에 다시 저울질된다."}],"cases":[{"label":"리뷰 전에 걸러내기","note":"조건을 못 맞춘 항목은 그 자리에서 보여주지 않고 목록으로 돌려보낸다."},{"label":"여러 팀이 한 제품을 만들 때","note":"팀마다 다른 조건표를 쓰면 합쳐 놓은 결과물의 상태를 아무도 말할 수 없어서, 같은 것을 함께 정하고 따른다."},{"label":"회고에서 손보기","note":"조건이 매번 안 지켜지면 조건을 낮추든 한 바퀴에 담는 양을 줄이든 둘 중 하나를 고른다."}],"dia":{"shape":"흐름","title":"만든 것 하나는 어디서 끝난 것이 되나","rows":[{"who":"항목","what":"이번 바퀴에 만들기로 고른다"},{"who":"만들기","what":"실제로 손을 대 결과를 낸다"},{"who":"조건표","what":"미리 적어 둔 조건을 하나씩 맞춰 본다"},{"who":"통과","what":"다 맞은 그 순간 내놓을 수 있는 것이 된다"}],"sum":"조건표를 통과한 것만 끝난 것으로 세어진다","loop":{"who":"목록으로","what":"하나라도 안 맞으면 도로 목록에 돌아간다"}}},"pm--funnel":{"definition":"들어온 사람 전부가 끝까지 가지는 않는다. 단계마다 얼마씩 빠져나가는 모양이 깔때기를 닮아서 퍼널이라고 부르고, 어느 칸에서 가장 많이 빠지는지를 보려고 쓴다.","name":"= 깔때기라는 뜻. 위가 넓고 아래가 좁은 그 모양이 곧 단계마다 사람이 줄어드는 모습이다","analogy":"깔때기. 위는 넓고 아래는 좁아서 부은 양보다 나오는 양이 늘 적다.","example":"장바구니까지 담았다가 결제 화면에서 그냥 나와본 적이 있다. 그렇게 빠져나간 자리가 가장 많이 새는 칸이다.","tryit":"쇼핑 앱에서 물건을 장바구니에 담고 결제 화면까지만 가 보라. 거기서 새로 물어보는 항목이 몇 개인지 세어 보면 된다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"각 칸의 통과율은 앞 칸 대비로 센다. 전체 전환율은 그 통과율을 전부 곱한 값이라서, 한 칸만 낮아도 앞뒤의 노력이 다 지워진다.\n\n칸 수 자체도 결과를 바꾼다. 칸마다 60%가 통과하는 퍼널이 5칸이면 전체는 7.8%지만, 같은 통과율로 3칸이면 21.6%가 된다. 필요 없는 단계를 없애는 것만으로 숫자가 움직이는 이유가 여기 있다.\n\n단계를 무엇으로 잡을지는 제품마다 다르다. 획득에서 활성화와 유지를 거쳐 수익과 추천까지 보는 방식이 널리 쓰이고, 이커머스처럼 구매 경로가 뚜렷하면 방문에서 결제까지를 그대로 칸으로 삼는다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **결제 이탈 확인** — 결제 화면까지 온 450명 중 절반이 사라지면 결제 절차부터 손본다.\n- **가입 폼 개선** — 입력 항목을 줄인 화면과 기존 화면을 나눠 보여주고 통과율을 비교한다.\n- **광고 판단** — 방문자만 늘고 아래 칸의 수가 그대로면 광고를 늘리는 대신 아래를 먼저 고친다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **전환율이 낮으면 사람을 더 데려오면 된다** — 새는 자리를 그대로 두고 위에 더 부으면 광고비만 늘어난다. 아래를 먼저 막는 편이 훨씬 싸게 먹힌다.\n- **마지막 칸의 숫자가 전환율이다** — 각 칸의 통과율을 곱한 결과다. 5%짜리 칸 하나가 앞의 모든 노력을 지운다.\n- **단계를 자세히 나눌수록 정확하다** — 열 몇 칸으로 쪼개면 칸마다 사람 수가 적어져 무엇이 문제인지 오히려 흐려진다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **신규와 재방문을 같은 퍼널에 넣지 않는다.** 행동이 달라서 섞어 세면 양쪽 다 흐려진다.\n- **기간을 정하고 센다.** 하루 만에 사는 사람과 한 달 뒤에 사는 사람을 한 칸에 넣으면 통과율이 실제보다 낮게 나온다."}],"figure":"```도해\n흐름: 방문자 1만 명이 구매까지 가면서 얼마나 남나\n방문 :: 10000명이 들어온다\n상품 조회 :: 3000명이 상세를 본다\n장바구니 :: 900명이 담는다\n결제 시작 :: 450명이 결제 화면에 들어간다\n구매 완료 :: 270명이 결제를 끝낸다\n= 마지막 숫자보다 어느 칸에서 가장 많이 빠졌는지가 볼 것이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 전환율을 하나의 숫자로만 보면 어떻게 되나\n전체 수치만 || 단계별로\n문제 위치 :: 짐작만 한다 || 칸이 지목된다\n개선 순서 :: 전부 손댄다 || 최악부터 손댄다\n광고 판단 :: 더 붓기만 함 || 새는 데를 막음\n= 같은 2.7% 라도 어디서 새는지 알아야 고칠 수 있다\n```\n\n전환율이 낮다는 사실만으로는 할 수 있는 일이 없다. 페이지도 고쳐보고 문구도 바꿔보다가, 정작 사람들이 가장 많이 떠나는 자리는 건드리지 않은 채 끝난다.\n\n단계를 나눠 세면 그 자리가 이름을 갖는다. 방문에서 조회로 30%가 넘어가고 결제 화면에서 60%가 넘어간다는 식으로 적히면, 어느 칸을 먼저 손볼지는 더 이상 취향 문제가 아니다."},"recap":"**\"단계마다 얼마씩 새는지 세어 보는 그 깔때기\"** 라고 읽으면 된다. 전체 전환율은 칸마다의 통과율을 전부 곱한 값이라서, 가장 많이 빠지는 칸 하나가 앞뒤의 노력을 통째로 지운다.","kid":"깔때기는 위가 넓고 아래로 갈수록 좁아지지? 가게에 들어온 백 명이 그 속을 내려가는데 구경만 하다 나가는 사람, 물건을 골라 놓고 나가는 사람, 계산대 앞에서 나가는 사람이 있어서 맨 아래로 나오는 사람은 몇 명뿐이야. 어느 목에서 제일 많이 빠져나가는지 세어 보고 거기부터 넓히는 거야.","check":[{"q":"결제 화면까지 온 450명 중 절반이 사라진다면 어느 단계를 먼저 손봐야 하나","at":"실제 사례"},{"q":"방문자를 두 배로 늘렸는데 구매 수가 그대로일 때 무엇을 의심해야 하나","at":"흔한 오해"},{"q":"칸마다 60%가 통과하는 퍼널을 5칸에서 3칸으로 줄이면 전체 전환율은 어떻게 되나","at":"작동 원리"}],"myths":[{"wrong":"전환율이 낮으면 사람을 더 데려오면 된다","right":"새는 자리를 그대로 두고 위에 더 부으면 광고비만 늘어난다. 아래를 먼저 막는 편이 훨씬 싸게 먹힌다."},{"wrong":"마지막 칸의 숫자가 전환율이다","right":"각 칸의 통과율을 곱한 결과다. 5%짜리 칸 하나가 앞의 모든 노력을 지운다."},{"wrong":"단계를 자세히 나눌수록 정확하다","right":"열 몇 칸으로 쪼개면 칸마다 사람 수가 적어져 무엇이 문제인지 오히려 흐려진다."}],"cases":[{"label":"결제 이탈 확인","note":"결제 화면까지 온 450명 중 절반이 사라지면 결제 절차부터 손본다."},{"label":"가입 폼 개선","note":"입력 항목을 줄인 화면과 기존 화면을 나눠 보여주고 통과율을 비교한다."},{"label":"광고 판단","note":"방문자만 늘고 아래 칸의 수가 그대로면 광고를 늘리는 대신 아래를 먼저 고친다."}],"dia":{"shape":"흐름","title":"방문자 1만 명이 구매까지 가면서 얼마나 남나","rows":[{"who":"방문","what":"10000명이 들어온다"},{"who":"상품 조회","what":"3000명이 상세를 본다"},{"who":"장바구니","what":"900명이 담는다"},{"who":"결제 시작","what":"450명이 결제 화면에 들어간다"},{"who":"구매 완료","what":"270명이 결제를 끝낸다"}],"sum":"마지막 숫자보다 어느 칸에서 가장 많이 빠졌는지가 볼 것이다"}},"pm--gtm":{"definition":"제품이 완성되면 팔린다고 보기 쉽지만, 아는 사람이 없으면 팔릴 자리도 없다. GTM은 출시 전에 대상과 메시지와 채널과 가격을 정해두는 일이다.","name":"Go :: 나가다\nto :: ~를 향해\nMarket :: 사고파는 자리\n= 붙여 읽으면 \"장터로 나가는 길\". 물건이 아니라 나가는 길을 짜는 일이다","analogy":"가게 자리 잡기. 물건이 아무리 좋아도 사람이 안 다니는 골목에 열면 아무도 모른 채 지나간다.","example":"어떤 앱은 나오기도 전에 사전예약 광고가 뜨고, 어떤 앱은 다 만들어진 뒤에도 아무도 모른다.","tryit":"앱 스토어에서 아무 앱이나 골라 소개 글 첫 줄을 읽어 보라. 누구를 향해 쓴 말인지 한 무리가 떠오르면 대상을 좁힌 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n층: 시장 크기를 어디까지 세어야 하나\nTAM :: 이 문제를 가진 전체. 기회의 크기\nSAM :: 우리가 실제로 닿을 수 있는 범위\nSOM :: 당분간 실제로 가져올 몫. 여기부터 시작한다\n= 위쪽 숫자는 설득용이고, 계획을 세우는 건 맨 아래 숫자다\n```\n\n성장 방식은 대개 셋 중 하나에 기운다. 제품 자체가 퍼지게 만드는 쪽, 영업이 직접 만나 파는 쪽, 콘텐츠로 찾아오게 만드는 쪽이다.\n\n어느 쪽이 맞는지는 가격과 결정 방식이 정한다. 값이 크고 결정에 여러 사람이 끼면 영업이 앞에 서고, 혼자 결정하고 바로 써볼 수 있으면 제품이 앞에 선다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **베타 모집** — 출시 몇 달 전부터 쓸 사람을 미리 모아두면 출시일에 반응할 사람이 있는 상태로 시작한다.\n- **채널 좁히기** — 예산이 적을 때 여러 채널에 나누는 대신 한두 곳에 몰아 넣고 반응을 본다.\n- **가격 구간** — 기본을 무료로 열고 필요한 사람만 유료로 넘어가게 하면 퍼지는 속도는 빠르지만 초기 매출은 낮다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **GTM은 마케팅의 다른 이름이다** — 마케팅은 그 안의 한 조각이다. 누구에게 팔지, 얼마에 팔지, 어떻게 전달할지까지가 GTM이다.\n- **제품이 다 되면 그때 시작한다** — 그때 시작하면 출시일에 아는 사람이 없다. 대상과 메시지를 정하는 일은 만드는 동안 같이 한다.\n- **시장이 클수록 좋은 계획이다** — 전체 시장 숫자는 계획이 아니다. 당분간 실제로 가져올 몫을 좁게 잡아야 어디에 얼마를 쓸지가 나온다."}],"figure":"```도해\n흐름: 출시 전에 무엇을 순서대로 정하나\n대상 :: 누구의 어떤 불편을 없앨지 좁힌다\n가치 :: 그 사람에게 무엇이 나아지는지 한 줄로 적는다\n채널 :: 그 사람이 실제로 있는 곳을 고른다\n가격 :: 그 가치에 견줄 값을 정한다\n출시 :: 정해둔 채널로 정해둔 메시지를 내보낸다\n= 앞을 안 정하고 마지막 마디부터 하면, 무엇을 누구에게 말할지가 없다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 계획 없이 출시하면 무엇이 달라지나\nGTM 없이 || GTM 으로\n대상 :: 모두를 향한다 || 한 무리로 좁힘\n메시지 :: 무난하고 흐림 || 그 무리에 맞음\n채널 :: 예산을 흩뿌림 || 한두 곳에 몰음\n= 좁게 정해야 무슨 말을 어디서 할지가 정해진다\n```\n\n만들기만 하다가 출시일에 알리면 그날 아는 사람이 없다. 대상을 \"모두\" 로 두면 광고 문구도 무난해져서 누구도 자기 얘기로 읽지 않는다. 기업용 제품을 개인용 채널에 걸면 예산만 나간다.\n\nGTM은 이 셋을 출시 전에 정해둔다. 대상을 좁히면 메시지가 구체적으로 나오고, 그 대상이 실제로 있는 곳만 골라 예산을 모을 수 있다."},"recap":"**\"장터로 나가기 전에 정해 두는 그 계획\"** 이라고 읽으면 된다. 대상을 좁힐수록 메시지와 채널이 저절로 정해진다. 만드는 일이 끝난 뒤에 시작하면 늦다.","kid":"떡볶이를 아무리 맛있게 만들어도 사람이 안 다니는 골목에 가게를 열면 아무도 못 먹어 보지? 그래서 문을 열기 전에 누가 먹을지, 어느 골목에 열지, 얼마를 받을지부터 정해 두는 거야. 다 만들고 나서 그걸 정하면 문 여는 날 아무도 안 와.","check":[{"q":"예산이 적을 때 채널을 한두 곳으로 좁히는 이유는","at":"해결하는 문제"},{"q":"전체 시장이 3억 개라는 숫자로 다음 분기 계획을 세울 수 없는 이유는","at":"작동 원리"},{"q":"출시일에 아무도 모른 채 지나갔다면 어느 단계를 건너뛴 것인가","at":"그림"}],"myths":[{"wrong":"GTM은 마케팅의 다른 이름이다","right":"마케팅은 그 안의 한 조각이다. 누구에게 팔지, 얼마에 팔지, 어떻게 전달할지까지가 GTM이다."},{"wrong":"제품이 다 되면 그때 시작한다","right":"그때 시작하면 출시일에 아는 사람이 없다. 대상과 메시지를 정하는 일은 만드는 동안 같이 한다."},{"wrong":"시장이 클수록 좋은 계획이다","right":"전체 시장 숫자는 계획이 아니다. 당분간 실제로 가져올 몫을 좁게 잡아야 어디에 얼마를 쓸지가 나온다."}],"cases":[{"label":"베타 모집","note":"출시 몇 달 전부터 쓸 사람을 미리 모아두면 출시일에 반응할 사람이 있는 상태로 시작한다."},{"label":"채널 좁히기","note":"예산이 적을 때 여러 채널에 나누는 대신 한두 곳에 몰아 넣고 반응을 본다."},{"label":"가격 구간","note":"기본을 무료로 열고 필요한 사람만 유료로 넘어가게 하면 퍼지는 속도는 빠르지만 초기 매출은 낮다."}],"dia":{"shape":"흐름","title":"출시 전에 무엇을 순서대로 정하나","rows":[{"who":"대상","what":"누구의 어떤 불편을 없앨지 좁힌다"},{"who":"가치","what":"그 사람에게 무엇이 나아지는지 한 줄로 적는다"},{"who":"채널","what":"그 사람이 실제로 있는 곳을 고른다"},{"who":"가격","what":"그 가치에 견줄 값을 정한다"},{"who":"출시","what":"정해둔 채널로 정해둔 메시지를 내보낸다"}],"sum":"앞을 안 정하고 마지막 마디부터 하면, 무엇을 누구에게 말할지가 없다"}},"pm--kpi":{"definition":"서비스에서 뽑을 수 있는 숫자는 수백 개다. 그중 목표와 직접 이어져서, 움직이면 방향을 바꿔야 하는 몇 개만 KPI다. 나머지는 그냥 통계다.","name":"Key :: 핵심이 되는\nPerformance :: 해낸 정도\nIndicator :: 가리키는 눈금\n= 붙여 읽으면 \"해낸 정도를 가리키는 핵심 눈금\". Key 가 붙었으니 몇 개뿐이어야 한다","analogy":"자동차 계기판. 속도와 연료만 크게 보이고 나머지 수치는 보이지 않는다. 운전에 필요한 것만 골라 앞에 둔 것이다.","example":"앱을 며칠 쓰다 보면 별점을 매겨 달라는 창이 뜬다. 그 별점 평균이 누군가가 매달 확인하는 숫자다.","tryit":"폰의 스크린 타임(사용 시간) 화면을 열어 보라. 앱마다 하루 몇 분 켰는지 나오는데, 만든 쪽도 똑같은 숫자를 본다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"지표 하나를 KPI로 삼기 전에 다섯 가지를 확인한다. 구체적인가(Specific), 잴 수 있는가(Measurable), 이룰 수 있는가(Achievable), 목표와 이어지는가(Relevant), 기한이 있는가(Time-bound). 머리글자를 따서 SMART라고 부른다.\n\n\"사용자 만족도를 높인다\"는 다섯 개 중 하나도 통과하지 못한다. 무엇을 어떻게 재는지도, 언제까지인지도 없다. \"이탈률을 석 달 안에 10%에서 7%로 낮춘다\"로 바꾸면 전부 통과한다.\n\n계산식도 같이 적어둔다. DAU/MAU는 하루 활성 사용자를 월간 활성 사용자로 나눈 값이다. 하루 5만 명에 한 달 20만 명이면 25%이고, 한 사람이 한 달에 평균 7.5일 들어온다는 뜻이다. 이탈률은 월초 1000명 중 100명이 떠났으면 10%다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 제품 KPI vs 개발 KPI","body":"| | 제품 KPI | 개발 KPI |\n|---|---|---|\n| 무엇을 재나 | 사용자의 행동 | 팀이 일하는 방식 |\n| 활동량 | DAU/MAU | 배포 빈도 |\n| 지속 | 재방문율(Retention) | 리드 타임 |\n| 손실 | 이탈률(Churn Rate) | 배포 실패율 |\n\n제품 쪽은 사용자당 평균 수익(ARPU)을, 개발 쪽은 평균 복구 시간(MTTR)을 여기에 더해 보는 경우가 많다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **주간 회의** — 지난주 이탈률과 이번 주 이탈률을 나란히 놓고 그사이에 무엇을 했는지 맞춰본다.\n- **기능 유지 판단** — 새 기능을 켠 뒤 재방문율이 움직였는지를 보고 계속 둘지 접을지 정한다.\n- **장애 회고** — 평균 복구 시간이 지난달보다 길어졌으면 복구 절차의 어느 단계가 막혔는지 찾는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **KPI는 많을수록 좋다** — Key가 붙은 이유가 있다. 스무 개를 걸어두면 어느 것도 안 보게 되고, 어디에 손을 대야 할지도 정해지지 않는다.\n- **숫자가 오르면 잘하고 있는 것이다** — 지표만 올리는 방법은 대개 따로 있다. 가입 수를 KPI로 잡으면 광고비로 올릴 수 있고, 그동안 이탈률은 그대로다.\n- **KPI와 목표는 같은 말이다** — 목표는 가려는 곳이고 KPI는 얼마나 왔는지 보는 눈금이다. 눈금을 목표로 착각하면 눈금만 만지게 된다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **하나만 걸어두지 않는다.** 지표 하나만 보면 그것만 올리고 옆이 무너지는 일이 생긴다. 가입 수를 볼 때는 이탈률을 같이 본다.\n- **계산식을 문서에 적어둔다.** 이탈률을 세는 방법이 팀마다 다르면 같은 숫자를 놓고 서로 다른 이야기를 하게 된다."}],"figure":"```도해\n흐름: 목표 하나가 볼 수 있는 숫자가 되기까지 무엇을 거치나\n목표 :: \"이탈을 줄인다\" 는 아직 말일 뿐이다\n지표 고르기 :: 이탈률로 재기로 정한다\n계산식 :: 월초 인원 대비 떠난 인원의 비율\n기준값 :: 지금 10%, 석 달 뒤 7% 로 정한다\n측정 :: 매달 같은 방식으로 다시 잰다\n판단 :: 안 움직이면 한 일이 틀린 것이다\n= 목표는 재는 방법이 정해진 뒤에야 확인할 수 있는 것이 된다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 재는 숫자를 정해두지 않으면 무엇이 달라지나\nKPI 없이 || KPI 로\n성과 판단 :: 느낌으로 || 숫자로 비교\n우선순위 :: 목소리 큰 쪽 || 지표가 나쁜 쪽\n개선 확인 :: 나아졌는지 모름 || 전후를 비교\n= 재지 않으면 나아졌는지도 알 수 없다\n```\n\n\"사용자 경험을 개선한다\"는 아무도 반대하지 않는 말이다. 반대할 수 없는 이유는 틀렸는지 확인할 방법이 없기 때문이다. 석 달 뒤 회고에서는 각자 기억나는 장면을 근거로 잘됐다거나 아쉬웠다고 말하게 된다.\n\nKPI는 그 말에 눈금을 붙인다. 이탈률 10%를 7%로 낮춘다고 적어두면, 석 달 뒤에 한 일이 맞았는지 틀렸는지가 남는다. 틀렸다는 걸 알 수 있어야 다음에 다른 걸 해볼 수 있다."},"recap":"**\"목표까지 얼마나 왔는지 가리키는 그 눈금\"** 이라고 읽으면 된다. 재는 방법과 기한이 정해져야 지표가 되고, 그렇지 않으면 감상으로 남는다. 눈금을 목표로 착각하면 숫자만 오르고 목표는 제자리에 있다.","kid":"자동차 앞자리에는 지금 얼마나 빠른지, 기름이 얼마나 남았는지만 큼직하게 떠 있지? 잴 수 있는 건 훨씬 많은데 운전에 꼭 필요한 몇 개만 골라서 앞에 둔 거야. 그래야 속도를 줄일지 기름을 넣을지를 그 자리에서 바로 정할 수 있어.","check":[{"q":"\"사용자 경험을 개선한다\"를 목표로 걸면 석 달 뒤 회고에서 무슨 일이 벌어지나","at":"해결하는 문제"},{"q":"가입 수가 두 배로 올랐는데 서비스는 나아지지 않았을 수 있다. 어떻게 그런가","at":"흔한 오해"},{"q":"하루 5만 명, 한 달 20만 명이면 DAU/MAU는 얼마이고 그게 무슨 뜻인가","at":"작동 원리"}],"myths":[{"wrong":"KPI는 많을수록 좋다","right":"Key가 붙은 이유가 있다. 스무 개를 걸어두면 어느 것도 안 보게 되고, 어디에 손을 대야 할지도 정해지지 않는다."},{"wrong":"숫자가 오르면 잘하고 있는 것이다","right":"지표만 올리는 방법은 대개 따로 있다. 가입 수를 KPI로 잡으면 광고비로 올릴 수 있고, 그동안 이탈률은 그대로다."},{"wrong":"KPI와 목표는 같은 말이다","right":"목표는 가려는 곳이고 KPI는 얼마나 왔는지 보는 눈금이다. 눈금을 목표로 착각하면 눈금만 만지게 된다."}],"cases":[{"label":"주간 회의","note":"지난주 이탈률과 이번 주 이탈률을 나란히 놓고 그사이에 무엇을 했는지 맞춰본다."},{"label":"기능 유지 판단","note":"새 기능을 켠 뒤 재방문율이 움직였는지를 보고 계속 둘지 접을지 정한다."},{"label":"장애 회고","note":"평균 복구 시간이 지난달보다 길어졌으면 복구 절차의 어느 단계가 막혔는지 찾는다."}],"dia":{"shape":"흐름","title":"목표 하나가 볼 수 있는 숫자가 되기까지 무엇을 거치나","rows":[{"who":"목표","what":"\"이탈을 줄인다\" 는 아직 말일 뿐이다"},{"who":"지표 고르기","what":"이탈률로 재기로 정한다"},{"who":"계산식","what":"월초 인원 대비 떠난 인원의 비율"},{"who":"기준값","what":"지금 10%, 석 달 뒤 7% 로 정한다"},{"who":"측정","what":"매달 같은 방식으로 다시 잰다"},{"who":"판단","what":"안 움직이면 한 일이 틀린 것이다"}],"sum":"목표는 재는 방법이 정해진 뒤에야 확인할 수 있는 것이 된다"}},"pm--kanban":{"definition":"칸반 지침은 이 방식을 세 가지 실천으로 적는다. 흐름을 정의해 눈에 보이게 하는 것, 흐름 안의 일감을 그때그때 손봐 가며 관리하는 것, 그 흐름을 계속 개선하는 것이다. 판을 거는 일은 그중 첫째의 일부일 뿐이다.","name":"= 일본말 \"간판\". 일이 어디까지 왔는지를 판에 내걸어 누구나 보게 한다는 뜻에서 왔다","analogy":"급식실 배식대에서 쟁반 놓을 자리가 여섯 개뿐이면 한 자리가 비어야 다음 쟁반이 올라간다.","example":"할 일 · 하는 중 · 끝 세 칸에 카드가 붙어 있고 하는 중 칸 제목 옆에 작은 숫자가 하나 적혀 있는 그 화면이다.","tryit":"지금 손을 댔는데 아직 안 끝난 일을 종이에 전부 적어 보라. 그 줄 수가 바로 이 방식이 제일 먼저 재는 숫자다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"흐름을 정의할 때 적어야 하는 것이 정해져 있다. 무엇을 한 항목으로 볼지, 어디를 넘으면 시작이고 어디를 넘으면 끝인지, 그 사이에 어떤 상태들이 있는지, 동시 진행 수를 어떻게 통제할지, 항목이 상태를 넘어갈 때 따르는 규칙은 무엇인지다.\n\n여기서 네 가지 숫자가 나온다. 지침이 이 넷을 이름까지 정해 두었다.\n\n- 동시 진행 수 = 시작했지만 아직 안 끝난 항목의 개수\n- 처리량 = 일정 기간에 끝난 항목 수 ÷ 그 기간\n- 주기 시간 = 끝난 시각 − 시작한 시각\n- 항목 나이 = 오늘 − 시작한 시각\n\n이 기록이 쌓이면 약속 하나를 만들 수 있다. 지침이 든 예가 \"작업 항목의 85%가 8일 이내에 끝난다\" 꼴이고, 이 값은 과거의 주기 시간에 근거해야 한다고 적혀 있다.\n\n네 숫자가 거짓말하는 자리는 하나로 모인다. 시작과 끝의 선이다. 같은 팀이 같은 일을 해도 시작선을 뒤로 밀면 주기 시간이 짧아지고, 끝선을 앞으로 당기면 처리량이 늘어난다. 처리량은 개수만 세므로 큰 항목 하나와 잔일 다섯이 같은 자리에 서지도 않는다. 그래서 이 숫자들을 꺼내기 전에 두 선이 어디 그어져 있는지를 먼저 물어야 한다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 칸반과 스크럼","body":"```도해\n대조: 칸반과 스크럼은 무엇이 다른가\n칸반 |=| 스크럼\n일을 끊는 단위 :: 카드 한 장 || 정해진 기간\n계획 시점 :: 자리 빌 때마다 || 주기 시작 때\n남은 양 재기 :: 처리량과 주기 || 지난 주기 양\n= 칸반은 흐름을 재고 스크럼은 한 바퀴를 잰다\n```\n\n둘은 고르는 문제가 아니다. 칸반 지침은 다른 원칙과 방법과 기법을 이 위에 얹으라고 직접 적어 둔다. 주기는 그대로 두고 판과 상한만 얹는 팀이 많은 이유가 그것이다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **하는 중 칸에 숫자 붙이기** — 그 칸이 상한에 닿으면 새 일을 시작하지 않고 이미 벌인 것을 끝내러 간다.\n- **오래 묵은 카드 찾기** — 시작한 지 며칠 됐는지를 카드마다 보면, 아직 안 끝난 것 중 무엇이 위험한지가 먼저 보인다.\n- **기한 대신 기록으로 답하기** — \"이달 안에요\" 대신 \"지난 기록으로는 열에 여덟이 여드레 안에 끝났습니다\" 로 답한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **칸반은 그냥 할 일 판이다** — 판만 걸고 상한을 안 두면 흐름은 그대로다. 지침은 동시 진행 수를 명시적으로 통제하는 것을 조건으로 적는다.\n- **칸반이 스크럼보다 낫다** — 둘 중 하나를 고르는 문제가 아니다. 지침 자체가 다른 방법과 기법을 함께 얹으라고 적어 둔다.\n- **카드가 빨리 지나가면 잘 되고 있는 것이다** — 끝났다는 선을 어디에 긋느냐로 그 시간은 얼마든지 짧아진다. 선을 먼저 정하지 않으면 그 숫자는 아무 말도 안 한다."}],"figure":"```도해\n흐름: 칸반 판에서 카드 한 장은 어떻게 움직이나\n할 일 :: 아직 시작 안 한 카드가 쌓여 있다\n시작선 :: 이 선을 넘는 순간부터 시간이 재진다\n하는 중 :: 동시에 놓을 수 있는 수가 정해져 있다\n빈자리 :: 하나가 끝나야 다음 카드가 올라온다\n끝 :: 이 선을 넘은 것만 끝난 것으로 센다\n@ 할 일로 :: 자리가 비면 다음 카드를 당겨 온다\n= 밀어 넣는 판이 아니라 자리가 비어야 당겨 오는 판이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 동시에 벌여둔 일의 수를 안 정하면 어떻게 되나\n수를 안 정하면 || 상한을 두면\n일의 개수 :: 계속 늘어난다 || 정해진 수까지\n끝나는 시각 :: 아무도 모른다 || 지난 값으로 잰다\n막힌 자리 :: 안 보인다 || 판에 쌓여 보인다\n= 시작을 줄여야 끝이 늘어난다\n```\n\n일을 시작하는 데는 아무 제한이 없고 끝내는 데만 힘이 든다. 그래서 손댄 것이 계속 쌓이고, 하나하나는 다 진행 중인데 실제로 나가는 것은 없는 상태가 된다. 이때 \"언제 끝나요\" 라는 물음에 답할 근거가 팀에 하나도 없다.\n\n칸반은 동시에 진행하는 수를 명시적으로 통제한다. 지침은 이것을 선택 사항이 아니라 조건으로 적는다. 수가 막히면 새 일을 시작하는 대신 이미 벌인 것을 끝내러 가게 되고, 그러면 끝나는 것이 규칙적으로 쌓여서 다음 물음에 기록으로 답할 수 있게 된다."},"recap":"**\"동시에 벌인 일의 수를 정해 놓고 흐름을 재는 그 판\"** 이라고 읽으면 된다. 판을 거는 것이 아니라 동시 진행 수를 통제하는 것이 이 방식의 조건이고, 시작과 끝의 선을 어디에 긋느냐가 그 위에서 나오는 모든 숫자를 정한다.","kid":"급식 받을 때 쟁반 놓는 자리가 여섯 개뿐이면 한 명이 다 먹고 일어나야 다음 사람이 앉지? 일도 그렇게 한꺼번에 몇 개까지만 벌여 놓기로 미리 정해 두는 거야. 그러면 벌여만 놓고 안 끝나는 게 줄고, 하나가 얼마나 걸리는지도 세어 볼 수 있어.","check":[{"q":"하는 중 칸에 상한을 안 두면 끝나는 시각을 왜 못 잡나","at":"해결하는 문제"},{"q":"카드가 지나간 시간을 재려면 먼저 정해져 있어야 하는 것은","at":"작동 원리"},{"q":"판을 걸었는데도 흐름이 그대로인 팀은 무엇을 빠뜨린 것인가","at":"흔한 오해"}],"myths":[{"wrong":"칸반은 그냥 할 일 판이다","right":"판만 걸고 상한을 안 두면 흐름은 그대로다. 지침은 동시 진행 수를 명시적으로 통제하는 것을 조건으로 적는다."},{"wrong":"칸반이 스크럼보다 낫다","right":"둘 중 하나를 고르는 문제가 아니다. 지침 자체가 다른 방법과 기법을 함께 얹으라고 적어 둔다."},{"wrong":"카드가 빨리 지나가면 잘 되고 있는 것이다","right":"끝났다는 선을 어디에 긋느냐로 그 시간은 얼마든지 짧아진다. 선을 먼저 정하지 않으면 그 숫자는 아무 말도 안 한다."}],"cases":[{"label":"하는 중 칸에 숫자 붙이기","note":"그 칸이 상한에 닿으면 새 일을 시작하지 않고 이미 벌인 것을 끝내러 간다."},{"label":"오래 묵은 카드 찾기","note":"시작한 지 며칠 됐는지를 카드마다 보면, 아직 안 끝난 것 중 무엇이 위험한지가 먼저 보인다."},{"label":"기한 대신 기록으로 답하기","note":"\"이달 안에요\" 대신 \"지난 기록으로는 열에 여덟이 여드레 안에 끝났습니다\" 로 답한다."}],"dia":{"shape":"흐름","title":"칸반 판에서 카드 한 장은 어떻게 움직이나","rows":[{"who":"할 일","what":"아직 시작 안 한 카드가 쌓여 있다"},{"who":"시작선","what":"이 선을 넘는 순간부터 시간이 재진다"},{"who":"하는 중","what":"동시에 놓을 수 있는 수가 정해져 있다"},{"who":"빈자리","what":"하나가 끝나야 다음 카드가 올라온다"},{"who":"끝","what":"이 선을 넘은 것만 끝난 것으로 센다"}],"sum":"밀어 넣는 판이 아니라 자리가 비어야 당겨 오는 판이다","loop":{"who":"할 일로","what":"자리가 비면 다음 카드를 당겨 온다"}}},"pm--mvp":{"definition":"기능을 다 갖춘 뒤에 내놓으면 아무도 안 쓴다는 사실도 그때 알게 된다. MVP는 그 답을 앞으로 당기려고 확인에 필요한 부분만 먼저 만든다.","name":"Minimum :: 가장 적은\nViable :: 살아남을 만한\nProduct :: 내놓는 물건\n= 붙여 읽으면 \"살아남을 만한 가장 적은 물건\". Viable 이 빠지면 그냥 덜 만든 것이다","analogy":"식당을 차리기 전에 푸드트럭부터 세워보는 것. 주방을 다 짓기 전에 그 메뉴가 팔리는지부터 안다.","example":"새로 나온 앱을 깔았는데 되는 기능이 서너 개뿐이고 화면 어딘가에 베타라고 적혀 있다. 그 상태로 내놓은 데는 이유가 있다.","tryit":"깔아 둔 앱 하나를 열어 실제로 쓰는 기능이 몇 개인지 세어 보라. 대개 서넛이고, 나머지는 첫 판에 없어도 됐던 것들이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n층: 기능을 자를 때 무엇부터 남기나\n핵심 가치 :: 이게 없으면 제품이라 할 수 없는 것\n쓸 만한 최소 :: 그 가치를 실제로 쓰게 해주는 것\n편의 :: 있으면 편하지만 없어도 되는 것\n치장 :: 나중에 붙여도 늦지 않은 것\n= 위를 자르면 검증이 안 되고, 아래를 붙들면 출시가 밀린다\n```\n\n사진 공유 서비스라면 핵심은 올리고 링크로 넘기는 것이다. 편집과 앨범 정리와 댓글은 아래 두 층이라 첫 판에서 뺀다.\n\n무엇을 확인하려는지 먼저 적어두는 것이 순서다. 그게 없으면 자르는 기준도 없고, 반응이 나와도 무엇이 확인된 것인지 말할 수 없다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| | MVP | 완제품 |\n|---|---|---|\n| 개발 기간 | 1~3개월 | 6~12개월 |\n| 기능 수 | 3~5개 | 50개 이상 |\n| 목적 | 가설 확인 | 완성 |\n| 방향 바꾸기 | 쉽다 | 이미 늦었다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **데모 영상 먼저** — Dropbox는 제품 없이 동작 영상만 올려 75,000명의 가입을 받고 수요를 확인했다.\n- **직접 손으로 처리** — Airbnb는 자기 아파트 방 세 개를 단순한 웹사이트로 내놓고 예약이 되는지 봤다.\n- **기능 잘라내기** — 사진 공유라면 업로드와 링크 생성까지만 만들고 편집과 앨범은 다음으로 미룬다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **MVP는 대충 만든 제품이다** — 기능 개수는 줄이지만 남긴 기능은 제대로 돌아가야 한다. 업로드가 되다 말면 사람들이 안 쓴다는 결과가 나오는데, 아이디어 때문인지 버그 때문인지 구분할 수 없다.\n- **MVP는 개발 기간을 줄이는 방법이다** — 목적은 시간 절약이 아니라 답을 얻는 것이다. 무엇을 확인하려는지 정하지 않고 기능만 덜어내면 그냥 작은 제품이 나온다.\n- **반응이 없으면 MVP는 실패다** — 안 쓴다는 것도 답이다. 6개월치를 만들기 전에 알아냈다면 MVP는 제 일을 한 것이다."}],"figure":"```도해\n흐름: MVP 로 만들면 무엇이 언제 확인되나\n가설 :: \"사람들이 이걸 돈 내고 쓸 것이다\"\n최소 기능 :: 그 가설을 확인할 것만 만든다\n출시 :: 다 만들기 전에 사람 앞에 내놓는다\n반응 :: 쓰는지 안 쓰는지가 숫자로 나온다\n@ 다음 판 :: 맞았으면 늘리고 틀렸으면 방향을 튼다\n= 오래 만들수록 틀렸다는 사실을 늦게 안다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 다 만들고 내놓으면 무엇을 잃나\n완성 후 출시 || MVP 로\n답을 얻는 때 :: 6개월 뒤 || 1개월 뒤\n틀렸을 때 :: 전부 버린다 || 방향만 튼다\n만든 기능 :: 안 쓰는 게 많다 || 쓰는 것만 있다\n= 늦게 알수록 되돌리는 값이 커진다\n```\n\n기능을 백 개 만들어 내놓았는데 실제로 쓰이는 게 열 개면 아홉은 헛일이다. 문제는 그 아홉이 어느 것인지를 만들기 전에는 알 수 없다는 데 있다.\n\nMVP는 그 질문을 실제 사용자에게 넘긴다. 확인에 필요한 만큼만 만들어 내놓고, 사람들이 쓰는지를 보고 다음에 무엇을 만들지 정한다. 틀렸다면 한 달치를 버리는 것으로 끝난다."},"recap":"**\"확인할 만큼만 만들어 먼저 내놓는 그 물건\"** 이라고 읽으면 된다. 기능을 덜어내는 것이 목적이 아니라 틀렸는지를 일찍 아는 것이 목적이고, 그래서 무엇을 확인하려는지 먼저 정해야 한다.","kid":"식당을 크게 짓기 전에 작은 차에 솥 하나 싣고 나가서 먼저 팔아 보는 거야. 사람들이 줄을 서면 그때 가게를 짓고, 아무도 안 사 먹으면 차만 접으면 되지? 크게 다 지어 놓고 나서 알면 그때는 되돌릴 수가 없어.","check":[{"q":"제품을 만들지 않고 데모 영상만 올렸는데도 검증이 됐다고 보는 이유는","at":"실제 사례"},{"q":"남긴 기능이 자꾸 깨지면 사용자가 안 쓴다는 결과에서 무엇을 알 수 없게 되나","at":"흔한 오해"},{"q":"완성한 다음에 내놓은 쪽이 가설이 틀렸을 때 더 크게 손해 보는 이유는","at":"해결하는 문제"}],"myths":[{"wrong":"MVP는 대충 만든 제품이다","right":"기능 개수는 줄이지만 남긴 기능은 제대로 돌아가야 한다. 업로드가 되다 말면 사람들이 안 쓴다는 결과가 나오는데, 아이디어 때문인지 버그 때문인지 구분할 수 없다."},{"wrong":"MVP는 개발 기간을 줄이는 방법이다","right":"목적은 시간 절약이 아니라 답을 얻는 것이다. 무엇을 확인하려는지 정하지 않고 기능만 덜어내면 그냥 작은 제품이 나온다."},{"wrong":"반응이 없으면 MVP는 실패다","right":"안 쓴다는 것도 답이다. 6개월치를 만들기 전에 알아냈다면 MVP는 제 일을 한 것이다."}],"cases":[{"label":"데모 영상 먼저","note":"Dropbox는 제품 없이 동작 영상만 올려 75,000명의 가입을 받고 수요를 확인했다."},{"label":"직접 손으로 처리","note":"Airbnb는 자기 아파트 방 세 개를 단순한 웹사이트로 내놓고 예약이 되는지 봤다."},{"label":"기능 잘라내기","note":"사진 공유라면 업로드와 링크 생성까지만 만들고 편집과 앨범은 다음으로 미룬다."}],"dia":{"shape":"흐름","title":"MVP 로 만들면 무엇이 언제 확인되나","rows":[{"who":"가설","what":"\"사람들이 이걸 돈 내고 쓸 것이다\""},{"who":"최소 기능","what":"그 가설을 확인할 것만 만든다"},{"who":"출시","what":"다 만들기 전에 사람 앞에 내놓는다"},{"who":"반응","what":"쓰는지 안 쓰는지가 숫자로 나온다"}],"sum":"오래 만들수록 틀렸다는 사실을 늦게 안다","loop":{"who":"다음 판","what":"맞았으면 늘리고 틀렸으면 방향을 튼다"}}},"pm--north-star-metric":{"definition":"팀마다 보는 숫자가 다르면 무엇을 먼저 할지 정하는 자리가 취향 다툼이 된다. 하나를 정해두면 각 기능이 그 숫자를 얼마나 움직이는지로 비교할 수 있다.","name":"North Star :: 북극성\nMetric :: 재는 숫자\n= 붙여 읽으면 \"북극성으로 삼는 숫자\". 여럿이 아니라 하나여야 방향이 된다","analogy":"북극성. 배마다 가는 길은 달라도 같은 별을 보고 방향을 잡는다.","example":"연말이면 음악 앱이 올해 몇 시간을 들었는지 정리해 보여준다. 그 서비스가 무엇을 세고 있는지가 거기 드러난다.","tryit":"유튜브에서 아무 영상이나 열고 제목 바로 아래를 보라. 좋아요 수도 댓글 수도 아닌 조회수가 가장 먼저 나오는데, 그 앱이 무엇을 세고 있는지가 거기 드러난다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"지표를 고르는 기준은 사용자가 실제로 가치를 얻는 순간이다. 음악 서비스라면 가입이 아니라 듣는 시간이고, 숙박 서비스라면 검색이 아니라 예약된 숙박 일수다.\n\n여기에 조건 몇 가지가 붙는다. 매출로 이어져야 하고, 셀 수 있어야 하고, 팀이 움직일 수 있어야 하고, 설명 없이 이해돼야 한다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 제품별 북극성 지표","body":"| 제품 | 지표 | 이유 |\n|---|---|---|\n| Facebook | 일간 활성 사용자 | 매일 쓴다는 건 가치를 느낀다는 것 |\n| Airbnb | 예약된 숙박 일수 | 예약이 곧 제공한 가치 |\n| Spotify | 청취 시간 | 듣는 것이 핵심 경험 |\n| Slack | 전송된 메시지 수 | 메시지가 곧 협업 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **기능 우선순위** — 세 기능 중 무엇을 먼저 할지 각각이 지표를 몇 퍼센트 움직이는지로 비교한다.\n- **허상 걸러내기** — 가입자는 늘었는데 지표가 그대로면 성장이 아니라는 신호로 읽는다.\n- **팀별 분담** — 신규 가입은 마케팅이, 활성화와 재방문은 제품팀이 맡는 식으로 입력 지표를 나눈다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **매출을 북극성으로 삼으면 된다** — 매출은 결과라서 무엇을 고쳐야 할지 알려주지 않는다. 가치를 느낀 순간을 세고, 매출은 그 뒤에 따라오게 둔다.\n- **총 가입자 수가 늘면 성장하는 것이다** — 누적 숫자는 줄어들지 않아서 그래프가 항상 오른쪽 위로 간다. 아무도 안 쓰는 상태에서도 모양은 똑같다.\n- **정교하게 만든 지표일수록 좋다** — 여러 숫자를 섞은 식은 팀이 이해하지 못한다. 이해되지 않는 지표는 방향을 모으지 못하니 지표 노릇을 못 한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **팀이 직접 움직일 수 없는 숫자는 고르지 않는다.** 언론 노출 같은 것은 오르내려도 할 수 있는 일이 없다.\n- **특정 기능의 사용률로 좁히지 않는다.** 제품 전체가 아니라 그 기능만 좋아지는 방향으로 결정이 쏠린다."}],"figure":"```도해\n흐름: 지표 하나를 정하면 결정이 어떻게 달라지나\n후보 :: 가입자, 매출, 체류 시간이 나란히 있다\n기준 :: 사용자가 가치를 느끼는 순간을 고른다\n지표 :: 그 순간을 세는 숫자 하나로 정한다\n평가 :: 기능마다 이 숫자를 얼마나 움직이는지 본다\n결정 :: 가장 크게 움직이는 것부터 한다\n= 무엇을 먼저 할지 다투는 대신 같은 자로 재게 된다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 팀마다 다른 숫자를 보면 어떻게 되나\n지표 없이 || 북극성 지표로\n목표 :: 팀마다 다름 || 하나로 모임\n우선순위 :: 목소리 큰 쪽 || 영향 큰 쪽\n성장 :: 숫자만 커짐 || 쓰는 사람이 늚\n= 같은 자로 재기 시작하면 논쟁이 비교로 바뀐다\n```\n\n한 사람은 가입자를, 한 사람은 매출을, 한 사람은 체류 시간을 늘리자고 한다. 셋 다 틀린 말은 아니라서 회의는 길어지고, 결국 목소리가 큰 쪽이나 만들기 쉬운 쪽으로 정해진다.\n\n숫자가 여러 개면 좋아 보이는 숫자만 골라 보게 되는 문제도 있다. 가입자 100만 명을 달성했는데 실제로 쓰는 사람은 5천 명인 상태에서도 보고할 숫자는 남는다. 지표를 하나로 좁히면 이 회피가 어려워진다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 북극성 지표는 무엇으로 움직이나\n북극성 :: 월간 활성 사용자 같은 숫자 하나\n입력 지표 :: 신규 가입, 활성화율, 재방문, 복귀\n팀의 일 :: 각 입력 지표를 하나씩 맡아 움직인다\n= 북극성은 직접 못 건드린다. 아래를 움직여야 위가 움직인다\n```"},"recap":"**\"다 같이 올려다보는 그 숫자 하나\"** 라고 읽으면 된다. 팀마다 흩어져 있던 목표가 한 방향으로 모이고, 기능의 우선순위를 같은 자로 재게 된다. 다만 이 숫자는 직접 못 건드리고 아래의 작은 숫자들을 움직여야 따라 올라간다.","kid":"밤에 길을 잃으면 다들 북극성을 찾아서 방향을 잡지? 여럿이 무언가를 같이 만들 때도 그렇게 별 하나를 정해 두는 거야. 그러면 무엇부터 할지 다투는 대신 어느 쪽이 그 별에 더 가까워지는지만 보면 돼.","check":[{"q":"가입자가 매달 2천 명씩 느는데도 성장으로 보지 않는 경우는","at":"실제 사례"},{"q":"북극성 지표를 직접 올릴 수 없다면 무엇을 움직여야 하나","at":"구성"},{"q":"매출을 북극성 지표로 두지 않는 이유는","at":"흔한 오해"}],"myths":[{"wrong":"매출을 북극성으로 삼으면 된다","right":"매출은 결과라서 무엇을 고쳐야 할지 알려주지 않는다. 가치를 느낀 순간을 세고, 매출은 그 뒤에 따라오게 둔다."},{"wrong":"총 가입자 수가 늘면 성장하는 것이다","right":"누적 숫자는 줄어들지 않아서 그래프가 항상 오른쪽 위로 간다. 아무도 안 쓰는 상태에서도 모양은 똑같다."},{"wrong":"정교하게 만든 지표일수록 좋다","right":"여러 숫자를 섞은 식은 팀이 이해하지 못한다. 이해되지 않는 지표는 방향을 모으지 못하니 지표 노릇을 못 한다."}],"cases":[{"label":"기능 우선순위","note":"세 기능 중 무엇을 먼저 할지 각각이 지표를 몇 퍼센트 움직이는지로 비교한다."},{"label":"허상 걸러내기","note":"가입자는 늘었는데 지표가 그대로면 성장이 아니라는 신호로 읽는다."},{"label":"팀별 분담","note":"신규 가입은 마케팅이, 활성화와 재방문은 제품팀이 맡는 식으로 입력 지표를 나눈다."}],"dia":{"shape":"흐름","title":"지표 하나를 정하면 결정이 어떻게 달라지나","rows":[{"who":"후보","what":"가입자, 매출, 체류 시간이 나란히 있다"},{"who":"기준","what":"사용자가 가치를 느끼는 순간을 고른다"},{"who":"지표","what":"그 순간을 세는 숫자 하나로 정한다"},{"who":"평가","what":"기능마다 이 숫자를 얼마나 움직이는지 본다"},{"who":"결정","what":"가장 크게 움직이는 것부터 한다"}],"sum":"무엇을 먼저 할지 다투는 대신 같은 자로 재게 된다"}},"pm--okr":{"definition":"Objective 는 어디로 갈지를 말로 적고, Key Results 는 거기 닿았는지를 숫자로 적는다. 앞은 정성적이고 뒤는 정량적이라 역할이 겹치지 않는다.","name":"Objectives :: 가려는 곳\nand :: 그리고\nKey Results :: 닿았음을 잴 숫자\n= 붙여 읽으면 \"가려는 곳, 그리고 닿았는지 잴 숫자\". 앞은 말로 뒤는 숫자로 적는다","analogy":"등산 계획. 정상까지 간다는 게 목표고, 몇 번째 대피소를 언제 지났는지가 지금 어디쯤인지 말해주는 숫자다.","example":"분기마다 목표 한 줄과 그 아래 숫자 칸 서넛을 채워 내라는 시트를 받아본 적이 있다.","tryit":"이번 달에 이루고 싶은 것 한 줄을 적고 그 아래에 다 됐는지 알 숫자 두 개를 붙여 보라. 숫자가 안 떠오르면 그 목표는 아직 흐린 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"Objective 는 한 문장이고 숫자가 들어가지 않는다. 그 아래 KR 은 둘에서 셋이고 전부 숫자다. 숫자에는 기한이 붙는데, 대개 그 분기의 마지막 날이다.\n\n달성률은 100%를 기준으로 보지 않는다. 전부 채웠다는 건 대개 목표를 안전하게 잡았다는 뜻이라, 70% 근처를 정상으로 놓고 읽는다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: OKR vs KPI","body":"| | OKR | KPI |\n|---|---|---|\n| 무엇을 하나 | 도전적 목표를 민다 | 현상을 지키고 잰다 |\n| 주기 | 분기별 | 지속적 |\n| 달성률 | 70% 를 정상으로 본다 | 100% 를 지켜야 한다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **회사 분기 목표** — \"최고의 사용자 경험 제공\"에 NPS 70점, 크래시율 1% 이하, 로딩 2초 이하를 붙인다.\n- **개인 성장 계획** — \"AI 전문가 되기\"에 LLM 프로젝트 3개, 논문 10편, 기술 블로그 12편을 붙인다.\n- **주간 점검** — 목표를 다시 읽는 게 아니라 KR 숫자가 지난주보다 얼마나 움직였는지만 확인한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **KR 을 다 채우는 게 잘한 것이다** — 전부 채웠으면 목표를 쉽게 잡았다고 본다. OKR 은 70% 근처를 정상으로 놓는다.\n- **OKR 은 할 일 목록이다** — 할 일이 아니라 결과다. \"블로그를 쓴다\"가 아니라 \"블로그 12편\"처럼 끝났을 때 잴 수 있는 것으로 적는다.\n- **Objective 도 숫자로 적어야 한다** — 숫자는 KR 이 맡는 자리다. 목표까지 숫자로 적으면 어디로 가는지가 지표 하나로 쪼그라든다."}],"figure":"```도해\n흐름: 한 분기의 OKR 은 어떤 순서로 굴러가나\n분기 시작 :: 어디로 갈지를 한 문장으로 적는다\nKR 붙이기 :: 닿았는지 잴 숫자를 두셋 정한다\n매주 :: 그 숫자가 어디까지 왔는지만 본다\n분기 말 :: KR 마다 달성률을 매긴다\n@ 다음 분기 :: 왜 못 갔는지 보고 목표를 다시 적는다\n= 목표는 말로 적고 진행은 숫자로만 본다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 목표를 말로만 적으면 무엇이 달라지나\n숫자 없이 || KR 을 붙이면\n달성 판단 :: 사람마다 다르다 || 숫자 하나로\n중간 점검 :: 느낌으로 한다 || 진척률로 본다\n목표 수준 :: 쉬운 걸 고른다 || 크게 잡는다\n= 다 했다는 말이 사람마다 다르게 들리는 걸 막는다\n```\n\n\"최고의 사용자 경험 제공\" 같은 목표는 분기가 끝나도 됐는지 안 됐는지 다투게 된다. 누구는 됐다고 하고 누구는 아직이라고 한다. 다툼이 싫으면 애초에 재기 쉬운 목표를 고르게 되고, 그러면 목표가 작아진다.\n\nKR 은 그 자리에 숫자를 놓는다. NPS(추천 의향 점수) 70점, 앱 크래시율 1% 이하, 페이지 로딩 시간 2초 이하처럼 분기 말에 한 번 재면 판정이 끝나는 것들이다. 판정을 숫자에 맡겼기 때문에 목표 쪽은 도리어 크게 잡을 수 있다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 같은 분기에 OKR 은 어디까지 적히나\n회사 :: 최고의 사용자 경험 제공\n팀 :: 회사 KR 하나를 받아 자기 목표로 삼는다\n개인 :: 팀 KR 에 닿을 자기 숫자를 적는다\n= 위층의 KR 이 아래층의 Objective 가 된다\n```"},"recap":"**\"목표 옆에 눈금을 나란히 적는 그 틀\"** 이라고 읽으면 된다. 판정을 숫자에 맡겼기 때문에 목표 자체는 크게 잡을 수 있고, 다 못 채우는 쪽을 정상으로 본다. Objective 는 어디로 갈지를 맡고 Key Results 는 거기 닿았는지를 맡는다.","kid":"산꼭대기까지 가자는 건 어디로 갈지를 정한 거고, 두 번째 쉼터를 몇 시에 지났는지는 지금 어디쯤인지를 알려 주지? 가고 싶은 곳 옆에 그런 눈금을 같이 적어 두는 거야. 그러면 다 왔는지 아닌지를 두고 서로 다르게 말할 일이 없어.","check":[{"q":"KR 세 개를 전부 채웠는데 잘한 게 아니라고 말하는 이유는","at":"흔한 오해"},{"q":"\"사용자 경험을 개선한다\"만 적고 분기를 끝내면 무슨 다툼이 생기나","at":"해결하는 문제"},{"q":"팀의 Objective 는 어디에서 오나","at":"구성"}],"myths":[{"wrong":"KR 을 다 채우는 게 잘한 것이다","right":"전부 채웠으면 목표를 쉽게 잡았다고 본다. OKR 은 70% 근처를 정상으로 놓는다."},{"wrong":"OKR 은 할 일 목록이다","right":"할 일이 아니라 결과다. \"블로그를 쓴다\"가 아니라 \"블로그 12편\"처럼 끝났을 때 잴 수 있는 것으로 적는다."},{"wrong":"Objective 도 숫자로 적어야 한다","right":"숫자는 KR 이 맡는 자리다. 목표까지 숫자로 적으면 어디로 가는지가 지표 하나로 쪼그라든다."}],"cases":[{"label":"회사 분기 목표","note":"\"최고의 사용자 경험 제공\"에 NPS 70점, 크래시율 1% 이하, 로딩 2초 이하를 붙인다."},{"label":"개인 성장 계획","note":"\"AI 전문가 되기\"에 LLM 프로젝트 3개, 논문 10편, 기술 블로그 12편을 붙인다."},{"label":"주간 점검","note":"목표를 다시 읽는 게 아니라 KR 숫자가 지난주보다 얼마나 움직였는지만 확인한다."}],"dia":{"shape":"흐름","title":"한 분기의 OKR 은 어떤 순서로 굴러가나","rows":[{"who":"분기 시작","what":"어디로 갈지를 한 문장으로 적는다"},{"who":"KR 붙이기","what":"닿았는지 잴 숫자를 두셋 정한다"},{"who":"매주","what":"그 숫자가 어디까지 왔는지만 본다"},{"who":"분기 말","what":"KR 마다 달성률을 매긴다"}],"sum":"목표는 말로 적고 진행은 숫자로만 본다","loop":{"who":"다음 분기","what":"왜 못 갔는지 보고 목표를 다시 적는다"}}},"pm--pmf":{"definition":"만든 것이 좋으냐가 아니라, 그것을 필요로 하는 사람들이 실제로 있고 계속 쓰느냐를 묻는 말이다. 스타트업이 성장에 돈을 쓰기 전에 먼저 확인해야 하는 것으로 통한다.","name":"Product :: 만든 물건\nMarket :: 그걸 원하는 사람들\nFit :: 딱 맞음\n= 붙여 읽으면 \"만든 물건이 원하는 사람들에게 딱 맞음\". 물건 쪽만 고쳐서 맞추는 게 아니다","analogy":"퍼즐 조각과 빈칸. 조각을 아무리 정교하게 깎아도 들어갈 자리가 아니면 안 맞고, 자리를 바꾸면 그대로 맞기도 한다.","example":"광고로 도배된 앱을 깔았다가 하루 만에 지운 적이 있고, 광고는 못 봤는데 친구가 먼저 깔라고 한 앱도 있다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n흐름: PMF 에 닿았는지 어떤 순서로 확인하나\n문제 찾기 :: 고객이 정말 아파하는 문제인지 본다\n해법 맞추기 :: 만든 것이 그 문제를 푸는지 본다\n내놓기 :: 얼리 어답터 바깥 사람에게도 쓰게 한다\n재방문 :: 남는 사람 비율이 어디서 멈추는지 본다\n설문 :: 없어지면 매우 실망할 사람이 40%를 넘는지 묻는다\n= 앞 단계를 건너뛰면 마지막 숫자는 착각이 된다\n```\n\n재는 방법이 몇 가지 있고, 하나만으로는 판단하지 않는다.\n\n첫째는 션 엘리스 테스트다. \"이 제품이 사라진다면 어떻게 느끼시겠어요\"라고 묻고 \"매우 실망할 것이다\"를 고른 비율을 본다. 통상 40% 이상을 기준으로 본다.\n\n둘째는 리텐션 곡선이다. 가입한 주를 기준으로 몇 주 뒤까지 남아 있는지를 그려보면, PMF가 없는 제품은 끝까지 떨어져 2~3% 근처로 가고, 있는 제품은 어느 선에서 떨어지기를 멈추고 평탄해진다. 그 선이 40~60% 근처면 좋은 신호로 본다.\n\n셋째는 NPS와 유기적 성장이다. 0에서 10까지 추천 의향을 묻고 9~10을 고른 비율에서 0~6을 고른 비율을 뺀다. 여기에 광고 없이 들어온 비율과 월간 성장률을 같이 본다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: PMF 로 착각하기 쉬운 신호","body":"| 겉으로 보이는 것 | 함정 | 대신 확인할 것 |\n|---|---|---|\n| 얼리 어답터의 열광 | 좁은 틈새에서만 통할 수 있다 | 일반 사용자도 같은 반응인가 |\n| 가입 수가 많다 | 가입만 하고 쓰지 않는다 | 가입한 뒤 실제로 쓰는 비율 |\n| 언론에 소개됐다 | 일시적인 관심이다 | 노출이 끝난 뒤에도 늘어나나 |\n| 투자를 받았다 | 미래 가능성에 건 돈이다 | 지금 사용자가 만족하고 있나 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **설문이 기준에 못 미칠 때** — \"매우 실망\"이 40%를 넘지 않으면 대상 고객을 좁혀 다시 재고 그 안에서 넘는지 본다.\n- **리텐션 곡선이 눕지 않는 제품** — 몇 주가 지나도 계속 떨어지면 기능을 더 붙이기 전에 문제 정의부터 다시 본다.\n- **광고를 잠시 꺼보는 실험** — 유료 유입을 멈추고 신규 가입이 어디까지 떨어지는지로 유기적 성장을 가늠한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **PMF는 한 번 달성하면 끝난다** — 시장도 경쟁도 계속 움직인다. 예전에 맞았던 제품이 지금도 맞는지는 다시 재봐야 안다.\n- **사용자가 늘고 있으면 PMF가 있는 것이다** — 광고비로 산 성장은 광고를 끄면 멈춘다. 봐야 할 것은 얼마나 들어왔느냐가 아니라 들어온 사람이 남느냐다.\n- **PMF는 제품을 잘 만들면 생긴다** — 제품 혼자 정하지 않는다. 같은 제품이라도 대상 고객을 바꾸면 결과가 달라지므로 시장 쪽을 바꾸는 것도 답이 된다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **평균으로 재면 안 보인다.** 전체 사용자를 뭉쳐 재면 40%를 못 넘지만, 특정 집단만 떼어 보면 넘는 경우가 있다. 그 집단이 시작점이다.\n- **초기 사용자만으로 판단하지 않는다.** 얼리 어답터는 원래 새것에 관대하다. 그 바깥 사람이 같은 반응을 보이는지가 관건이다."}],"figure":"```도해\n대조: 제품이 시장에 맞아떨어지면 무엇이 달라지나\nPMF 이전 || PMF 이후\n가입 100명 :: 5명만 남는다 || 80명이 남는다\n재방문율 :: 계속 떨어진다 || 어느 선에서 멈춤\n광고를 끄면 :: 신규가 끊긴다 || 입소문이 남는다\n= 새는 양동이에 물을 더 붓는다고 물이 차지는 않는다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"PMF가 없는 제품도 광고비를 쓰면 가입자는 늘어난다. 문제는 들어온 사람이 남지 않는다는 것이다. 광고를 끄는 순간 유입이 멈추고, 그동안 쓴 돈은 남는 사용자로 바뀌지 않는다.\n\nPMF를 먼저 확인하자는 말은 성장을 늦추자는 뜻이 아니다. 남는 사람이 있는 상태에서 돈을 부어야 그 돈이 쌓인다는 순서의 문제다."},"recap":"**\"조각이 빈칸에 딱 맞아 들어간 그 상태\"** 라고 읽으면 된다. 션 엘리스 테스트, 리텐션 곡선, NPS와 유기적 성장을 함께 보고 판단하며 하나만으로는 정하지 않는다. 이것을 확인하기 전에 성장에 돈을 쓰면 대부분 새어 나간다.","kid":"퍼즐 조각을 아무리 예쁘게 깎아도 맞는 자리가 아니면 안 들어가지? 조각을 다시 깎아 볼 수도 있고, 아예 다른 빈칸을 찾아볼 수도 있어. 딱 맞은 조각은 손을 놔도 그대로 있는데, 안 맞는 건 계속 눌러 주고 있어야 겨우 붙어 있어.","check":[{"q":"사용자가 매달 늘고 있는데도 PMF가 없다고 보는 경우는 언제인가","at":"해결하는 문제"},{"q":"리텐션 곡선이 평탄해지는 것이 왜 좋은 신호인가","at":"작동 원리"},{"q":"언론에 소개돼 가입이 몰렸다. 이것만으로 PMF라고 할 수 없는 이유는","at":"비교"}],"myths":[{"wrong":"PMF는 한 번 달성하면 끝난다","right":"시장도 경쟁도 계속 움직인다. 예전에 맞았던 제품이 지금도 맞는지는 다시 재봐야 안다."},{"wrong":"사용자가 늘고 있으면 PMF가 있는 것이다","right":"광고비로 산 성장은 광고를 끄면 멈춘다. 봐야 할 것은 얼마나 들어왔느냐가 아니라 들어온 사람이 남느냐다."},{"wrong":"PMF는 제품을 잘 만들면 생긴다","right":"제품 혼자 정하지 않는다. 같은 제품이라도 대상 고객을 바꾸면 결과가 달라지므로 시장 쪽을 바꾸는 것도 답이 된다."}],"cases":[{"label":"설문이 기준에 못 미칠 때","note":"\"매우 실망\"이 40%를 넘지 않으면 대상 고객을 좁혀 다시 재고 그 안에서 넘는지 본다."},{"label":"리텐션 곡선이 눕지 않는 제품","note":"몇 주가 지나도 계속 떨어지면 기능을 더 붙이기 전에 문제 정의부터 다시 본다."},{"label":"광고를 잠시 꺼보는 실험","note":"유료 유입을 멈추고 신규 가입이 어디까지 떨어지는지로 유기적 성장을 가늠한다."}],"dia":{"shape":"대조","title":"제품이 시장에 맞아떨어지면 무엇이 달라지나","rows":[{"who":"","what":"PMF 이전 || PMF 이후","left":"PMF 이전","right":"PMF 이후"},{"who":"가입 100명","what":"5명만 남는다 || 80명이 남는다","left":"5명만 남는다","right":"80명이 남는다"},{"who":"재방문율","what":"계속 떨어진다 || 어느 선에서 멈춤","left":"계속 떨어진다","right":"어느 선에서 멈춤"},{"who":"광고를 끄면","what":"신규가 끊긴다 || 입소문이 남는다","left":"신규가 끊긴다","right":"입소문이 남는다"}],"sum":"새는 양동이에 물을 더 붓는다고 물이 차지는 않는다"}},"pm--persona":{"definition":"회의에서 \"사용자\"라고 말하면 사람마다 다른 얼굴을 떠올린다. 인터뷰와 사용 기록에서 반복되는 특징만 모아 이름과 하루 일과가 있는 한 사람으로 만들어두면, 그다음부터는 모두가 같은 사람을 놓고 이야기하게 된다.","name":"= 옛 연극에서 배우가 쓰던 가면을 이르던 라틴 말. 실존 인물이 아니라 쓰고 벗는 얼굴이라는 뜻이 남아 있다","analogy":"여러 명의 증언을 모아 그린 몽타주. 실존 인물은 아니지만 특징은 실제에서 나온다.","example":"어떤 앱은 글씨가 크고 단추가 몇 개뿐인데 어떤 앱은 기능이 빽빽하다. 만들 때 머릿속에 둔 사람이 달라서 갈린 것이다.","tryit":"같은 일을 하는 앱 두 개를 나란히 열어 보라. 은행 앱과 간편송금 앱은 둘 다 돈을 보내는 앱인데 첫 화면 단추 개수가 크게 다르다. 하는 일이 같은데 화면이 갈렸다면 만들 때 떠올린 사람이 달랐던 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"만드는 순서는 수집이 먼저다. 인터뷰 같은 대화 기록과 사용 로그 같은 숫자를 함께 본다. 한쪽만으로는 무엇을 하는지는 알아도 왜 하는지는 모른다.\n\n다음은 묶는 일이다. 나이나 직업이 아니라 행동이 비슷한 사람끼리 나눈다. 같은 서른 살이라도 매일 쓰는 사람과 한 달에 한 번 쓰는 사람은 전혀 다른 것을 원한다.\n\n주로 겨냥할 사람 한둘을 정하고, 겨냥하지 않을 사람도 적어둔다. 제외 대상을 적어두면 어디에 힘을 쓰지 않을지가 같이 정해진다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **기능 순서 정하기** — 후보 기능을 이 사람의 고충에 닿는 것부터 줄 세운다.\n- **회의 기준 삼기** — \"이 사람이라면 이 단계에서 그만둘까\"로 물으면 취향 다툼이 줄어든다.\n- **메시지 정하기** — 이 사람이 실제로 쓴 표현을 그대로 안내 문구에 쓴다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **페르소나는 상상해서 만드는 캐릭터다** — 이름과 사진은 지어내지만 특징은 조사에서 나온다. 근거 없이 만들면 팀의 짐작을 사람 모양으로 적어둔 것에 그친다.\n- **여러 명 만들수록 촘촘해진다** — 열 명을 만들면 겨냥한 사람이 없는 것과 같다. 결정을 갈라주지 못하는 페르소나는 늘어나기만 한다.\n- **나이와 직업을 적으면 페르소나다** — 그건 명단이다. 무엇 때문에 쓰고 어디서 막히는지가 없으면 어떤 결정도 갈리지 않는다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **한 번 만들고 두면 옛날 사람이 남는다.** 사용자는 바뀌는데 문서는 안 바뀌어서, 몇 해 전 조사로 지금 결정을 하게 된다.\n- **팀에서 아무도 이름을 부르지 않으면 안 쓰이는 것이다.** 회의에서 인용되지 않는 페르소나는 만들어둔 파일일 뿐이다."}],"figure":"```도해\n흐름: 인터뷰 기록이 어떻게 한 사람으로 좁혀지나\n수집 :: 인터뷰, 문의 내역, 사용 기록을 모은다\n묶기 :: 비슷하게 행동하는 사람끼리 나눈다\n고르기 :: 가장 큰 무리를 대표로 삼는다\n쓰기 :: 목표, 고충, 하루 일과를 적는다\n판단 :: 회의에서 이 사람을 기준으로 정한다\n= 여러 명에게서 나온 것을 한 사람의 얼굴로 줄여둔 것이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 대상을 사용자들이라고만 부르면 어떻게 되나\n페르소나 없이 || 페르소나로\n회의 기준 :: 각자 다른 사람 || 같은 한 사람\n기능 결정 :: 목소리 큰 쪽 || 이 사람의 고충\n겨냥 범위 :: 모두를 겨냥 || 한 무리를 겨냥\n= 누구를 위한 것인지 정해야 무엇을 뺄지도 정해진다\n```\n\n\"사용자가 이걸 원할까요\"라는 질문은 끝나지 않는다. 각자 머릿속의 사용자가 다르기 때문에, 서로 다른 사람 얘기를 하면서 같은 단어를 쓰고 있는 것이다. 결론이 안 나면 결국 직급이나 목소리가 정한다.\n\n한 사람으로 좁혀 적어두면 질문이 바뀐다. \"이 사람이라면 이 화면에서 무엇을 할까\"는 답을 맞춰볼 수 있는 질문이고, 답이 갈리면 무엇을 더 조사해야 하는지도 드러난다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 페르소나에 무엇이 적혀야 쓸모가 있나\n고충과 목표 :: 왜 쓰는지, 어디서 막히는지. 실제로 한 말을 근거로 붙인다\n행동 :: 언제 어떻게 쓰는지. 하루 일과\n인구통계 :: 나이, 직업, 사는 곳\n= 아래만 있으면 명단이고, 위가 있어야 결정에 쓰인다\n```"},"recap":"**\"여럿에게서 뽑아 한 사람으로 줄인 그 얼굴\"** 이라고 읽으면 된다. 나이와 직업이 아니라 무엇 때문에 쓰고 어디서 막히는지가 적혀 있어야 결정을 가른다. 겨냥할 사람을 정하는 일은 곧 겨냥하지 않을 사람을 정하는 일이다.","kid":"본 사람 여럿한테 물어서 얼굴 하나를 그려 놓은 그림 있지? 그 사람이 진짜로 있는 건 아니지만 눈매도 말버릇도 다 실제로 들은 거야. 그런 사람을 하나 정해 두면 다들 \"이 사람이면 어떡할까\" 하고 같은 얼굴을 떠올리면서 정하게 돼.","check":[{"q":"\"사용자들이 원할까요\"라는 질문이 회의에서 잘 안 끝나는 이유는","at":"해결하는 문제"},{"q":"나이와 직업만 적힌 페르소나로 기능 순서를 정하기 어려운 이유는","at":"구성"},{"q":"페르소나를 열 명 만들면 무엇이 나빠지나","at":"흔한 오해"}],"myths":[{"wrong":"페르소나는 상상해서 만드는 캐릭터다","right":"이름과 사진은 지어내지만 특징은 조사에서 나온다. 근거 없이 만들면 팀의 짐작을 사람 모양으로 적어둔 것에 그친다."},{"wrong":"여러 명 만들수록 촘촘해진다","right":"열 명을 만들면 겨냥한 사람이 없는 것과 같다. 결정을 갈라주지 못하는 페르소나는 늘어나기만 한다."},{"wrong":"나이와 직업을 적으면 페르소나다","right":"그건 명단이다. 무엇 때문에 쓰고 어디서 막히는지가 없으면 어떤 결정도 갈리지 않는다."}],"cases":[{"label":"기능 순서 정하기","note":"후보 기능을 이 사람의 고충에 닿는 것부터 줄 세운다."},{"label":"회의 기준 삼기","note":"\"이 사람이라면 이 단계에서 그만둘까\"로 물으면 취향 다툼이 줄어든다."},{"label":"메시지 정하기","note":"이 사람이 실제로 쓴 표현을 그대로 안내 문구에 쓴다."}],"dia":{"shape":"흐름","title":"인터뷰 기록이 어떻게 한 사람으로 좁혀지나","rows":[{"who":"수집","what":"인터뷰, 문의 내역, 사용 기록을 모은다"},{"who":"묶기","what":"비슷하게 행동하는 사람끼리 나눈다"},{"who":"고르기","what":"가장 큰 무리를 대표로 삼는다"},{"who":"쓰기","what":"목표, 고충, 하루 일과를 적는다"},{"who":"판단","what":"회의에서 이 사람을 기준으로 정한다"}],"sum":"여러 명에게서 나온 것을 한 사람의 얼굴로 줄여둔 것이다"}},"pm--product-roadmap":{"definition":"기능 목록이 아니라 순서와 이유를 담는 자리다. 그래서 잘 쓰인 로드맵은 새 요청이 들어왔을 때 무엇을 뒤로 미룰지 답하는 데 쓰인다.","name":"Product :: 만들고 있는 것\nRoad :: 가는 길\nMap :: 펼쳐 놓은 그림\n= 붙여 읽으면 \"만드는 것이 갈 길을 펼친 그림\". 지도라고 했지 시간표라고 하지 않았다","analogy":"여행 일정표. 며칠에 어디를 간다까지는 적지만, 몇 시 몇 분에 무엇을 한다까지는 적지 않는다.","example":"게임이나 앱이 올해 무엇을 언제쯤 내놓겠다고 공지로 올릴 때가 있다. 그 한 장을 사용자에게도 보여준 것이다.","tryit":"자주 하는 게임이나 앱의 공지 게시판에서 업데이트 계획 글을 찾아 읽어 보라. 날짜 대신 분기나 '다음'으로 적힌 곳이 많다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"우선순위는 대개 두 축으로 잡는다. 이 일이 얼마나 효과가 있는지와 품이 얼마나 드는지다. 효과가 크고 품이 적은 것부터 하고, 품이 많이 드는 큰 건은 분기 하나를 통째로 잡아 계획한다.\n\nRICE 처럼 점수를 매기는 방식도 쓴다. 얼마나 많은 사용자에게 닿는지, 얼마나 큰 변화인지, 그 추정을 얼마나 믿는지를 곱하고 드는 품으로 나눈다. 숫자가 정답을 주지는 않지만 왜 이 순서인지 설명할 근거는 된다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| 유형 | 적는 방식 | 강점 | 약점 |\n|---|---|---|---|\n| 기능 중심 | 분기별 기능 목록 | 구체적이다 | 바뀌면 흔들린다 |\n| 테마 중심 | 분기별 집중 주제 | 유연하다 | 덜 구체적이다 |\n| Now-Next-Later | 시간 대신 순서 | 변화에 강하다 | 일정이 흐리다 |\n| 결과 중심 | 목표 숫자와 방법 | 이유가 분명하다 | 실행이 추상적이다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **분기 테마** — 한 분기를 \"유지율 개선\"으로 묶고 그 아래에 서너 가지 일을 둔다.\n- **Now-Next-Later** — 날짜를 못 박지 않고 지금 하는 일, 다음에 할 일, 나중에 볼 일로 나눠 적는다.\n- **월 단위 갱신** — 매달 한 번 진척을 보고 순서를 다시 잡은 뒤 바뀐 내용을 팀에 알린다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **로드맵은 날짜가 박힌 일정표다** — 날짜를 못 박을수록 오래 산다. 분기나 Now/Next/Later 로 적는 곳이 많은 이유다.\n- **한 번 정하면 그대로 간다** — 상황이 바뀌면 고치는 문서다. 몇 달째 그대로인 로드맵은 아무도 안 보고 있다는 뜻이다.\n- **기능을 많이 적을수록 좋은 로드맵이다** — 항목이 늘면 무엇이 중요한지가 사라진다. 한 구간에 서너 개로 줄이는 편이 낫다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **왜 하는지를 같이 적는다.** 기능 이름만 있는 줄은 몇 주 뒤에 아무도 이유를 설명하지 못한다.\n- **갱신하지 않을 문서라면 만들지 않는다.** 오래된 로드맵은 없는 것보다 나쁘다. 사람들이 틀린 일정을 믿고 움직인다."}],"figure":"```도해\n흐름: 로드맵 한 장은 어떻게 만들어지나\n비전 :: 1~3년 뒤 제품이 어떤 모습인지 정한다\n목표 :: 그 모습에 닿기 위한 숫자를 잡는다\n테마 :: 분기마다 무엇에 집중할지 묶는다\n후보 :: 하고 싶은 일들을 늘어놓는다\n우선순위 :: 효과와 드는 품으로 줄을 세운다\n공유 :: 팀과 이해관계자가 같은 그림을 본다\n= 기능 목록부터 나오면 왜 하는지가 빠진 채로 굳는다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 로드맵이 없으면 팀에서 무슨 일이 벌어지나\n로드맵 없이 || 로드맵으로\n다음 할 일 :: 물어봐야 안다 || 문서에 있다\n요청이 몰릴 때 :: 다 받는다 || 순서를 댄다\n일정 질문 :: 답이 사람마다 || 한 곳을 본다\n= 우선순위를 매번 말로 정하면 말한 사람 수만큼 우선순위가 생긴다\n```\n\n영업은 고객이 요청한 기능을, 마케팅은 캠페인에 필요한 기능을, 대표는 어제 본 경쟁사 기능을 먼저 해달라고 한다. 기준이 문서로 없으면 목소리 큰 순서가 우선순위가 되고, 개발팀은 셋을 동시에 시작한다.\n\n로드맵은 그 판단을 한 곳에 모아 적어둔다. 새 요청이 들어오면 \"지금 것 대신 이것을 할지\"를 묻는 대화로 바뀌고, 일정 질문에는 문서 한 곳을 가리키면 된다."},"recap":"**\"무엇을 왜 먼저 하는지 펼쳐 놓은 그 지도\"** 라고 읽으면 된다. 날짜를 못 박기보다 순서와 이유를 담아야 상황이 바뀌어도 살아남는다. 갱신을 멈추는 순간 문서가 아니라 오해의 원인이 된다.","kid":"여행 갈 때 며칠에 어디를 갈지는 적어 두지만 몇 시 몇 분에 뭘 할지까지는 안 적지? 그렇게 적어 두면 비가 와도 순서만 바꾸면 되는데, 분까지 적어 두면 하나만 어긋나도 뒤가 전부 틀어져. 왜 거기를 가는지도 같이 적어 둬야 다른 데 가자는 말이 나왔을 때 답할 수 있어.","check":[{"q":"영업과 마케팅과 대표가 각각 다른 기능을 먼저 해달라고 한다. 로드맵이 이 자리에서 하는 일은 무엇인가","at":"해결하는 문제"},{"q":"\"3월 15일 로그인 완료\"라고 적는 것이 왜 위험한가","at":"흔한 오해"},{"q":"새 요청 두 개 중 무엇을 먼저 할지 근거를 대려면 무엇을 견주어 보나","at":"작동 원리"}],"myths":[{"wrong":"로드맵은 날짜가 박힌 일정표다","right":"날짜를 못 박을수록 오래 산다. 분기나 Now/Next/Later 로 적는 곳이 많은 이유다."},{"wrong":"한 번 정하면 그대로 간다","right":"상황이 바뀌면 고치는 문서다. 몇 달째 그대로인 로드맵은 아무도 안 보고 있다는 뜻이다."},{"wrong":"기능을 많이 적을수록 좋은 로드맵이다","right":"항목이 늘면 무엇이 중요한지가 사라진다. 한 구간에 서너 개로 줄이는 편이 낫다."}],"cases":[{"label":"분기 테마","note":"한 분기를 \"유지율 개선\"으로 묶고 그 아래에 서너 가지 일을 둔다."},{"label":"Now-Next-Later","note":"날짜를 못 박지 않고 지금 하는 일, 다음에 할 일, 나중에 볼 일로 나눠 적는다."},{"label":"월 단위 갱신","note":"매달 한 번 진척을 보고 순서를 다시 잡은 뒤 바뀐 내용을 팀에 알린다."}],"dia":{"shape":"흐름","title":"로드맵 한 장은 어떻게 만들어지나","rows":[{"who":"비전","what":"1~3년 뒤 제품이 어떤 모습인지 정한다"},{"who":"목표","what":"그 모습에 닿기 위한 숫자를 잡는다"},{"who":"테마","what":"분기마다 무엇에 집중할지 묶는다"},{"who":"후보","what":"하고 싶은 일들을 늘어놓는다"},{"who":"우선순위","what":"효과와 드는 품으로 줄을 세운다"},{"who":"공유","what":"팀과 이해관계자가 같은 그림을 본다"}],"sum":"기능 목록부터 나오면 왜 하는지가 빠진 채로 굳는다"}},"pm--retention":{"definition":"한 달에 만 명이 가입해도 다음 달에 오백 명만 남으면 사용자 수는 늘지 않는다. 신규 유입은 들어오는 양을 재고, 리텐션은 남는 양을 잰다.","name":"= 붙잡아 둠이라는 뜻. 새로 데려오는 쪽이 아니라 이미 온 사람을 놓치지 않는 쪽을 재는 말이다","analogy":"구멍 난 양동이. 위에서 물을 아무리 부어도 바닥이 새면 수위가 오르지 않는다.","example":"한동안 안 열었던 앱에서 오랜만이라며 알림이 오기 시작한다. 안 돌아오는 사람을 세다가 내 이름이 걸린 것이다.","tryit":"홈 화면을 넘기며 최근 한 달 동안 한 번도 안 연 앱을 세어 보라. 그 앱들에게는 내가 빠져나간 쪽이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"같은 날 가입한 사람들을 한 묶음으로 묶고, 그 묶음이 며칠째에 얼마나 남았는지를 센다. 이렇게 묶어 보는 방식을 코호트라고 부른다. 전체 활성 사용자 수로는 신규와 기존이 섞여서 어느 쪽이 움직였는지 알 수 없다.\n\n곡선의 모양이 값보다 중요하다. 계속 아래로 내려가면 언젠가 아무도 남지 않는다. 어느 지점에서 평평해지면 그 높이만큼은 계속 쌓인다.\n\n```도해\n층: 리텐션을 올리려면 어디부터 보나\n첫 화면 :: 가입 직후 무엇을 할지 보이는가\n첫 성공 :: 이 제품이 무엇을 해주는지 겪었는가\n재방문 이유 :: 다음에 다시 열 계기가 있는가\n습관 :: 열어보는 것이 일과에 들어갔는가\n= 아래 단계는 위 단계를 통과한 사람에게만 생긴다\n```"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **가입 첫날 이탈** — 가입은 하는데 첫 화면에서 뭘 해야 할지 몰라 그대로 나간다. 처음 할 일을 하나만 남기면 달라진다.\n- **일주일 뒤 이탈** — 처음에는 써봤는데 다시 열 이유가 없다. 알림이나 주간 요약처럼 돌아올 계기를 만든다.\n- **곡선이 평평해지는 지점** — 30일 이후로 값이 거의 안 떨어지면 그만큼은 계속 남는 사용자라고 볼 수 있다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **리텐션은 마케팅 지표다** — 제품 지표에 가깝다. 광고로 사람을 데려올 수는 있어도 다시 오게 만드는 것은 제품이 하는 일이다.\n- **숫자가 높을수록 좋은 제품이다** — 제품 종류마다 기준이 다르다. 매일 쓰는 도구와 몇 달에 한 번 쓰는 서비스를 같은 값으로 비교할 수 없다.\n- **떨어지는 건 초기니까 당연하다** — 떨어지는 것 자체는 정상이지만, 평평해지지 않고 끝까지 내려가면 남는 사용자가 없다는 뜻이다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **재방문의 정의를 먼저 정한다.** 앱을 열기만 한 것과 실제로 무언가 한 것은 전혀 다른 숫자가 된다.\n- **알림을 늘려 값을 올리지 않는다.** 잠깐 오르지만 그다음에 앱을 지우는 사람이 늘어난다."}],"figure":"```도해\n흐름: 리텐션은 무엇을 세는 값인가\n가입 :: 같은 날 가입한 사람들을 한 묶음으로 본다\n1 일 후 :: 그중 몇 명이 다시 왔는지 센다\n7 일 후 :: 다시 센다. 대개 여기서 많이 빠진다\n30 일 후 :: 또 센다\n곡선 :: 날짜별 비율을 이으면 모양이 나온다\n= 중요한 건 값 하나가 아니라 곡선이 어디서 평평해지는가다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 가입자 수만 보면 어떻게 되나\n가입자 수만 || 리텐션까지\n성장 판단 :: 늘어난다고 본다 || 남는지를 본다\n마케팅 :: 계속 부어야 한다 || 부은 만큼 쌓인다\n제품 문제 :: 안 보인다 || 빠지는 지점이 보인다\n= 들어오는 양이 아니라 남는 양이 성장을 정한다\n```\n\n가입자 수는 마케팅을 늘리면 같이 올라간다. 그래서 이 숫자만 보면 제품이 잘되고 있는지 알 수 없다. 광고를 멈춘 다음 달에야 실제 상태가 드러난다.\n\n리텐션은 그 상태를 먼저 보여준다. 며칠째에 크게 빠지는지가 보이면 제품의 어느 지점이 문제인지도 좁혀진다. 첫날에 빠지면 처음 화면 문제이고, 일주일 뒤에 빠지면 계속 쓸 이유가 없다는 뜻이다."},"recap":"**\"들어온 사람이 얼마나 남았는지 그 비율\"** 이라고 읽으면 된다. 값 하나보다 곡선이 어디서 평평해지는지가 중요하고, 이 값을 보지 않으면 가입자 수가 늘어도 실제로 쌓이는 것이 없다.","kid":"바닥에 구멍 난 양동이는 물을 아무리 부어도 안 차지? 새 사람이 들어와도 금방 나가 버리면 그것과 똑같아. 그래서 더 붓는 것보다 어디가 새는지 먼저 찾아 막아야 물이 차오르기 시작해.","check":[{"q":"가입자 수가 매달 늘고 있는데도 사용자가 안 쌓인다면 무엇을 보고 있어야 하나","at":"해결하는 문제"},{"q":"가입 첫날에 크게 빠지는 것과 일주일 뒤에 빠지는 것은 각각 무엇을 가리키나","at":"실제 사례"},{"q":"전체 활성 사용자 수 대신 같은 날 가입한 묶음을 따로 보는 이유는","at":"작동 원리"}],"myths":[{"wrong":"리텐션은 마케팅 지표다","right":"제품 지표에 가깝다. 광고로 사람을 데려올 수는 있어도 다시 오게 만드는 것은 제품이 하는 일이다."},{"wrong":"숫자가 높을수록 좋은 제품이다","right":"제품 종류마다 기준이 다르다. 매일 쓰는 도구와 몇 달에 한 번 쓰는 서비스를 같은 값으로 비교할 수 없다."},{"wrong":"떨어지는 건 초기니까 당연하다","right":"떨어지는 것 자체는 정상이지만, 평평해지지 않고 끝까지 내려가면 남는 사용자가 없다는 뜻이다."}],"cases":[{"label":"가입 첫날 이탈","note":"가입은 하는데 첫 화면에서 뭘 해야 할지 몰라 그대로 나간다. 처음 할 일을 하나만 남기면 달라진다."},{"label":"일주일 뒤 이탈","note":"처음에는 써봤는데 다시 열 이유가 없다. 알림이나 주간 요약처럼 돌아올 계기를 만든다."},{"label":"곡선이 평평해지는 지점","note":"30일 이후로 값이 거의 안 떨어지면 그만큼은 계속 남는 사용자라고 볼 수 있다."}],"dia":{"shape":"흐름","title":"리텐션은 무엇을 세는 값인가","rows":[{"who":"가입","what":"같은 날 가입한 사람들을 한 묶음으로 본다"},{"who":"1 일 후","what":"그중 몇 명이 다시 왔는지 센다"},{"who":"7 일 후","what":"다시 센다. 대개 여기서 많이 빠진다"},{"who":"30 일 후","what":"또 센다"},{"who":"곡선","what":"날짜별 비율을 이으면 모양이 나온다"}],"sum":"중요한 건 값 하나가 아니라 곡선이 어디서 평평해지는가다"}},"pm--retrospective":{"definition":"스크럼 지침은 이 자리를 한 주기의 마지막 행사로 두고, 한 달짜리 주기면 최대 세 시간까지로 잡는다. 애자일 선언의 열두째 원칙도 같은 말을 한다. 팀이 정기적으로 더 나아질 방법을 되돌아보고, 그에 맞춰 행동을 조정한다는 것이다.","name":"Retro :: 뒤로\nSpect :: 보다\n= 붙여 읽으면 \"뒤를 보다\". 다만 보고 끝내는 자리가 아니라 바꿀 것을 하나 들고 나오는 자리다","analogy":"경기가 끝나면 선수들이 모여 다음 경기에 바꿀 한 가지를 정하고 흩어지는 그 자리다.","example":"수련회 마지막 날 좋았던 점과 아쉬운 점을 칠판에 적고 다음에 할 것을 정하던 그 시간이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"이 자리가 헛돌고 있는지도 셀 수 있다. 지침이 정해 준 산식은 없지만, 고른 개선을 다음 바퀴의 할 일 목록에 넣을 수 있다고 적어 두었으니 거기서 셀 것이 하나 나온다. **다음 바퀴 목록에 실제로 올라간 개선 수 ÷ 그 회고에서 하기로 정한 개선 수**다.\n\n이 값이 거짓말하는 자리는 분모다. 그 자리에서 나온 말을 전부 분모에 넣으면 값은 늘 바닥이고, 하기로 고른 것만 넣으면 늘 100%가 나온다. 그래서 회고 끝에 \"하기로 정한 것\" 을 몇 개인지 적어 두는 일 자체가 이 숫자를 만든다.\n\n분자도 흔들린다. 목록에 올리는 것과 실제로 끝내는 것은 다른 일이라, 올린 수만 세면 매 바퀴 개선이 쌓이는 것처럼 보이는데 실제로는 같은 항목이 계속 넘어가고 있을 수 있다. 세 바퀴 연속으로 같은 항목이 넘어가면 그 항목은 개선이 아니라 못 하는 일이라고 봐야 한다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 리뷰와 회고","body":"```도해\n대조: 리뷰와 회고는 무엇이 다른가\n리뷰 |=| 회고\n보는 대상 :: 만든 결과물 || 일한 방식\n부르는 사람 :: 밖의 이해관계자 || 팀 안 사람들\n나오는 것 :: 다음에 만들 것 || 다음에 바꿀 것\n= 하나는 제품을 고치고 하나는 만드는 방식을 고친다\n```\n\n둘은 한 주기의 마지막에 나란히 붙어 있다. 리뷰는 이해관계자와 함께 이번에 나온 결과를 살펴 다음에 무엇을 만들지를 정하고, 회고는 그다음에 팀끼리 모여 만드는 방식을 손본다. 한 자리에서 두 가지를 같이 하면 대개 제품 이야기만 남는다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **2주마다 한 시간** — 주기 마지막 날 한 시간을 잡고, 그 자리에서 다음 바퀴에 바꿀 것을 정해 할 일 목록에 올린다.\n- **완료 정의 손보기** — \"끝났다\" 의 조건이 매번 안 지켜졌다면 조건을 고치거나 한 바퀴에 담는 양을 줄인다.\n- **개선이 실린 비율 세기** — 지난 회고에서 정한 것 중 다음 목록에 실제로 올라간 수를 세어 둔다. 세 번 연속 0이면 자리 자체가 헛돌고 있는 것이다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **회고는 잘잘못을 가리는 자리다** — 가리는 것은 사람이 아니라 어긋난 판단이 어디서 왔는지다. 사람 이름을 부르기 시작하면 다음부터 아무도 사실을 안 꺼낸다.\n- **회고를 하면 팀이 알아서 좋아진다** — 자리만으로는 아무것도 안 바뀐다. 고른 개선이 다음 바퀴의 할 일 목록에 실제로 들어가야 바뀐다.\n- **바쁘면 이번 한 번은 건너뛰어도 된다** — 건너뛴 바퀴의 문제는 사라지지 않고 다음 바퀴로 넘어간다. 지침은 이 자리를 주기를 닫는 행사로 못 박아 두었다."}],"figure":"```도해\n흐름: 회고 한 자리에서 무엇을 하고 나오나\n지난 바퀴 :: 실제로 있었던 일을 늘어놓는다\n잘된 것 :: 어디서 잘 굴러갔는지 짚는다\n막힌 것 :: 어디서 걸렸고 그 판단이 어디서 왔는지 캔다\n고칠 것 :: 다음 바퀴에 바꿀 것을 골라 정한다\n@ 다음 회고 :: 그 바꾼 것이 먹혔는지 다음 자리에서 본다\n= 돌아보는 것으로 끝나지 않고 바꿀 것 하나를 들고 나온다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 일하는 방식을 따로 손보지 않으면 어떻게 되나\n자리가 없으면 || 회고를 두면\n같은 문제 :: 매번 되풀이된다 || 원인을 캔다\n불만 :: 뒤에서 돈다 || 그 자리에 놓인다\n바꾸는 시점 :: 아무도 안 정한다 || 다음 바퀴에 넣는다\n= 제품만 고치면 만드는 방식은 그대로 남는다\n```\n\n만든 것이 잘 나왔는지는 누구나 본다. 그런데 그것을 만드느라 팀이 어떻게 일했는지는 아무 자리에서도 안 다뤄진다. 그러면 같은 실수가 다음 바퀴에 그대로 되풀이되고, 불만은 회의실 밖에서만 돌게 된다.\n\n회고는 그것을 다루는 자리를 일정 안에 못 박는다. 스크럼 지침은 여기서 볼 것을 사람, 서로 주고받은 것, 일하는 절차, 쓰는 도구, 그리고 완료 정의라고 적는다. 어긋난 판단이 어디서 왔는지를 캐고, 가장 도움이 될 변화를 골라 되도록 빨리 손을 댄다. 고른 개선은 다음 바퀴의 할 일 목록에 넣어도 된다."},"recap":"**\"지난 한 바퀴에서 바꿀 것 하나를 정하고 나오는 그 자리\"** 라고 읽으면 된다. 제품이 아니라 만드는 방식을 다루는 자리이고, 정한 것이 다음 바퀴의 할 일 목록에 실제로 들어갔는지가 이 자리의 값을 말한다.","kid":"경기가 끝나면 선수들이 둘러앉아서 방금 뭐가 잘 됐고 뭐에 걸렸는지 이야기하지? 그러고 나서 다음 경기에 바꿀 걸 딱 하나 정해. 다음에 또 모였을 때는 그 하나가 정말 통했는지부터 봐.","check":[{"q":"리뷰에서 다루는 것과 이 자리에서 다루는 것은 어떻게 다른가","at":"비교"},{"q":"회고를 열 번 했는데도 일하는 방식이 그대로인 팀은 무엇을 빠뜨렸나","at":"흔한 오해"},{"q":"이 자리가 헛돌고 있는지를 무슨 숫자로 잡아 보나","at":"작동 원리"}],"myths":[{"wrong":"회고는 잘잘못을 가리는 자리다","right":"가리는 것은 사람이 아니라 어긋난 판단이 어디서 왔는지다. 사람 이름을 부르기 시작하면 다음부터 아무도 사실을 안 꺼낸다."},{"wrong":"회고를 하면 팀이 알아서 좋아진다","right":"자리만으로는 아무것도 안 바뀐다. 고른 개선이 다음 바퀴의 할 일 목록에 실제로 들어가야 바뀐다."},{"wrong":"바쁘면 이번 한 번은 건너뛰어도 된다","right":"건너뛴 바퀴의 문제는 사라지지 않고 다음 바퀴로 넘어간다. 지침은 이 자리를 주기를 닫는 행사로 못 박아 두었다."}],"cases":[{"label":"2주마다 한 시간","note":"주기 마지막 날 한 시간을 잡고, 그 자리에서 다음 바퀴에 바꿀 것을 정해 할 일 목록에 올린다."},{"label":"완료 정의 손보기","note":"\"끝났다\" 의 조건이 매번 안 지켜졌다면 조건을 고치거나 한 바퀴에 담는 양을 줄인다."},{"label":"개선이 실린 비율 세기","note":"지난 회고에서 정한 것 중 다음 목록에 실제로 올라간 수를 세어 둔다. 세 번 연속 0이면 자리 자체가 헛돌고 있는 것이다."}],"dia":{"shape":"흐름","title":"회고 한 자리에서 무엇을 하고 나오나","rows":[{"who":"지난 바퀴","what":"실제로 있었던 일을 늘어놓는다"},{"who":"잘된 것","what":"어디서 잘 굴러갔는지 짚는다"},{"who":"막힌 것","what":"어디서 걸렸고 그 판단이 어디서 왔는지 캔다"},{"who":"고칠 것","what":"다음 바퀴에 바꿀 것을 골라 정한다"}],"sum":"돌아보는 것으로 끝나지 않고 바꿀 것 하나를 들고 나온다","loop":{"who":"다음 회고","what":"그 바꾼 것이 먹혔는지 다음 자리에서 본다"}}},"pm--scrum":{"definition":"시작할 때 전부 정해놓고 끝까지 그대로 만드는 대신, 몇 주 단위로 끊어서 만들고 보여주고 고친다. 애자일이라는 생각을 실제 일정과 자리로 옮긴 형태다.","name":"= 럭비에서 양 팀이 어깨를 맞대고 공을 다시 넣는 그 뭉침. 한 덩어리로 붙어서 함께 민다는 뜻을 가져왔다","analogy":"요리하면서 중간에 맛을 본다. 다 끓이고 나서 짠 걸 아는 것보다 낫다.","example":"온라인 게임의 패치 공지가 격주 목요일처럼 정해진 날에 꼬박꼬박 올라온다. 그 정해진 한 바퀴가 이 방식의 단위다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"역할이 셋으로 나뉜다. 무엇을 먼저 만들지 정하는 사람, 팀이 일하는 방식을 돌보고 막힌 것을 치우는 사람, 실제로 만드는 팀이다. 무엇을 만들지와 어떻게 만들지를 다른 사람이 맡는 것이 이 구분의 뜻이다.\n\n```도해\n층: 할 일 목록은 어떤 단위로 쪼개지나\n제품 백로그 :: 만들 것 전부. 우선순위 순으로 쌓인다\n스프린트 백로그 :: 이번 주기에 하기로 한 것만 내려온다\n작업 :: 하루 안에 손댈 수 있는 크기로 다시 쪼갠다\n= 아래로 내려올수록 범위가 좁아지고 대신 확정된다\n```"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **2주 주기 개발** — 격주 금요일에 결과를 보여주고 다음 주 월요일에 다음 주기를 시작한다.\n- **급한 요청 처리** — 주기 중에 들어온 요청을 목록 맨 앞에 놓고 다음 주기에 먼저 집는다.\n- **회고에서 나온 변경** — 매일 모이는 시간이 길어진다는 말이 나오면 그 자리에서 규칙을 바꾼다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **스크럼을 하면 계획을 안 세운다** — 오히려 자주 세운다. 한 번에 멀리까지 세우는 대신 주기마다 다시 세우는 것이다.\n- **매일 모이는 자리는 진행 보고 시간이다** — 관리자에게 보고하는 자리가 아니라 막힌 것을 꺼내 서로 치우는 자리다. 보고가 되면 길어지고 사람이 빠지기 시작한다.\n- **주기 도중에도 일을 계속 넣을 수 있다** — 넣으면 그 주기에 하기로 한 것이 밀린다. 급한 일은 다음 주기 맨 앞에 놓는 것이 원칙이다."}],"figure":"```도해\n흐름: 스프린트 한 번은 어떻게 돌아가나\n계획 :: 목록에서 이번에 할 것만 골라 담는다\n개발 :: 정해진 기간 동안 범위를 고정하고 만든다\n매일 :: 짧게 모여 막힌 것을 꺼낸다\n리뷰 :: 만든 것을 실제로 보여주고 의견을 받는다\n회고 :: 일하는 방식에서 고칠 것을 정한다\n@ 계획 :: 받은 의견을 목록에 넣고 다음 주기를 연다\n= 제품과 일하는 방식을 같은 주기로 함께 고친다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 처음에 전부 정하고 끝까지 만들면 어떻게 되나\n한 번에 만들면 || 스프린트로\n방향 확인 :: 다 만든 뒤에 || 몇 주마다\n요구 변경 :: 되돌리기 어렵다 || 다음 주기에 반영\n문제 발견 :: 막판에 몰린다 || 주기마다 나온다\n= 틀린 것을 언제 알게 되느냐가 갈린다\n```\n\n계획을 한 번에 세우면 그 계획이 맞았는지는 다 만든 뒤에야 알 수 있다. 중간에 요구가 바뀌어도 이미 짜인 일정 위에 얹기 어렵고, 문제는 대부분 마감 직전에 한꺼번에 드러난다.\n\n스크럼은 확인 지점을 앞으로 당긴다. 몇 주마다 쓸 수 있는 결과물을 내놓고 보여주니, 방향이 틀렸다면 그 주기만큼만 잃는다."},"recap":"**\"몇 주짜리 한 바퀴를 규칙으로 굳힌 그 틀\"** 이라고 읽으면 된다. 주기마다 범위를 고정하는 것과 회고로 일하는 방식까지 손보는 것이 이 방식의 뼈대다.","kid":"두 주에 한 번씩 국을 떠서 다 같이 맛보는 날을 아예 정해 두는 거야. 그 두 주 동안은 넣기로 한 재료만 넣고 중간에 새 재료를 끼워 넣지 않아. 맛을 본 뒤에는 국 맛만이 아니라 우리가 끓인 방법에서 뭘 고칠지도 같이 이야기해.","check":[{"q":"주기 도중에 새 요구가 들어오면 어디에 놓나","at":"실제 사례"},{"q":"리뷰에서 다루는 것과 회고에서 다루는 것은 어떻게 다른가","at":"그림"},{"q":"매일 모이는 자리가 길어진다면 무엇이 잘못된 것인가","at":"흔한 오해"}],"myths":[{"wrong":"스크럼을 하면 계획을 안 세운다","right":"오히려 자주 세운다. 한 번에 멀리까지 세우는 대신 주기마다 다시 세우는 것이다."},{"wrong":"매일 모이는 자리는 진행 보고 시간이다","right":"관리자에게 보고하는 자리가 아니라 막힌 것을 꺼내 서로 치우는 자리다. 보고가 되면 길어지고 사람이 빠지기 시작한다."},{"wrong":"주기 도중에도 일을 계속 넣을 수 있다","right":"넣으면 그 주기에 하기로 한 것이 밀린다. 급한 일은 다음 주기 맨 앞에 놓는 것이 원칙이다."}],"cases":[{"label":"2주 주기 개발","note":"격주 금요일에 결과를 보여주고 다음 주 월요일에 다음 주기를 시작한다."},{"label":"급한 요청 처리","note":"주기 중에 들어온 요청을 목록 맨 앞에 놓고 다음 주기에 먼저 집는다."},{"label":"회고에서 나온 변경","note":"매일 모이는 시간이 길어진다는 말이 나오면 그 자리에서 규칙을 바꾼다."}],"dia":{"shape":"흐름","title":"스프린트 한 번은 어떻게 돌아가나","rows":[{"who":"계획","what":"목록에서 이번에 할 것만 골라 담는다"},{"who":"개발","what":"정해진 기간 동안 범위를 고정하고 만든다"},{"who":"매일","what":"짧게 모여 막힌 것을 꺼낸다"},{"who":"리뷰","what":"만든 것을 실제로 보여주고 의견을 받는다"},{"who":"회고","what":"일하는 방식에서 고칠 것을 정한다"}],"sum":"제품과 일하는 방식을 같은 주기로 함께 고친다","loop":{"who":"계획","what":"받은 의견을 목록에 넣고 다음 주기를 연다"}}},"pm--sprint":{"definition":"보통 1주에서 4주 사이로 잡고 2주를 많이 쓴다. 기간이 먼저 정해져 있고 그 안에 무엇을 담을지를 나중에 고른다는 점이 보통의 일정 계획과 다르다.","name":"= 짧은 거리를 전력으로 달린다는 뜻. 다만 여기서 정해져 있는 건 속도가 아니라 달리는 시간이다","analogy":"잡지 마감. 다음 호 날짜가 정해져 있으니 그 안에 실을 것만 고르고, 못 실은 것은 다음 호로 넘긴다.","example":"업데이트 공지에 이번에 들어간 것만 적혀 있고 기다리던 기능은 다음으로 밀려 있을 때가 있다. 날짜 대신 담을 것을 덜어낸 것이다.","tryit":"이번 주에 할 일 다섯 개를 적고 금요일을 마감으로 못 박아 보라. 금요일이 가까워지면 미루는 대신 뺄 것을 고르게 된다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"기간과 목표와 범위 셋을 놓고 무엇을 고정할지 먼저 정한다. 기간은 2주로 두고 늘리지 않는다. 이번에 무엇을 낼지도 도중에 바꾸지 않는다. 셋 중 하나는 움직여야 하니 남는 것은 범위다. 안 되겠으면 날짜가 아니라 이번에 담을 것을 덜어낸다.\n\n한 바퀴가 끝날 때마다 끝낸 일의 양을 적어둔다. 지난 세 번이 20, 25, 23이었다면 다음에도 23쯤이 담을 수 있는 양이다. 이 숫자가 쌓일수록 계획이 희망이 아니라 관측에 가까워진다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **2주짜리 목표** — \"로그인이 되게 한다\"를 목표로 잡고 화면, 인증 API, 세션, 테스트까지 그 안에 넣는다.\n- **속도로 계획** — 지난 세 번에 20, 25, 23을 끝냈다면 다음 계획도 23 언저리로 잡는다.\n- **끼어든 요청** — 도중에 들어온 요구는 목록에 넣어두고 다음 계획 때 다른 것들과 같이 저울질한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **스프린트는 짧은 기간에 몰아서 끝내는 것이다** — 기간을 압축하는 게 아니라 기간을 고정하는 것이다. 안 들어가면 날짜를 미루는 대신 이번에 넣을 범위를 줄인다.\n- **스프린트가 끝나면 무조건 배포한다** — 배포 시점은 따로 정한다. 스프린트가 보장하는 것은 지금 상태로도 보여줄 수 있다는 데까지다.\n- **매일 하는 회의는 진행 보고 자리다** — 보고가 목적이면 관리자만 쓸모를 본다. 막힌 곳을 그날 드러내서 하루라도 빨리 치우려고 모이는 것이다."}],"figure":"```도해\n흐름: 스프린트 한 바퀴는 어떻게 도나\n계획 :: 목록에서 이번에 할 것만 꺼내 정한다\n개발 :: 정한 범위 안에서만 만든다\n매일 회의 :: 막힌 곳을 그날 드러낸다\n리뷰 :: 만든 것을 실제로 돌려 보여준다\n회고 :: 일하는 방식에서 고칠 것을 정한다\n@ 다음 바퀴 :: 고칠 점을 안고 같은 기간을 다시 돈다\n= 한 바퀴마다 쓸 수 있는 결과와 고칠 점이 같이 나온다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 기간을 안 끊고 계속 만들면 어떻게 되나\n기간 없이 || 스프린트로\n결과 확인 :: 다 끝나야 본다 || 2주마다 본다\n끼어든 요청 :: 그때그때 넣는다 || 다음 주기로\n남은 기간 :: 감으로 잡는다 || 지난 속도로\n= 끝을 정해두면 무엇을 뺄지 정하는 일이 따라온다\n```\n\n기간을 안 정하면 다 만들 때까지 아무도 결과를 못 본다. 그사이 요청이 계속 끼어들어 범위가 늘고, 언제 끝나는지 묻는 사람에게는 감으로 답하게 된다.\n\n스프린트는 끝을 먼저 박아둔다. 2주마다 실제로 도는 것을 보여주고, 도중에 들어온 요청은 다음 주기에서 다시 저울질한다. 매번 얼마나 끝냈는지가 쌓이면 다음에 얼마나 담을 수 있는지도 숫자로 잡힌다."},"recap":"**\"끝나는 날을 먼저 못 박아 둔 그 한 바퀴\"** 라고 읽으면 된다. 안 들어가면 기간이 아니라 범위를 줄이고, 매번 얼마나 끝냈는지가 다음 계획의 근거가 된다.","kid":"학급 신문을 매달 첫째 주 금요일에 꼭 낸다고 정해 두면 글이 다 안 모여도 그날은 내야 하지? 그러면 날짜를 미루는 대신 이번에 실을 글을 줄이고 남은 건 다음 호로 넘겨. 그리고 매번 몇 편이나 실렸는지 세어 두면 다음 달에 몇 편쯤 담을 수 있는지도 알게 돼.","check":[{"q":"2주 안에 다 못 끝낼 것 같을 때 기간과 범위 중 무엇을 움직이나","at":"작동 원리"},{"q":"다음 스프린트에 얼마나 담을지 정할 때 무엇을 보고 정하나","at":"실제 사례"},{"q":"스프린트 도중에 들어온 요청을 그 자리에서 넣지 않는 이유는","at":"해결하는 문제"}],"myths":[{"wrong":"스프린트는 짧은 기간에 몰아서 끝내는 것이다","right":"기간을 압축하는 게 아니라 기간을 고정하는 것이다. 안 들어가면 날짜를 미루는 대신 이번에 넣을 범위를 줄인다."},{"wrong":"스프린트가 끝나면 무조건 배포한다","right":"배포 시점은 따로 정한다. 스프린트가 보장하는 것은 지금 상태로도 보여줄 수 있다는 데까지다."},{"wrong":"매일 하는 회의는 진행 보고 자리다","right":"보고가 목적이면 관리자만 쓸모를 본다. 막힌 곳을 그날 드러내서 하루라도 빨리 치우려고 모이는 것이다."}],"cases":[{"label":"2주짜리 목표","note":"\"로그인이 되게 한다\"를 목표로 잡고 화면, 인증 API, 세션, 테스트까지 그 안에 넣는다."},{"label":"속도로 계획","note":"지난 세 번에 20, 25, 23을 끝냈다면 다음 계획도 23 언저리로 잡는다."},{"label":"끼어든 요청","note":"도중에 들어온 요구는 목록에 넣어두고 다음 계획 때 다른 것들과 같이 저울질한다."}],"dia":{"shape":"흐름","title":"스프린트 한 바퀴는 어떻게 도나","rows":[{"who":"계획","what":"목록에서 이번에 할 것만 꺼내 정한다"},{"who":"개발","what":"정한 범위 안에서만 만든다"},{"who":"매일 회의","what":"막힌 곳을 그날 드러낸다"},{"who":"리뷰","what":"만든 것을 실제로 돌려 보여준다"},{"who":"회고","what":"일하는 방식에서 고칠 것을 정한다"}],"sum":"한 바퀴마다 쓸 수 있는 결과와 고칠 점이 같이 나온다","loop":{"who":"다음 바퀴","what":"고칠 점을 안고 같은 기간을 다시 돈다"}}},"pm--story-point":{"definition":"스크럼 지침은 백로그 항목에 크기를 붙이라고만 하고 그 단위를 정해 주지 않는다. 정해 둔 것은 그 일을 할 사람들이 크기를 매긴다는 것뿐이다. 스토리 포인트는 그 빈칸을 채우는 흔한 단위 하나이고, 시간이 아니라 서로 견준 값이라는 점이 여느 견적과 다르다.","name":"Story :: 사용자 쪽에서 본 일감\nPoint :: 크기를 세는 눈금\n= 붙여 읽으면 \"일감 하나의 크기 눈금\". 시간 단위가 아니라는 것이 이름에 이미 들어 있다","analogy":"이삿짐 상자에 몇 분 걸릴지 대신 큰 것 · 중간 것 · 작은 것 표를 붙여 두는 일이다.","example":"일감 카드에 1, 2, 3, 5, 8 같은 숫자가 붙어 있는데 그게 시간이 아니라는 말을 듣고 어리둥절했던 그 순간이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"매기는 법은 견주기다. 팀이 아는 항목 하나를 기준으로 삼고 나머지를 그것과 견줘 값을 붙인다. 눈금은 2의 배수나 피보나치처럼 값이 띄엄띄엄한 것을 쓴다. 도구 문서도 이 값을 다른 항목과 견준 상대 크기에 대한 팀의 짐작이라고 적는다.\n\n이 값이 계획에 쓰이는 자리는 하나다. **속도 = 그 한 바퀴 안에 끝난 항목들의 점수 합**이다. 지난 세 바퀴가 25, 30, 28이었다면 평균 28쯤이 다음 바퀴에 담을 양의 근거가 된다.\n\n이 산식이 거짓말하는 자리는 넷이다.\n\n- **분자** — \"끝났다\" 의 선이 없으면 점수는 얼마든지 붙는다. 통과한 것만 세고 반쯤 된 것은 0으로 센다.\n- **어느 바퀴에 세느냐** — 1번 바퀴에 담았다가 3번 바퀴에 끝난 항목의 점수는 3번 바퀴로 간다. 계획 대비로 읽으면 두 바퀴가 다 이상해 보인다.\n- **분모** — 바퀴 길이가 다르면 합끼리 견줄 수 없다. 길이를 같게 두는 것이 이 숫자의 전제다.\n- **팀 밖** — 눈금이 팀마다 다르므로 다른 팀의 합과 나란히 놓을 수 없다. 도구 문서도 이 값을 성과 지표와 혼동하지 말라고 적는다.\n\n항목 크기가 들쭉날쭉해도 값이 흔들린다. 크기 편차를 줄일수록 이 숫자와 그것으로 만든 예측이 믿을 만해진다고 문서가 직접 권한다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **다음 바퀴에 담을 양 정하기** — 지난 세 바퀴의 합이 25, 30, 28이면 다음에도 28 언저리를 담는다.\n- **너무 큰 항목 찾기** — 눈금에서 가장 큰 값이 붙은 항목만 골라 한 바퀴에 들어갈 크기로 쪼갠다.\n- **끝난 것만 세기** — 바퀴가 끝날 때 못 끝낸 항목은 점수를 반만 주지 않고 그대로 목록에 돌려보낸다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **1점을 몇 시간으로 정해 두면 편하다** — 시간으로 바꿔 적는 순간 이 값이 하려던 일이 없어진다. 문서가 적어 둔 것은 다른 항목과 견준 상대 크기이지 걸리는 시간이 아니다.\n- **속도가 높은 팀이 일을 잘하는 팀이다** — 눈금이 팀마다 달라 합끼리 견줄 수 없다. 이 값을 성과 지표와 혼동하지 말라는 경고가 도구 문서에도 그대로 붙어 있다.\n- **일감마다 점수를 매기는 게 언제나 낫다** — 끝난 개수를 세는 것도 같은 자리에 쓸 수 있다. 항목 크기를 고르게 맞출 수 있는 팀은 개수 세기가 더 간단하고 눈금 다툼도 없다."}],"figure":"```도해\n대조: 스토리 포인트는 시간 견적과 무엇이 다른가\n시간 견적 |=| 스토리 포인트\n적는 것 :: 걸리는 시간 || 서로 견준 크기\n쓰는 눈금 :: 시·일 단위 || 2배수나 피보나치\n계획에 쓰는 법 :: 그 값을 더한다 || 지난 합으로 잰다\n= 절대 시간이 아니라 서로 견준 크기라, 그 팀의 지난 기록과만 짝이 된다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 일감 크기를 아무도 안 적어 두면 어떻게 되나\n크기가 없으면 || 크기를 적으면\n담을 양 정하기 :: 감으로 정한다 || 지난 합을 본다\n쪼갤 것 고르기 :: 눈에 안 띈다 || 큰 값이 튄다\n남은 기간 답하기 :: 희망을 말한다 || 기록을 말한다\n= 지나간 것만이 앞을 내다보는 근거가 된다\n```\n\n이번 바퀴에 얼마나 담을지는 매번 정해야 하는데, 크기를 아무 데도 안 적어 두면 그 판단의 근거가 사람의 자신감밖에 없다. 자신감은 매번 달라지고, 커다란 항목 하나가 통째로 숨어 있어도 목록만 봐서는 안 보인다.\n\n크기를 적어 두면 근거가 기록으로 바뀐다. 스크럼 지침도 지난 성과와 앞으로의 여력과 완료 정의를 알 때 계획에 대한 확신이 생긴다고 적고, 복잡한 환경에서는 앞으로 무슨 일이 일어날지 알 수 없으니 이미 일어난 것만이 앞을 내다보는 판단의 재료가 된다고 못 박는다."},"recap":"**\"시간이 아니라 서로 견준 덩치를 적은 그 숫자\"** 라고 읽으면 된다. 이 값이 뜻을 갖는 자리는 같은 팀이 같은 길이의 바퀴에서 끝낸 것만 더한 합 하나다. 그 밖으로 나가면 숫자는 남고 뜻은 사라진다.","kid":"짐 상자가 몇 분 만에 옮겨질지는 몰라도 이 상자가 저 상자보다 두 배쯤 크다는 건 알겠지? 일도 그렇게 서로 견줘서 큰 것 작은 것 표를 붙여 둬. 지난번에 옮긴 표 숫자를 다 더해 보면 이번에 얼마나 옮길 수 있는지 짐작이 돼.","check":[{"q":"크기를 아무도 안 적어 두면 이번에 담을 양을 무엇으로 정하게 되나","at":"해결하는 문제"},{"q":"1번 바퀴에 담았다가 3번 바퀴에 끝난 항목의 점수는 어디에 세나","at":"작동 원리"},{"q":"다른 팀의 합과 우리 팀의 합을 나란히 놓으면 안 되는 이유는","at":"흔한 오해"}],"myths":[{"wrong":"1점을 몇 시간으로 정해 두면 편하다","right":"시간으로 바꿔 적는 순간 이 값이 하려던 일이 없어진다. 문서가 적어 둔 것은 다른 항목과 견준 상대 크기이지 걸리는 시간이 아니다."},{"wrong":"속도가 높은 팀이 일을 잘하는 팀이다","right":"눈금이 팀마다 달라 합끼리 견줄 수 없다. 이 값을 성과 지표와 혼동하지 말라는 경고가 도구 문서에도 그대로 붙어 있다."},{"wrong":"일감마다 점수를 매기는 게 언제나 낫다","right":"끝난 개수를 세는 것도 같은 자리에 쓸 수 있다. 항목 크기를 고르게 맞출 수 있는 팀은 개수 세기가 더 간단하고 눈금 다툼도 없다."}],"cases":[{"label":"다음 바퀴에 담을 양 정하기","note":"지난 세 바퀴의 합이 25, 30, 28이면 다음에도 28 언저리를 담는다."},{"label":"너무 큰 항목 찾기","note":"눈금에서 가장 큰 값이 붙은 항목만 골라 한 바퀴에 들어갈 크기로 쪼갠다."},{"label":"끝난 것만 세기","note":"바퀴가 끝날 때 못 끝낸 항목은 점수를 반만 주지 않고 그대로 목록에 돌려보낸다."}],"dia":{"shape":"대조","title":"스토리 포인트는 시간 견적과 무엇이 다른가","rows":[{"who":"","what":"시간 견적 || 스토리 포인트","left":"시간 견적","right":"스토리 포인트","even":true},{"who":"적는 것","what":"걸리는 시간 || 서로 견준 크기","left":"걸리는 시간","right":"서로 견준 크기"},{"who":"쓰는 눈금","what":"시·일 단위 || 2배수나 피보나치","left":"시·일 단위","right":"2배수나 피보나치"},{"who":"계획에 쓰는 법","what":"그 값을 더한다 || 지난 합으로 잰다","left":"그 값을 더한다","right":"지난 합으로 잰다"}],"sum":"절대 시간이 아니라 서로 견준 크기라, 그 팀의 지난 기록과만 짝이 된다"}},"pm--user-story":{"definition":"기능을 기술 용어로 적는 대신 그것을 쓸 사람의 입장에서 적는다. 형식은 정해져 있다. 어떤 역할로서, 무엇을 하고 싶고, 그래서 무엇을 얻는지 세 줄이다.","name":"User :: 그것을 쓸 사람\nStory :: 겪는 이야기\n= 붙여 읽으면 \"쓸 사람이 겪는 이야기\". 명세서가 아니라 이야기라고 부른 데 뜻이 있다","analogy":"식당 메뉴판. 손님이 무엇을 원하는지까지만 적혀 있고 어떻게 조리할지는 주방이 정한다.","example":"앱 리뷰에 저장 기능을 넣어 달라고만 쓰는 사람과 지하철에서 읽으려고 그렇다고 쓰는 사람이 있다. 뒤쪽이 이 형식이다.","tryit":"아무 앱의 리뷰를 열어 무엇을 해 달라고만 쓴 글과 왜 필요한지까지 쓴 글을 하나씩 찾아 보라. 뒤쪽만 무엇을 만들지 정할 수 있다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"좋은 스토리인지 보는 기준을 INVEST라고 부른다. 다른 스토리를 기다리지 않아도 되고, 구현 방법이 열려 있고, 사용자에게 가치가 있고, 크기를 가늠할 수 있고, 한 스프린트에 들어갈 만큼 작고, 끝났는지 확인할 수 있어야 한다는 여섯 가지다.\n\n끝났는지 확인하는 부분은 인수 기준으로 따로 적는다. \"어떤 상태에서, 무엇을 하면, 어떻게 된다\"의 형태로 몇 줄 쓴다. 검색 스토리라면 검색어를 넣으면 관련 상품이 보인다, 결과가 없으면 없다는 안내가 나온다처럼 적는 식이다. 이게 있어야 스토리가 테스트 가능해진다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 요구를 적는 세 가지 방식","body":"| | User Story | Use Case | Requirement |\n|---|---|---|---|\n| 길이 | 세 줄 | 한두 쪽 | 여러 쪽 |\n| 보는 관점 | 사용자 | 시스템 흐름 | 기술 명세 |\n| 상세도 | 낮다 | 중간 | 높다 |\n| 바꾸기 | 쉽다 | 중간 | 어렵다 |\n| 쓰이는 곳 | 애자일 | 설계 단계 | 폭포수 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **장바구니 담기** — 여러 개를 한 번에 사려고 담아둔다는 이유를 적고, 개수 표시와 같은 상품 합치기를 인수 기준으로 붙인다.\n- **소셜 로그인** — 계정을 또 만들기 싫다는 이유가 적혀 있어서 어떤 방식으로 붙일지 팀이 고를 수 있다.\n- **비밀번호 재설정** — 잊어버려도 다시 들어올 수 있게 한다는 가치가 드러나 다른 요구와 우선순위를 비교할 수 있다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **형식만 지키면 좋은 스토리다** — \"개발자로서 캐시를 넣고 싶다\"도 형식은 맞지만 사용자에게 남는 가치가 없다. 기준은 형식이 아니라 누구에게 무엇이 남느냐다.\n- **스토리를 잘 쓰면 다른 문서가 필요 없다** — 스토리는 세부를 담지 않는다. 무엇이 되면 끝인지는 인수 기준으로 따로 적고 나머지는 대화에서 정해진다.\n- **화면과 버튼까지 적어줘야 개발이 빨라진다** — 구현 방법을 지정하면 팀이 더 나은 방법을 고를 여지가 사라진다. 무엇을 원하는지까지만 적는다."}],"figure":"```도해\n흐름: 한 줄짜리 요구가 개발까지 어떻게 이어지나\n역할 :: 누가 쓰는지 정한다. 출퇴근하는 직장인\n바람 :: 무엇을 하고 싶은지 적는다. 기사를 저장한다\n이유 :: 왜 필요한지 적는다. 지하철에서 읽으려고\n대화 :: 이 세 줄을 놓고 팀이 세부를 정한다\n인수 기준 :: 무엇이 되면 끝인지 함께 적어둔다\n= 세 줄은 답이 아니라 대화를 시작하는 자리다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 요구를 기술 용어로 적으면 무엇을 잃나\n기술로 적으면 || 스토리로 적으면\n읽는 사람 :: 왜 하는지 모름 || 목적이 보인다\n구현 방법 :: 이미 정해져 있음 || 팀이 정한다\n분량 :: 문서 백 쪽 || 세 줄\n= 무엇을 원하는지와 어떻게 만들지를 갈라놓는 장치다\n```\n\n\"OAuth 기반 인증을 붙인다\"라고 적힌 요구를 받으면 만드는 쪽은 왜 필요한지를 모른다. 목적을 모르면 판단할 수가 없어서, 더 간단한 방법이 있어도 제안하지 못하고 우선순위도 비교할 수 없다.\n\n같은 요구를 \"계정을 또 만들기 싫어서 쓰던 계정으로 가입하고 싶다\"로 적으면 목적이 드러난다. 여기서 팀은 어떤 방식이 그 목적에 맞는지 고를 수 있고, 다른 요구와 견줘 무엇을 먼저 할지 정할 수 있다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 요구는 어느 크기까지 쪼개져 내려오나\n에픽 :: 쇼핑몰을 만든다 급. 여러 스프린트에 걸친다\n스토리 :: 장바구니에 담는다. 한 스프린트 안에 끝난다\n작업 :: 버튼 붙이기, API 만들기. 개발자가 쪼갠 것\n= 스토리는 사용자에게 가치가 남는 가장 작은 단위다\n```"},"recap":"**\"쓸 사람 입장에서 세 줄로 적은 그 이야기\"** 라고 읽으면 된다. 세부를 다 담는 명세가 아니라 팀이 대화를 시작할 지점이고, 끝났는지는 인수 기준으로 따로 정한다. 한 스프린트에 들어가지 않을 만큼 크면 에픽이므로 더 쪼갠다.","kid":"식당에서 \"맵지 않게 해 주세요\"라고는 말해도 어느 냄비에 어떤 불로 익히라고까지는 안 하지? 원하는 것과 그 까닭까지만 말하면 주방이 제일 좋은 방법을 골라 줘. 처음부터 방법까지 시켜 버리면 더 나은 방법이 있어도 못 쓰게 돼.","check":[{"q":"\"개발자로서 캐시를 넣고 싶다\"가 좋은 스토리가 아닌 이유는","at":"흔한 오해"},{"q":"스토리에 버튼 위치까지 적으면 팀은 무엇을 잃게 되나","at":"해결하는 문제"},{"q":"한 스프린트에 못 끝낼 만큼 큰 요구는 무엇이라 부르고 어떻게 다루나","at":"구성"}],"myths":[{"wrong":"형식만 지키면 좋은 스토리다","right":"\"개발자로서 캐시를 넣고 싶다\"도 형식은 맞지만 사용자에게 남는 가치가 없다. 기준은 형식이 아니라 누구에게 무엇이 남느냐다."},{"wrong":"스토리를 잘 쓰면 다른 문서가 필요 없다","right":"스토리는 세부를 담지 않는다. 무엇이 되면 끝인지는 인수 기준으로 따로 적고 나머지는 대화에서 정해진다."},{"wrong":"화면과 버튼까지 적어줘야 개발이 빨라진다","right":"구현 방법을 지정하면 팀이 더 나은 방법을 고를 여지가 사라진다. 무엇을 원하는지까지만 적는다."}],"cases":[{"label":"장바구니 담기","note":"여러 개를 한 번에 사려고 담아둔다는 이유를 적고, 개수 표시와 같은 상품 합치기를 인수 기준으로 붙인다."},{"label":"소셜 로그인","note":"계정을 또 만들기 싫다는 이유가 적혀 있어서 어떤 방식으로 붙일지 팀이 고를 수 있다."},{"label":"비밀번호 재설정","note":"잊어버려도 다시 들어올 수 있게 한다는 가치가 드러나 다른 요구와 우선순위를 비교할 수 있다."}],"dia":{"shape":"흐름","title":"한 줄짜리 요구가 개발까지 어떻게 이어지나","rows":[{"who":"역할","what":"누가 쓰는지 정한다. 출퇴근하는 직장인"},{"who":"바람","what":"무엇을 하고 싶은지 적는다. 기사를 저장한다"},{"who":"이유","what":"왜 필요한지 적는다. 지하철에서 읽으려고"},{"who":"대화","what":"이 세 줄을 놓고 팀이 세부를 정한다"},{"who":"인수 기준","what":"무엇이 되면 끝인지 함께 적어둔다"}],"sum":"세 줄은 답이 아니라 대화를 시작하는 자리다"}},"pm--wireframe":{"definition":"무엇이 어디에 놓이고 무엇을 하는지만 회색 상자와 글자로 표시한다. 이미지도 색도 글꼴도 정하지 않기 때문에 몇 분 만에 그리고 그만큼 쉽게 버릴 수 있다.","name":"Wire :: 철사\nFrame :: 뼈대\n= 붙여 읽으면 \"철사로 짠 뼈대\". 살은 안 붙이고 뼈대만 세워 본다는 뜻이다","analogy":"건축 도면. 벽과 문의 위치만 그려져 있고 벽지 색이나 가구는 없다. 벽을 옮기자는 이야기는 도면 위에서 해야 싸다.","example":"회의에서 화이트보드에 네모 몇 개를 그려놓고 여기가 검색이고 여기가 목록이라고 짚어본 적이 있다. 그 낙서가 곧 이것이다.","tryit":"종이에 자주 쓰는 앱의 첫 화면을 네모와 글자만으로 1분 안에 그려 보라. 색 없이도 무엇을 하는 화면인지 통한다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n층: 와이어프레임은 어느 정도까지 그리나\n저해상도 :: 종이에 손으로. 몇 분이면 그린다\n중해상도 :: 도구로 실제 크기에 맞춰. 한 시간쯤\n고해상도 :: 눌러서 넘어가는 프로토타입까지. 하루쯤\n= 아래로 갈수록 정확해지고 그만큼 고치기 아까워진다\n```\n\n그리는 규칙이 몇 가지 있다. 이미지 자리는 회색 상자로만 두고 색과 글꼴은 손대지 않는다. 대신 문구는 실제로 쓸 것을 넣는다. 그래야 제목이 두 줄로 넘어가거나 버튼 안에 글자가 안 들어가는 문제가 그 자리에서 보인다.\n\n동작도 적어둔다. 그림만 있으면 같은 화면을 보고도 누른 뒤에 무슨 일이 일어나는지를 각자 다르게 상상한다. 검색창 옆에 세 글자부터 제안이 뜬다고 적어두는 식으로 옆에 짧게 붙인다. 화면 크기가 여럿이면 좁은 화면 것도 같이 그린다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **회의 전 종이 스케치** — 논의할 화면을 몇 분 만에 그려 놓고 그 위에서 이야기를 시작한다.\n- **화면 목록에서 빠진 것 찾기** — 전체 화면을 늘어놓으면 로그인이나 오류 화면처럼 빠뜨린 것이 드러난다.\n- **개발자에게 넘기는 주석** — 요소 옆에 언제 무엇이 일어나는지 적어 넘기면 다시 물어볼 일이 준다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **와이어프레임이 나오면 그대로 만들면 된다** — 뼈대까지만 정한 것이다. 그대로 개발로 넘기면 디자인 단계가 통째로 빠진 채 화면이 나온다.\n- **와이어프레임은 디자이너가 그려서 넘겨주는 것이다** — 혼자 완성해 넘기면 볼 사람의 의견이 빠진다. 기획과 디자인과 개발이 같이 그릴 때 빠진 화면과 만들기 어려운 동작이 미리 나온다.\n- **글자는 아무거나 채워 넣어도 된다** — 의미 없는 채움 글로 채우면 실제 문구의 길이를 못 본다. 제목이 몇 줄이 되는지, 목록 한 줄에 몇 글자가 들어가는지가 레이아웃을 바꾼다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **색과 글꼴을 정하기 시작하면 멈춘다.** 회색만 쓰는 이유는 구조 이야기가 색 이야기에 밀리지 않게 하려는 것이다.\n- **누른 뒤에 무슨 일이 일어나는지 반드시 적는다.** 이게 없으면 화면은 같아 보여도 동작을 각자 다르게 만든다."}],"figure":"```도해\n흐름: 와이어프레임 한 장은 어떤 순서로 만들어지나\n요소 모으기 :: 이 화면에 무엇이 들어가야 하는지 적는다\n자리 잡기 :: 회색 상자로 크기와 위치만 배치한다\n주석 달기 :: 누르면 어디로 가는지 옆에 적어둔다\n보여주기 :: 팀에 돌려 빠진 것과 어색한 곳을 듣는다\n@ 고치기 :: 지우고 다시 그린다. 몇 분이면 된다\n= 되돌리는 값이 쌀 때 어긋난 곳을 찾아내는 것이 목적이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 버튼 위치를 바꾸자는 말이 언제 나오면 싼가\n디자인부터 하면 || 먼저 그려보면\n고치는 비용 :: 며칠이 날아감 || 몇 분이면 끝\n팀의 그림 :: 각자 다르다 || 같은 것을 본다\n빠진 화면 :: 개발 중에 발견 || 미리 보인다\n= 어긋난 곳은 되돌리기 싼 단계에서 찾아야 한다\n```\n\n디자인을 3주 걸려 마친 뒤에야 버튼 위치가 이상하다는 말이 나오면 그 3주가 다시 든다. 같은 지적이 종이 스케치 단계에서 나왔다면 지우고 다시 그리는 데 몇 분이면 된다.\n\n말로만 정하면 각자 다른 그림을 상상하는 것도 문제다. \"여기에 검색 기능\"이라는 한마디를 두고 기획은 왼쪽 위를, 개발은 오른쪽 아래를 떠올린다. 화면을 한 장 그려 놓고 이야기하면 그 차이가 그 자리에서 드러나고, 전체 화면을 늘어놓으면 아예 빠뜨린 화면도 눈에 띈다."},"recap":"**\"색을 빼고 뼈대만 세워 본 그 밑그림\"** 이라고 읽으면 된다. 빨리 그리고 쉽게 버릴 수 있어서 되돌리는 값이 쌀 때 어긋난 곳을 찾아내는 데 쓴다. 디자인을 대신하지 않으며 여기서 합의한 구조 위에 디자인이 올라간다.","kid":"집을 지을 때 벽지 색을 고르기 전에 벽이랑 문 자리부터 종이에 그려 보지? 종이 위에서는 문을 옮기는 데 몇 분이면 되는데, 벽을 다 세운 뒤에 옮기려면 며칠이 걸려. 그래서 색칠은 뒤로 미루고 자리부터 맞춰 보는 거야.","check":[{"q":"디자인을 다 마친 뒤에 버튼 위치를 바꾸자는 말이 나오면 왜 비싼가","at":"해결하는 문제"},{"q":"실제 문구 대신 아무 글자로 채워 넣으면 무엇을 놓치게 되나","at":"흔한 오해"},{"q":"와이어프레임을 회색으로만 그리는 이유는","at":"주의사항"}],"myths":[{"wrong":"와이어프레임이 나오면 그대로 만들면 된다","right":"뼈대까지만 정한 것이다. 그대로 개발로 넘기면 디자인 단계가 통째로 빠진 채 화면이 나온다."},{"wrong":"와이어프레임은 디자이너가 그려서 넘겨주는 것이다","right":"혼자 완성해 넘기면 볼 사람의 의견이 빠진다. 기획과 디자인과 개발이 같이 그릴 때 빠진 화면과 만들기 어려운 동작이 미리 나온다."},{"wrong":"글자는 아무거나 채워 넣어도 된다","right":"의미 없는 채움 글로 채우면 실제 문구의 길이를 못 본다. 제목이 몇 줄이 되는지, 목록 한 줄에 몇 글자가 들어가는지가 레이아웃을 바꾼다."}],"cases":[{"label":"회의 전 종이 스케치","note":"논의할 화면을 몇 분 만에 그려 놓고 그 위에서 이야기를 시작한다."},{"label":"화면 목록에서 빠진 것 찾기","note":"전체 화면을 늘어놓으면 로그인이나 오류 화면처럼 빠뜨린 것이 드러난다."},{"label":"개발자에게 넘기는 주석","note":"요소 옆에 언제 무엇이 일어나는지 적어 넘기면 다시 물어볼 일이 준다."}],"dia":{"shape":"흐름","title":"와이어프레임 한 장은 어떤 순서로 만들어지나","rows":[{"who":"요소 모으기","what":"이 화면에 무엇이 들어가야 하는지 적는다"},{"who":"자리 잡기","what":"회색 상자로 크기와 위치만 배치한다"},{"who":"주석 달기","what":"누르면 어디로 가는지 옆에 적어둔다"},{"who":"보여주기","what":"팀에 돌려 빠진 것과 어색한 곳을 듣는다"}],"sum":"되돌리는 값이 쌀 때 어긋난 곳을 찾아내는 것이 목적이다","loop":{"who":"고치기","what":"지우고 다시 그린다. 몇 분이면 된다"}}}};
